export enum TransactionType {
  INCOME = 'INCOME',
  EXPENSE = 'EXPENSE',
  TRANSFER = 'TRANSFER',
}

export enum AccountType {
  MOMO = 'MoMo Receivables',
  CASH = 'Cash Receivables',
  OTHER = 'Others',
}

export interface Transaction {
  id: string;
  date: string; // ISO String YYYY-MM-DD
  type: TransactionType;
  category: string;
  amount: number;
  accountId: AccountType; // The main account involved
  toAccountId?: AccountType; // For transfers
  recipient?: string; // From/To
  notes?: string;
  isArchived: boolean;
  meta?: {
    receivedFromFinance?: boolean; // For MoMo expenses
    isPlan?: boolean; // If created from "Plan Next Week"
  };
}

export interface Category {
  id: string;
  name: string;
  type: 'INCOME' | 'EXPENSE' | 'BOTH';
}

export interface User {
  id: string;
  name: string;
  role: 'ADMIN' | 'VIEWER' | 'FINANCE_REP';
  phone: string;
  email: string;
}

export type Period = 'WEEK' | 'MONTH' | 'QUARTER' | 'YEAR';

export interface DashboardStats {
  income: number;
  expense: number;
  balance: number;
}

import { Transaction, TransactionType, AccountType, Category, User } from './types';
