        >
            User Management
        </button>
        <button 
            onClick={() => setActiveSection('ARCHIVE')}
            className={`w-full text-left px-4 py-2 rounded-lg transition-colors ${activeSection === 'ARCHIVE' ? 'bg-primary/10 text-primary font-medium' : 'text-gray-600 hover:bg-gray-50'}`}
        >
            Archived Records
        </button>
      </div>

      {/* Content */}
      <div className="flex-1 p-6">
        {activeSection === 'CATEGORIES' && (
            <div className="space-y-6">
