import React, { useState, useEffect } from 'react';
import { LayoutDashboard, Receipt, Settings as SettingsIcon, PieChart, Menu, X } from 'lucide-react';
import { Transaction, Category, User, AccountType } from './types';
import { INITIAL_TRANSACTIONS, INITIAL_CATEGORIES, INITIAL_USERS } from './utils';

import Overview from './components/Overview';
import Transactions from './components/Transactions';
import Reports from './components/Reports';
import Settings from './components/Settings';

function App() {
  // Global State
  const [transactions, setTransactions] = useState<Transaction[]>(INITIAL_TRANSACTIONS);
  const [categories, setCategories] = useState<Category[]>(INITIAL_CATEGORIES);
  const [users, setUsers] = useState<User[]>(INITIAL_USERS);
  const [activeView, setActiveView] = useState<'OVERVIEW' | 'TRANSACTIONS' | 'REPORTS' | 'SETTINGS'>('OVERVIEW');
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);

  // Filtering state lifted to App to allow Overview Cards to switch view
  const [preSelectedAccount, setPreSelectedAccount] = useState<AccountType | null>(null);

  const handleAccountFilter = (account: AccountType | null) => {
    setPreSelectedAccount(account);
    setActiveView('TRANSACTIONS');
  };

  const addTransaction = (t: Omit<Transaction, 'id'>) => {
    const newT = { ...t, id: Math.random().toString(36).substr(2, 9) };
    setTransactions(prev => [newT, ...prev]);
  };

  const deleteTransaction = (id: string) => {
    setTransactions(prev => prev.map(t => t.id === id ? { ...t, isArchived: true } : t));
  };

  const restoreTransaction = (id: string) => {
    setTransactions(prev => prev.map(t => t.id === id ? { ...t, isArchived: false } : t));
  };

  const addCategory = (c: Category) => {
    setCategories(prev => [...prev, c]);
  };

  const deleteCategory = (id: string) => {
    setCategories(prev => prev.filter(c => c.id !== id));
  };

  // Navigation Items
  const navItems = [
    { id: 'OVERVIEW', label: 'Overview', icon: LayoutDashboard },
    { id: 'TRANSACTIONS', label: 'Transactions', icon: Receipt },
    { id: 'REPORTS', label: 'Generate Reports', icon: PieChart },
    { id: 'SETTINGS', label: 'Settings', icon: SettingsIcon },
  ];

  return (
    <div className="flex min-h-screen bg-gray-50 font-sans text-gray-900">

      {/* Sidebar (Desktop) */}
      <aside className="hidden md:flex w-64 flex-col bg-white border-r border-gray-200 fixed h-full z-10">
        <div className="p-6 border-b border-gray-100">
          <h1 className="text-xl font-bold text-primary leading-tight">Thesaurus<br/><span className="text-gray-600 text-sm font-normal">Children's Finance</span></h1>
        </div>
        <nav className="flex-1 p-4 space-y-2">
          {navItems.map(item => (
            <button
