import React, { useState, useEffect } from 'react';
import { Transaction, TransactionType, AccountType, Category } from '../types';
import { formatCurrency } from '../utils';
import { Search, Plus, Save, X, Archive, ArrowRight } from 'lucide-react';

interface TransactionsProps {
  transactions: Transaction[];
  categories: Category[];
  accounts: AccountType[];
  preSelectedAccount: AccountType | null;
  onAddTransaction: (t: Omit<Transaction, 'id'>) => void;
  onDeleteTransaction: (id: string) => void;
}

type TabType = 'INCOME' | 'EXPENSE' | 'TRANSFER';

const Transactions: React.FC<TransactionsProps> = ({ 
  transactions, 
  categories, 
  accounts, 
  preSelectedAccount,
  onAddTransaction,
  onDeleteTransaction
}) => {
  const [activeTab, setActiveTab] = useState<TabType>('INCOME');
  const [filterAccount, setFilterAccount] = useState<string>(preSelectedAccount || 'ALL');
  const [searchTerm, setSearchTerm] = useState('');

  const [entries, setEntries] = useState<any[]>([{ 
    amount: '', 
    date: new Date().toISOString().split('T')[0],
    category: '',
    accountId: '',
    toAccountId: '',
    recipient: '',
    notes: '',
    receivedFromFinance: false
  }]);

  useEffect(() => {
    if (preSelectedAccount) setFilterAccount(preSelectedAccount);
  }, [preSelectedAccount]);

  const handleAddEntry = () => {
    setEntries([...entries, { 
      amount: '', 
      date: new Date().toISOString().split('T')[0],
      category: '',
      accountId: '',
      toAccountId: '',
      recipient: '',
      notes: '',
      receivedFromFinance: false
    }]);
  };

  const handleRemoveEntry = (index: number) => {
    if (entries.length > 1) {
      setEntries(entries.filter((_, i) => i !== index));
    }
  };

  const updateEntry = (index: number, field: string, value: any) => {
    const newEntries = [...entries];
    newEntries[index] = { ...newEntries[index], [field]: value };
    setEntries(newEntries);
  };

  const validateAndSave = () => {
    for (const entry of entries) {
      if (!entry.amount || Number(entry.amount) <= 0) {
        alert('Please enter a valid amount.');
        return;
      }
      if (!entry.date) {
        alert('Please select a date.');
        return;
      }
      if (activeTab !== 'TRANSFER' && !entry.category) {
        alert('Please select a category.');
        return;
      }
      if (!entry.accountId) {
        alert('Please select an account.');
        return;
      }
      if (activeTab === 'TRANSFER' && !entry.toAccountId) {
         alert('Please select a destination account.');
         return;
      }
    }

    entries.forEach(entry => {
      onAddTransaction({
        date: entry.date,
        amount: Number(entry.amount),
        type: activeTab === 'INCOME' ? TransactionType.INCOME : activeTab === 'EXPENSE' ? TransactionType.EXPENSE : TransactionType.TRANSFER,
        category: activeTab === 'TRANSFER' ? 'Finance Transfer' : entry.category,
        accountId: entry.accountId,
        toAccountId: activeTab === 'TRANSFER' ? entry.toAccountId : undefined,
        recipient: entry.recipient,
        notes: entry.notes,
        isArchived: false,
        meta: {
            receivedFromFinance: entry.receivedFromFinance
        }
      });
    });

    setEntries([{ 
      amount: '', 
      date: new Date().toISOString().split('T')[0],
      category: '',
      accountId: '',
      toAccountId: '',
      recipient: '',
      notes: '',
      receivedFromFinance: false
    }]);
    alert('Transaction(s) saved successfully!');
  };

  const filteredList = transactions
    .filter(t => !t.isArchived)
    .filter(t => filterAccount === 'ALL' || t.accountId === filterAccount || t.toAccountId === filterAccount)
    .filter(t => 
      t.category.toLowerCase().includes(searchTerm.toLowerCase()) || 
      t.notes?.toLowerCase().includes(searchTerm.toLowerCase()) ||
      t.recipient?.toLowerCase().includes(searchTerm.toLowerCase())
    )
    .sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());

  return (
    <div className="space-y-6">
      <div className="bg-white rounded-xl shadow-sm border border-gray-200 overflow-hidden">
        {/* Form Tabs */}
        <div className="flex border-b border-gray-100 overflow-x-auto no-scrollbar">
          {(['INCOME', 'EXPENSE', 'TRANSFER'] as TabType[]).map(tab => (
            <button
              key={tab}
              onClick={() => setActiveTab(tab)}
              className={`flex-1 min-w-[100px] py-4 text-sm font-semibold tracking-wide transition-colors whitespace-nowrap ${
                activeTab === tab 
                  ? tab === 'INCOME' ? 'bg-emerald-50 text-emerald-700 border-b-2 border-emerald-500' 
                    : tab === 'EXPENSE' ? 'bg-rose-50 text-rose-700 border-b-2 border-rose-500'
                    : 'bg-blue-50 text-blue-700 border-b-2 border-blue-500'
                  : 'text-gray-500 hover:bg-gray-50'
              }`}
            >
              {tab}
            </button>
          ))}
        </div>

        {/* Form Body */}
        <div className="p-4 sm:p-6">
          <div className="space-y-6">
            {entries.map((entry, index) => (
              <div key={index} className="relative p-4 bg-gray-50 rounded-lg border border-gray-200 space-y-4">
                {entries.length > 1 && (
                    <button onClick={() => handleRemoveEntry(index)} className="absolute top-2 right-2 text-red-400 hover:text-red-600 z-10 p-1 bg-white rounded-full shadow-sm">
                        <X size={16} />
                    </button>
                )}

                <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
                  <div>
                    <label className="block text-xs font-medium text-gray-500 mb-1">Date</label>
                    <input 
                        type="date" 
                        value={entry.date}
                        onChange={(e) => updateEntry(index, 'date', e.target.value)}
                        className="w-full rounded-md border-gray-300 shadow-sm focus:ring-primary focus:border-primary p-2 border text-sm"
                    />
                  </div>

                  <div>
                    <label className="block text-xs font-medium text-gray-500 mb-1">Value (GHC)</label>
                    <input 
                        type="number" 
                        placeholder="0.00"
                        value={entry.amount}
                        onChange={(e) => updateEntry(index, 'amount', e.target.value)}
                        className="w-full rounded-md border-gray-300 shadow-sm focus:ring-primary focus:border-primary p-2 border text-sm"
                    />
                  </div>

                  {activeTab !== 'TRANSFER' && (
                    <div className="sm:col-span-2">
                        <label className="block text-xs font-medium text-gray-500 mb-1">Category</label>
                        <select 
                            value={entry.category}
                            onChange={(e) => updateEntry(index, 'category', e.target.value)}
                            className="w-full rounded-md border-gray-300 shadow-sm focus:ring-primary focus:border-primary p-2 border text-sm"
                        >
                            <option value="">Select Category...</option>
                            {categories
                                .filter(c => c.type === 'BOTH' || c.type === activeTab)
                                .map(c => <option key={c.id} value={c.name}>{c.name}</option>)}
                        </select>
                    </div>
                  )}
                </div>

                <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                   <div>
                        <label className="block text-xs font-medium text-gray-500 mb-1">
                            {activeTab === 'TRANSFER' ? 'From Account' : 'Account'}
                        </label>
                        <select 
                            value={entry.accountId}
                            onChange={(e) => updateEntry(index, 'accountId', e.target.value)}
                            className="w-full rounded-md border-gray-300 shadow-sm focus:ring-primary focus:border-primary p-2 border text-sm"
                        >
                            <option value="">Select Account...</option>
                            {accounts.map(a => <option key={a} value={a}>{a}</option>)}
                        </select>

                        {activeTab === 'EXPENSE' && entry.accountId === AccountType.MOMO && (
                            <div className="mt-3 flex items-start">
                                <input 
                                    type="checkbox" 
                                    id={`finance-check-${index}`}
                                    checked={entry.receivedFromFinance}
                                    onChange={(e) => updateEntry(index, 'receivedFromFinance', e.target.checked)}
                                    className="mt-0.5 h-4 w-4 text-primary focus:ring-primary border-gray-300 rounded"
                                />
                                <label htmlFor={`finance-check-${index}`} className="ml-2 block text-xs text-red-600 font-medium leading-tight">
                                    Was this digital cash received from Finance? (Mandatory)
                                </label>
                            </div>
                        )}
                   </div>

                   {activeTab === 'TRANSFER' ? (
                       <div>
                            <label className="block text-xs font-medium text-gray-500 mb-1">To Account</label>
                            <select 
                                value={entry.toAccountId}
                                onChange={(e) => updateEntry(index, 'toAccountId', e.target.value)}
                                className="w-full rounded-md border-gray-300 shadow-sm focus:ring-primary focus:border-primary p-2 border text-sm"
                            >
                                <option value="">Select Account...</option>
                                {accounts.map(a => <option key={a} value={a}>{a}</option>)}
                            </select>
                       </div>
                   ) : (
                       <div>
                           <label className="block text-xs font-medium text-gray-500 mb-1">From/To (Optional)</label>
                           <input 
                                type="text"
                                placeholder="Recipient Name"
                                value={entry.recipient}
                                onChange={(e) => updateEntry(index, 'recipient', e.target.value)}
                                className="w-full rounded-md border-gray-300 shadow-sm focus:ring-primary focus:border-primary p-2 border text-sm"
                            />
                       </div>
                   )}
                </div>

                <div>
                    <label className="block text-xs font-medium text-gray-500 mb-1">Notes (Optional)</label>
                    <textarea 
                        rows={2}
                        value={entry.notes}
                        onChange={(e) => updateEntry(index, 'notes', e.target.value)}
                        className="w-full rounded-md border-gray-300 shadow-sm focus:ring-primary focus:border-primary p-2 border text-sm"
                        placeholder="Add details here..."
                    />
                </div>
              </div>
            ))}

            <div className="flex flex-col sm:flex-row justify-between items-center gap-4">
                <button 
                    onClick={handleAddEntry}
                    className="w-full sm:w-auto flex items-center justify-center text-sm font-medium text-primary hover:text-teal-800 p-2"
                >
                    <Plus size={16} className="mr-1" /> Add another entry
                </button>
                <button 
                    onClick={validateAndSave}
                    className={`w-full sm:w-auto flex items-center justify-center px-6 py-2.5 rounded-lg text-white font-medium shadow-sm transition-colors ${
                        activeTab === 'INCOME' ? 'bg-emerald-600 hover:bg-emerald-700' 
                        : activeTab === 'EXPENSE' ? 'bg-rose-600 hover:bg-rose-700' 
                        : 'bg-blue-600 hover:bg-blue-700'
                    }`}
                >
                    <Save size={18} className="mr-2" /> Save Transaction
                </button>
            </div>
          </div>
        </div>
      </div>

      {/* Transaction List */}
      <div className="bg-white rounded-xl shadow-sm border border-gray-200">
        <div className="p-4 border-b border-gray-100 flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
            <h3 className="font-bold text-gray-800">History</h3>
            <div className="flex flex-col sm:flex-row gap-2 w-full md:w-auto">
                <div className="relative flex-1">
                    <Search className="absolute left-2 top-2.5 text-gray-400" size={16} />
                    <input 
                        type="text" 
                        placeholder="Search..." 
                        value={searchTerm}
                        onChange={(e) => setSearchTerm(e.target.value)}
                        className="pl-8 pr-4 py-2 bg-gray-50 border border-gray-200 rounded-lg text-sm focus:outline-none focus:ring-1 focus:ring-primary w-full"
                    />
                </div>
                <select 
                    value={filterAccount}
                    onChange={(e) => setFilterAccount(e.target.value)}
                    className="py-2 px-3 bg-gray-50 border border-gray-200 rounded-lg text-sm focus:outline-none focus:ring-1 focus:ring-primary"
                >
                    <option value="ALL">All Accounts</option>
                    {accounts.map(a => <option key={a} value={a}>{a}</option>)}
                </select>
            </div>
        </div>
        <div className="overflow-x-auto w-full">
            <div className="min-w-[800px] md:min-w-full">
                <table className="w-full text-left text-sm text-gray-600 table-auto">
                    <thead className="bg-gray-50 text-gray-700 font-semibold uppercase text-xs">
                        <tr>
                            <th className="px-4 py-3 w-24">Date</th>
                            <th className="px-4 py-3 w-40">Category</th>
                            <th className="px-4 py-3 w-40">Account</th>
                            <th className="px-4 py-3 w-28 text-right">Amount</th>
                            <th className="px-4 py-3">Notes</th>
                            <th className="px-4 py-3 w-16 text-center">Action</th>
                        </tr>
                    </thead>
                    <tbody className="divide-y divide-gray-100">
                        {filteredList.length === 0 ? (
                            <tr><td colSpan={6} className="px-4 py-8 text-center text-gray-400">No transactions found.</td></tr>
                        ) : (
                            filteredList.map(t => (
                                <tr key={t.id} className="hover:bg-gray-50 group">
                                    <td className="px-4 py-3 whitespace-nowrap">{t.date}</td>
                                    <td className="px-4 py-3">
                                        <span className={`inline-flex items-center px-2 py-0.5 rounded text-xs font-medium whitespace-nowrap ${
                                            t.type === TransactionType.INCOME ? 'bg-emerald-100 text-emerald-800' : 
                                            t.type === TransactionType.EXPENSE ? 'bg-rose-100 text-rose-800' : 'bg-blue-100 text-blue-800'
                                        }`}>
                                            {t.category}
                                        </span>
                                    </td>
                                    <td className="px-4 py-3">
                                        <div className="flex flex-col">
                                            <span>{t.accountId}</span>
                                            {t.type === TransactionType.TRANSFER && (
                                                <span className="flex items-center text-xs text-gray-400 mt-0.5">
                                                    <ArrowRight size={10} className="mr-1" /> {t.toAccountId}
                                                </span>
                                            )}
                                        </div>
                                    </td>
                                    <td className={`px-4 py-3 text-right font-bold whitespace-nowrap ${
                                        t.type === TransactionType.INCOME ? 'text-emerald-600' : 'text-rose-600'
                                    }`}>
                                        {t.type === TransactionType.EXPENSE ? '-' : ''}{formatCurrency(t.amount)}
                                    </td>
                                    <td className="px-4 py-3 max-w-xs truncate text-gray-500" title={t.notes}>
                                        {t.notes || '-'}
                                    </td>
                                    <td className="px-4 py-3 text-center">
                                        <button 
                                            onClick={() => {
                                                if (window.confirm('Archive this transaction?')) {
                                                    onDeleteTransaction(t.id);
                                                }
                                            }}
                                            className="text-gray-400 hover:text-rose-600 p-1 transition-colors"
                                            title="Archive"
                                        >
                                            <Archive size={16} />
                                        </button>
                                    </td>
                                </tr>
                            ))
                        )}
                    </tbody>
                </table>
            </div>
        </div>
      </div>
    </div>
  );
};

export default Transactions;

import React, { useState } from 'react';
import { Category, User, Transaction } from '../types';
import { Trash2, Plus, RefreshCw } from 'lucide-react';
import { formatCurrency } from '../utils';

interface SettingsProps {
  categories: Category[];
  users: User[];
  archivedTransactions: Transaction[];
  onAddCategory: (c: Category) => void;
  onDeleteCategory: (id: string) => void;
  onRestoreTransaction: (id: string) => void;
}

const Settings: React.FC<SettingsProps> = ({ 
  categories, 
  users, 
  archivedTransactions, 
  onAddCategory, 
  onDeleteCategory,
  onRestoreTransaction 
}) => {
  const [activeSection, setActiveSection] = useState<'CATEGORIES' | 'USERS' | 'ARCHIVE'>('CATEGORIES');

  const [newCatName, setNewCatName] = useState('');
  const [newCatType, setNewCatType] = useState<'INCOME' | 'EXPENSE' | 'BOTH'>('EXPENSE');

  const handleAddCategory = () => {
    if (!newCatName) return;
    onAddCategory({
        id: Math.random().toString(36).substr(2, 9),
        name: newCatName,
        type: newCatType
    });
    setNewCatName('');
  };

  const navItems = [
      { id: 'CATEGORIES', label: 'Categories' },
      { id: 'USERS', label: 'Users' },
      { id: 'ARCHIVE', label: 'Archives' },
  ];

  return (
    <div className="bg-white rounded-xl shadow-sm border border-gray-200 min-h-[500px] flex flex-col md:flex-row">
      {/* Sidebar (Desktop) / Tabs (Mobile) */}
      <div className="w-full md:w-64 border-b md:border-b-0 md:border-r border-gray-100 p-2 md:p-4 bg-gray-50 md:bg-white overflow-x-auto">
        <h2 className="hidden md:block text-xl font-bold px-4 mb-4">Settings</h2>
        <div className="flex md:flex-col gap-2 min-w-max">
            {navItems.map(item => (
                <button 
                    key={item.id}
                    onClick={() => setActiveSection(item.id as any)}
                    className={`flex-1 md:w-full text-center md:text-left px-4 py-2.5 rounded-lg transition-colors text-sm font-medium ${
                        activeSection === item.id 
                        ? 'bg-white md:bg-primary/10 text-primary shadow-sm md:shadow-none border md:border-none border-gray-200' 
                        : 'text-gray-600 hover:bg-gray-100 md:hover:bg-gray-50'
                    }`}
                >
                    {item.label}
                </button>
            ))}
        </div>
      </div>

      {/* Content */}
      <div className="flex-1 p-4 md:p-6">
        {activeSection === 'CATEGORIES' && (
            <div className="space-y-6">
                <h3 className="text-lg font-bold text-gray-800 border-b pb-2">Manage Categories</h3>

                <div className="flex flex-col sm:flex-row gap-2 items-stretch sm:items-end bg-gray-50 p-4 rounded-lg">
                    <div className="flex-1">
                        <label className="text-xs font-medium text-gray-500">Name</label>
                        <input 
                            type="text" 
                            className="w-full p-2 border rounded-md text-sm" 
                            value={newCatName}
                            onChange={(e) => setNewCatName(e.target.value)}
                            placeholder="e.g. Transport"
                        />
                    </div>
                    <div className="w-full sm:w-32">
                         <label className="text-xs font-medium text-gray-500">Type</label>
                         <select 
                            className="w-full p-2 border rounded-md text-sm"
                            value={newCatType}
                            onChange={(e) => setNewCatType(e.target.value as any)}
                        >
                            <option value="EXPENSE">Expense</option>
                            <option value="INCOME">Income</option>
                            <option value="BOTH">Both</option>
                         </select>
                    </div>
                    <button 
                        onClick={handleAddCategory}
                        className="bg-primary text-white p-2 rounded-md hover:bg-teal-800 flex justify-center items-center"
                    >
                        <Plus size={20} />
                    </button>
                </div>

                <div className="space-y-2 max-h-96 overflow-y-auto">
                    {categories.map(cat => (
                        <div key={cat.id} className="flex justify-between items-center p-3 border rounded-lg hover:bg-gray-50">
                            <div>
                                <span className="font-medium text-gray-700">{cat.name}</span>
                                <span className="ml-2 text-xs px-2 py-1 bg-gray-200 rounded-full text-gray-600">{cat.type}</span>
                            </div>
                            <button onClick={() => onDeleteCategory(cat.id)} className="text-red-400 hover:text-red-600">
                                <Trash2 size={16} />
                            </button>
                        </div>
                    ))}
                </div>
            </div>
        )}

        {activeSection === 'USERS' && (
             <div className="space-y-6">
                 <h3 className="text-lg font-bold text-gray-800 border-b pb-2">User Management</h3>
                 <p className="text-sm text-gray-500">Define users and finance representatives for reporting.</p>

                 <div className="grid gap-4">
                     {users.map(user => (
                         <div key={user.id} className="p-4 border rounded-lg flex flex-col sm:flex-row justify-between items-start sm:items-center gap-2">
                             <div>
                                 <p className="font-bold">{user.name}</p>
                                 <p className="text-sm text-gray-500">{user.email} | {user.phone}</p>
                             </div>
                             <span className="px-3 py-1 bg-blue-100 text-blue-800 rounded-full text-xs font-bold">
                                 {user.role}
                             </span>
                         </div>
                     ))}
                 </div>
                 <div className="text-center p-4 border border-dashed rounded-lg text-gray-400 text-sm">
                     User addition disabled in demo.
                 </div>
             </div>
        )}

        {activeSection === 'ARCHIVE' && (
            <div className="space-y-6">
                <h3 className="text-lg font-bold text-gray-800 border-b pb-2">Archived Transactions</h3>
                {archivedTransactions.length === 0 ? (
                    <p className="text-gray-500">No archived records found.</p>
                ) : (
                    <div className="overflow-x-auto">
                        <table className="w-full text-sm text-left min-w-[500px]">
                            <thead className="bg-gray-50 text-gray-500">
                                <tr>
                                    <th className="p-2">Date</th>
                                    <th className="p-2">Category</th>
                                    <th className="p-2">Amount</th>
                                    <th className="p-2">Action</th>
                                </tr>
                            </thead>
                            <tbody>
                                {archivedTransactions.map(t => (
                                    <tr key={t.id} className="border-b">
                                        <td className="p-2">{t.date}</td>
                                        <td className="p-2">{t.category}</td>
                                        <td className="p-2">{formatCurrency(t.amount)}</td>
                                        <td className="p-2">
                                            <button 
                                                onClick={() => onRestoreTransaction(t.id)}
                                                className="text-primary hover:underline flex items-center text-xs"
                                            >
                                                <RefreshCw size={12} className="mr-1" /> Restore
                                            </button>
                                        </td>
                                    </tr>
                                ))}
                            </tbody>
                        </table>
                    </div>
                )}
            </div>
        )}
      </div>
    </div>
  );
};

export default Settings;

import React, { useState } from 'react';
import { Transaction, TransactionType, User, Category, AccountType } from '../types';
import { formatCurrency, getGreeting } from '../utils';
import { jsPDF } from 'jspdf';
import { FileText, Plus, Save } from 'lucide-react';

interface ReportsProps {
  transactions: Transaction[];
  users: User[];
  onAddTransaction: (t: Omit<Transaction, 'id'>) => void;
  financeRep: User | undefined;
}

type ReportType = 'WEEKLY' | 'MONTHLY' | 'QUARTERLY' | 'YEARLY';

const Reports: React.FC<ReportsProps> = ({ transactions, users, onAddTransaction, financeRep }) => {
  const [activeTab, setActiveTab] = useState<ReportType>('WEEKLY');

  const [plannedItems, setPlannedItems] = useState<{item: string, amount: number}[]>([{ item: '', amount: 0 }]);
  const [weeklyOfferings, setWeeklyOfferings] = useState<{type: 'CASH' | 'MOMO', amount: number}[]>([{ type: 'CASH', amount: 0 }]);

  const generatePDF = () => {
    const doc = new jsPDF();
    const pageWidth = doc.internal.pageSize.getWidth();

    doc.setFontSize(18);
    doc.text("Thesaurus Children's Finance Report", 10, 20);
    doc.setFontSize(12);
    doc.text(`Report Type: ${activeTab}`, 10, 30);
    doc.text(`Generated: ${new Date().toLocaleDateString()}`, 10, 36);

    if (activeTab === 'WEEKLY') {
        const totalPlanned = plannedItems.reduce((acc, i) => acc + i.amount, 0);
        const financeName = financeRep?.name || 'Finance Director';
        const requestAmount = formatCurrency(totalPlanned);

        let yPos = 50;
        doc.setFontSize(11);
        doc.setFont("helvetica", "bold");
        doc.text("Request to Finance:", 10, yPos);
        yPos += 10;
        doc.setFont("helvetica", "normal");

        const message = `${getGreeting()} ${financeName}. I pray you are well. Could you kindly send ${requestAmount} to [Recipient] for the purchase of the following for CM?`;

        const splitText = doc.splitTextToSize(message, pageWidth - 20);
        doc.text(splitText, 10, yPos);
        yPos += 20 + (splitText.length * 5);

        doc.text("Planned Items:", 10, yPos);
        yPos += 7;

        plannedItems.forEach(item => {
            doc.text(`- ${item.item}: ${formatCurrency(item.amount)}`, 15, yPos);
            yPos += 6;
        });

        yPos += 5;
        doc.setFont("helvetica", "bold");
        doc.text(`Total: ${formatCurrency(totalPlanned)}`, 15, yPos);

        yPos += 15;
        doc.setFont("helvetica", "italic");
        doc.text("Thank you very much. God bless you!", 10, yPos);
    } else {
        doc.text("Summary:", 10, 50);
        doc.text("Feature simplified for this demo.", 10, 60);
    }

    doc.save(`finance_report_${activeTab.toLowerCase()}.pdf`);
  };

  const handleAddPlannedItem = () => setPlannedItems([...plannedItems, { item: '', amount: 0 }]);
  const handleAddOffering = () => setWeeklyOfferings([...weeklyOfferings, { type: 'CASH', amount: 0 }]);

  const saveWeeklyData = () => {
    weeklyOfferings.forEach(off => {
        if (off.amount > 0) {
            onAddTransaction({
                date: new Date().toISOString().split('T')[0],
                amount: off.amount,
                category: 'Offerings & Tithes',
                accountId: off.type === 'CASH' ? AccountType.CASH : AccountType.MOMO,
                type: TransactionType.INCOME,
                notes: 'Weekly Entry',
                isArchived: false
            });
        }
    });

    plannedItems.forEach(plan => {
        if (plan.amount > 0 && plan.item) {
            onAddTransaction({
                date: new Date().toISOString().split('T')[0],
                amount: plan.amount,
                category: 'Snacks & Meals',
                accountId: AccountType.CASH,
                type: TransactionType.EXPENSE,
                notes: plan.item,
                isArchived: false,
                meta: { isPlan: true }
            });
        }
    });

    alert("Weekly data processed and saved.");
  };

  return (
    <div className="space-y-6">
      <div className="bg-white rounded-xl shadow-sm border border-gray-200 overflow-hidden">
         <div className="flex border-b border-gray-100 overflow-x-auto no-scrollbar">
          {(['WEEKLY', 'MONTHLY', 'QUARTERLY', 'YEARLY'] as ReportType[]).map(tab => (
            <button
              key={tab}
              onClick={() => setActiveTab(tab)}
              className={`flex-1 min-w-[100px] py-4 text-sm font-semibold tracking-wide transition-colors whitespace-nowrap ${
                activeTab === tab ? 'bg-gray-50 text-primary border-b-2 border-primary' : 'text-gray-500 hover:bg-gray-50'
              }`}
            >
              {tab}
            </button>
          ))}
        </div>

        <div className="p-4 sm:p-6">
            <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center mb-6 gap-4">
                <h3 className="text-xl font-bold text-gray-800">{activeTab} Report</h3>
                <button 
                    onClick={generatePDF}
                    className="flex items-center w-full sm:w-auto justify-center px-4 py-2 bg-gray-800 text-white rounded-lg hover:bg-gray-700 transition-colors"
                >
                    <FileText size={18} className="mr-2" /> Export to PDF
                </button>
            </div>

            {activeTab === 'WEEKLY' && (
                <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
                    {/* Income Section */}
                    <div className="space-y-4">
                        <h4 className="font-semibold text-gray-700 border-b pb-2">Record Income (Offerings/Tithes)</h4>
                        {weeklyOfferings.map((off, idx) => (
                            <div key={idx} className="flex flex-col sm:flex-row gap-2">
                                <select 
                                    className="p-2 border rounded-md w-full sm:w-32"
                                    value={off.type}
                                    onChange={(e) => {
                                        const n = [...weeklyOfferings];
                                        n[idx].type = e.target.value as any;
                                        setWeeklyOfferings(n);
                                    }}
                                >
                                    <option value="CASH">Cash</option>
                                    <option value="MOMO">MoMo</option>
                                </select>
                                <input 
                                    type="number" 
                                    className="flex-1 p-2 border rounded-md w-full" 
                                    placeholder="Amount"
                                    value={off.amount}
                                    onChange={(e) => {
                                        const n = [...weeklyOfferings];
                                        n[idx].amount = Number(e.target.value);
                                        setWeeklyOfferings(n);
                                    }}
                                />
                            </div>
                        ))}
                        <button onClick={handleAddOffering} className="text-sm text-primary flex items-center p-2 hover:bg-gray-50 rounded-md">
                            <Plus size={14} className="mr-1" /> Add Entry
                        </button>
                    </div>

                    {/* Planning Section */}
                    <div className="space-y-4">
                         <h4 className="font-semibold text-gray-700 border-b pb-2">Plan Next Week (Snacks & Meals)</h4>
                         {plannedItems.map((item, idx) => (
                            <div key={idx} className="flex flex-col sm:flex-row gap-2">
                                <input 
                                    type="text" 
                                    className="flex-1 p-2 border rounded-md w-full" 
                                    placeholder="Item Name"
                                    value={item.item}
                                    onChange={(e) => {
                                        const n = [...plannedItems];
                                        n[idx].item = e.target.value;
                                        setPlannedItems(n);
                                    }}
                                />
                                <input 
                                    type="number" 
                                    className="w-full sm:w-24 p-2 border rounded-md" 
                                    placeholder="Cost"
                                    value={item.amount}
                                    onChange={(e) => {
                                        const n = [...plannedItems];
                                        n[idx].amount = Number(e.target.value);
                                        setPlannedItems(n);
                                    }}
                                />
                            </div>
                        ))}
                        <button onClick={handleAddPlannedItem} className="text-sm text-primary flex items-center p-2 hover:bg-gray-50 rounded-md">
                            <Plus size={14} className="mr-1" /> Add Item
                        </button>
                    </div>

                    <div className="lg:col-span-2 pt-4 border-t">
                         <button 
                            onClick={saveWeeklyData}
                            className="w-full sm:w-auto px-6 py-3 bg-primary text-white font-bold rounded-lg shadow hover:bg-teal-800 transition-colors flex items-center justify-center"
                        >
                            <Save size={18} className="mr-2" /> Save Records & Update Finance
                         </button>
                    </div>
                </div>
            )}

            {activeTab !== 'WEEKLY' && (
                <div className="text-center py-10 text-gray-500">
                    <p>Charts and detailed analysis for {activeTab.toLowerCase()} would appear here.</p>
                    <p className="text-xs mt-2">(Included in PDF Export)</p>
                </div>
            )}
        </div>
      </div>
    </div>
  );
};

export default Reports;

import React, { useState, useEffect } from 'react';
import { LayoutDashboard, Receipt, Settings as SettingsIcon, PieChart, Menu, X } from 'lucide-react';
import { Transaction, Category, User, AccountType } from './types';
import { INITIAL_TRANSACTIONS, INITIAL_CATEGORIES, INITIAL_USERS } from './utils';

import Overview from './components/Overview';
import Transactions from './components/Transactions';
import Reports from './components/Reports';
import Settings from './components/Settings';

function App() {
  const [transactions, setTransactions] = useState<Transaction[]>(INITIAL_TRANSACTIONS);
  const [categories, setCategories] = useState<Category[]>(INITIAL_CATEGORIES);
  const [users, setUsers] = useState<User[]>(INITIAL_USERS);
  const [activeView, setActiveView] = useState<'OVERVIEW' | 'TRANSACTIONS' | 'REPORTS' | 'SETTINGS'>('OVERVIEW');
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);

  const [preSelectedAccount, setPreSelectedAccount] = useState<AccountType | null>(null);

  const handleAccountFilter = (account: AccountType | null) => {
    setPreSelectedAccount(account);
    setActiveView('TRANSACTIONS');
  };

  const addTransaction = (t: Omit<Transaction, 'id'>) => {
    const newT = { ...t, id: Math.random().toString(36).substr(2, 9) };
    setTransactions(prev => [newT, ...prev]);
  };

  const deleteTransaction = (id: string) => {
    setTransactions(prev => prev.map(t => t.id === id ? { ...t, isArchived: true } : t));
  };

  const restoreTransaction = (id: string) => {
    setTransactions(prev => prev.map(t => t.id === id ? { ...t, isArchived: false } : t));
  };

  const addCategory = (c: Category) => {
    setCategories(prev => [...prev, c]);
  };

  const deleteCategory = (id: string) => {
    setCategories(prev => prev.filter(c => c.id !== id));
  };

  const navItems = [
    { id: 'OVERVIEW', label: 'Overview', icon: LayoutDashboard },
    { id: 'TRANSACTIONS', label: 'Transactions', icon: Receipt },
    { id: 'REPORTS', label: 'Generate Reports', icon: PieChart },
    { id: 'SETTINGS', label: 'Settings', icon: SettingsIcon },
  ];

  return (
    <div className="flex min-h-screen bg-gray-50 font-sans text-gray-900">

      {/* Sidebar (Desktop) */}
      <aside className="hidden md:flex w-64 flex-col bg-white border-r border-gray-200 fixed h-full z-10">
        <div className="p-6 border-b border-gray-100">
          <h1 className="text-xl font-bold text-primary leading-tight">Thesaurus<br/><span className="text-gray-600 text-sm font-normal">Children's Finance</span></h1>
        </div>
        <nav className="flex-1 p-4 space-y-2">
          {navItems.map(item => (
            <button
              key={item.id}
              onClick={() => setActiveView(item.id as any)}
              className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl transition-all ${
                activeView === item.id 
                  ? 'bg-primary text-white shadow-lg shadow-primary/30' 
                  : 'text-gray-500 hover:bg-gray-50 hover:text-primary'
              }`}
            >
              <item.icon size={20} />
              <span className="font-medium">{item.label}</span>
            </button>
          ))}
        </nav>
        <div className="p-6 border-t border-gray-100">
          <p className="text-xs text-gray-400 text-center">Version 1.0.0</p>
        </div>
      </aside>

      {/* Mobile Header */}
      <div className="md:hidden fixed top-0 w-full bg-white border-b border-gray-200 z-30 flex justify-between items-center px-4 py-3 shadow-sm h-16">
         <div>
            <h1 className="text-lg font-bold text-primary leading-none">Thesaurus</h1>
            <p className="text-xs text-gray-500">Children's Finance</p>
         </div>
         <button 
            onClick={() => setIsMobileMenuOpen(!isMobileMenuOpen)} 
            className="text-gray-600 p-2 rounded-md hover:bg-gray-100"
         >
            {isMobileMenuOpen ? <X size={24} /> : <Menu size={24} />}
         </button>
      </div>

      {/* Mobile Menu Overlay */}
      {isMobileMenuOpen && (
        <div className="md:hidden fixed inset-0 z-20 bg-black/50 backdrop-blur-sm" onClick={() => setIsMobileMenuOpen(false)}>
           <div 
             className="absolute top-16 left-0 right-0 bg-white border-b border-gray-200 p-4 space-y-2 shadow-xl animate-in slide-in-from-top-10 duration-200"
             onClick={e => e.stopPropagation()} 
           >
             {navItems.map(item => (
              <button
                key={item.id}
                onClick={() => {
                    setActiveView(item.id as any);
                    setIsMobileMenuOpen(false);
                }}
                className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl transition-all ${
                  activeView === item.id 
                    ? 'bg-primary text-white shadow-md' 
                    : 'text-gray-500 hover:bg-gray-50'
                }`}
              >
                <item.icon size={20} />
                <span className="font-medium">{item.label}</span>
              </button>
            ))}
           </div>
        </div>
      )}

      {/* Main Content Area */}
      <main className={`flex-1 md:ml-64 p-4 md:p-8 pt-20 md:pt-8`}>
        <div className="max-w-7xl mx-auto">
          {activeView === 'OVERVIEW' && (
            <Overview 
                transactions={transactions} 
                onFilterAccount={handleAccountFilter} 
            />
          )}

          {activeView === 'TRANSACTIONS' && (
            <Transactions 
                transactions={transactions}
                categories={categories}
                accounts={[AccountType.MOMO, AccountType.CASH, AccountType.OTHER]}
                preSelectedAccount={preSelectedAccount}
                onAddTransaction={addTransaction}
                onDeleteTransaction={deleteTransaction}
            />
          )}

          {activeView === 'REPORTS' && (
             <Reports 
                transactions={transactions}
                users={users}
                onAddTransaction={addTransaction}
                financeRep={users.find(u => u.role === 'FINANCE_REP')}
             />
          )}

          {activeView === 'SETTINGS' && (
             <Settings 
                categories={categories}
                users={users}
                archivedTransactions={transactions.filter(t => t.isArchived)}
                onAddCategory={addCategory}
                onDeleteCategory={deleteCategory}
                onRestoreTransaction={restoreTransaction}
             />
          )}
        </div>
      </main>
    </div>
  );
}

export default App;

import React, { useState, useEffect } from 'react';
import { Transaction, TransactionType, AccountType, Category } from '../types';
import { formatCurrency } from '../utils';
import { Search, Plus, Save, X, Archive, ArrowRight, Filter } from 'lucide-react';

interface TransactionsProps {
  transactions: Transaction[];
  categories: Category[];
  accounts: AccountType[];
  preSelectedAccount: AccountType | null;
  onAddTransaction: (t: Omit<Transaction, 'id'>) => void;
  onDeleteTransaction: (id: string) => void;
}

type TabType = 'INCOME' | 'EXPENSE' | 'TRANSFER';

const Transactions: React.FC<TransactionsProps> = ({ 
  transactions, 
  categories, 
  accounts, 
  preSelectedAccount,
  onAddTransaction,
  onDeleteTransaction
}) => {
  const [activeTab, setActiveTab] = useState<TabType>('INCOME');
  const [filterAccount, setFilterAccount] = useState<string>(preSelectedAccount || 'ALL');
  const [searchTerm, setSearchTerm] = useState('');

  const [entries, setEntries] = useState<any[]>([{ 
    amount: '', 
    date: new Date().toISOString().split('T')[0],
    category: '',
    accountId: '',
    toAccountId: '',
    recipient: '',
    notes: '',
    receivedFromFinance: false
  }]);

  useEffect(() => {
    if (preSelectedAccount) setFilterAccount(preSelectedAccount);
  }, [preSelectedAccount]);

  const handleAddEntry = () => {
    setEntries([...entries, { 
      amount: '', 
      date: new Date().toISOString().split('T')[0],
      category: '',
      accountId: '',
      toAccountId: '',
      recipient: '',
      notes: '',
      receivedFromFinance: false
    }]);
  };

  const handleRemoveEntry = (index: number) => {
    if (entries.length > 1) {
      setEntries(entries.filter((_, i) => i !== index));
    }
  };

  const updateEntry = (index: number, field: string, value: any) => {
    const newEntries = [...entries];
    newEntries[index] = { ...newEntries[index], [field]: value };
    setEntries(newEntries);
  };

  const validateAndSave = () => {
    for (const entry of entries) {
      if (!entry.amount || Number(entry.amount) <= 0) {
        alert('Please enter a valid amount.');
        return;
      }
      if (!entry.date) {
        alert('Please select a date.');
        return;
      }
      if (activeTab !== 'TRANSFER' && !entry.category) {
        alert('Please select a category.');
        return;
      }
      if (!entry.accountId) {
        alert('Please select an account.');
        return;
      }
      if (activeTab === 'TRANSFER' && !entry.toAccountId) {
         alert('Please select a destination account.');
         return;
      }
    }

    entries.forEach(entry => {
      onAddTransaction({
        date: entry.date,
        amount: Number(entry.amount),
        type: activeTab === 'INCOME' ? TransactionType.INCOME : activeTab === 'EXPENSE' ? TransactionType.EXPENSE : TransactionType.TRANSFER,
        category: activeTab === 'TRANSFER' ? 'Finance Transfer' : entry.category,
        accountId: entry.accountId,
        toAccountId: activeTab === 'TRANSFER' ? entry.toAccountId : undefined,
        recipient: entry.recipient,
        notes: entry.notes,
        isArchived: false,
        meta: {
            receivedFromFinance: entry.receivedFromFinance
        }
      });
    });

    setEntries([{ 
      amount: '', 
      date: new Date().toISOString().split('T')[0],
      category: '',
      accountId: '',
      toAccountId: '',
      recipient: '',
      notes: '',
      receivedFromFinance: false
    }]);
    alert('Transaction(s) saved successfully!');
  };

  const filteredList = transactions
    .filter(t => !t.isArchived)
    .filter(t => filterAccount === 'ALL' || t.accountId === filterAccount || t.toAccountId === filterAccount)
    .filter(t => 
      t.category.toLowerCase().includes(searchTerm.toLowerCase()) || 
      t.notes?.toLowerCase().includes(searchTerm.toLowerCase()) ||
      t.recipient?.toLowerCase().includes(searchTerm.toLowerCase())
    )
    .sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());

  return (
    <div className="space-y-6">
      <div className="bg-white rounded-xl shadow-sm border border-gray-200 overflow-hidden">
        {/* Form Tabs */}
        <div className="flex border-b border-gray-100 overflow-x-auto no-scrollbar">
          {(['INCOME', 'EXPENSE', 'TRANSFER'] as TabType[]).map(tab => (
            <button
              key={tab}
              onClick={() => setActiveTab(tab)}
              className={`flex-1 min-w-[100px] py-4 text-sm font-semibold tracking-wide transition-colors whitespace-nowrap ${
                activeTab === tab 
                  ? tab === 'INCOME' ? 'bg-emerald-50 text-emerald-700 border-b-2 border-emerald-500' 
                    : tab === 'EXPENSE' ? 'bg-rose-50 text-rose-700 border-b-2 border-rose-500'
                    : 'bg-blue-50 text-blue-700 border-b-2 border-blue-500'
                  : 'text-gray-500 hover:bg-gray-50'
              }`}
            >
              {tab}
            </button>
          ))}
        </div>

        {/* Form Body */}
        <div className="p-4 sm:p-6">
          <div className="space-y-6">
            {entries.map((entry, index) => (
              <div key={index} className="relative p-4 bg-gray-50 rounded-lg border border-gray-200 space-y-4">
                {entries.length > 1 && (
                    <button onClick={() => handleRemoveEntry(index)} className="absolute top-2 right-2 text-red-400 hover:text-red-600 z-10 p-1 bg-white rounded-full shadow-sm border border-gray-200">
                        <X size={16} />
                    </button>
                )}

                <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
                  <div>
                    <label className="block text-xs font-medium text-gray-500 mb-1">Date</label>
                    <input 
                        type="date" 
                        value={entry.date}
                        onChange={(e) => updateEntry(index, 'date', e.target.value)}
                        className="w-full rounded-md border-gray-300 shadow-sm focus:ring-primary focus:border-primary p-2 border text-sm"
                    />
                  </div>

                  <div>
                    <label className="block text-xs font-medium text-gray-500 mb-1">Value (GHC)</label>
                    <input 
                        type="number" 
                        placeholder="0.00"
                        value={entry.amount}
                        onChange={(e) => updateEntry(index, 'amount', e.target.value)}
                        className="w-full rounded-md border-gray-300 shadow-sm focus:ring-primary focus:border-primary p-2 border text-sm"
                    />
                  </div>

                  {activeTab !== 'TRANSFER' && (
                    <div className="sm:col-span-2">
                        <label className="block text-xs font-medium text-gray-500 mb-1">Category</label>
                        <select 
                            value={entry.category}
                            onChange={(e) => updateEntry(index, 'category', e.target.value)}
                            className="w-full rounded-md border-gray-300 shadow-sm focus:ring-primary focus:border-primary p-2 border text-sm"
                        >
                            <option value="">Select Category...</option>
                            {categories
                                .filter(c => c.type === 'BOTH' || c.type === activeTab)
                                .map(c => <option key={c.id} value={c.name}>{c.name}</option>)}
                        </select>
                    </div>
                  )}
                </div>

                <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                   <div>
                        <label className="block text-xs font-medium text-gray-500 mb-1">
                            {activeTab === 'TRANSFER' ? 'From Account' : 'Account'}
                        </label>
                        <select 
                            value={entry.accountId}
                            onChange={(e) => updateEntry(index, 'accountId', e.target.value)}
                            className="w-full rounded-md border-gray-300 shadow-sm focus:ring-primary focus:border-primary p-2 border text-sm"
                        >
                            <option value="">Select Account...</option>
                            {accounts.map(a => <option key={a} value={a}>{a}</option>)}
                        </select>

                        {activeTab === 'EXPENSE' && entry.accountId === AccountType.MOMO && (
                            <div className="mt-3 flex items-start">
                                <input 
                                    type="checkbox" 
                                    id={`finance-check-${index}`}
                                    checked={entry.receivedFromFinance}
                                    onChange={(e) => updateEntry(index, 'receivedFromFinance', e.target.checked)}
                                    className="mt-0.5 h-4 w-4 text-primary focus:ring-primary border-gray-300 rounded"
                                />
                                <label htmlFor={`finance-check-${index}`} className="ml-2 block text-xs text-red-600 font-medium leading-tight">
                                    Was this digital cash received from Finance? (Mandatory)
                                </label>
                            </div>
                        )}
                   </div>

                   {activeTab === 'TRANSFER' ? (
                       <div>
                            <label className="block text-xs font-medium text-gray-500 mb-1">To Account</label>
                            <select 
                                value={entry.toAccountId}
                                onChange={(e) => updateEntry(index, 'toAccountId', e.target.value)}
                                className="w-full rounded-md border-gray-300 shadow-sm focus:ring-primary focus:border-primary p-2 border text-sm"
                            >
                                <option value="">Select Account...</option>
                                {accounts.map(a => <option key={a} value={a}>{a}</option>)}
                            </select>
                       </div>
                   ) : (
                       <div>
                           <label className="block text-xs font-medium text-gray-500 mb-1">From/To (Optional)</label>
                           <input 
                                type="text"
                                placeholder="Recipient Name"
                                value={entry.recipient}
                                onChange={(e) => updateEntry(index, 'recipient', e.target.value)}
                                className="w-full rounded-md border-gray-300 shadow-sm focus:ring-primary focus:border-primary p-2 border text-sm"
                            />
                       </div>
                   )}
                </div>

                <div>
                    <label className="block text-xs font-medium text-gray-500 mb-1">Notes (Optional)</label>
                    <textarea 
                        rows={2}
                        value={entry.notes}
                        onChange={(e) => updateEntry(index, 'notes', e.target.value)}
                        className="w-full rounded-md border-gray-300 shadow-sm focus:ring-primary focus:border-primary p-2 border text-sm"
                        placeholder="Add details here..."
                    />
                </div>
              </div>
            ))}

            <div className="flex flex-col sm:flex-row justify-between items-center gap-4">
                <button 
                    onClick={handleAddEntry}
                    className="w-full sm:w-auto flex items-center justify-center text-sm font-medium text-primary hover:text-teal-800 p-2"
                >
                    <Plus size={16} className="mr-1" /> Add another entry
                </button>
                <button 
                    onClick={validateAndSave}
                    className={`w-full sm:w-auto flex items-center justify-center px-6 py-2.5 rounded-lg text-white font-medium shadow-sm transition-colors ${
                        activeTab === 'INCOME' ? 'bg-emerald-600 hover:bg-emerald-700' 
                        : activeTab === 'EXPENSE' ? 'bg-rose-600 hover:bg-rose-700' 
                        : 'bg-blue-600 hover:bg-blue-700'
                    }`}
                >
                    <Save size={18} className="mr-2" /> Save Transaction
                </button>
            </div>
          </div>
        </div>
      </div>

      {/* Transaction List */}
      <div className="bg-white rounded-xl shadow-sm border border-gray-200">
        <div className="p-4 border-b border-gray-100 flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
            <h3 className="font-bold text-gray-800">History</h3>
            <div className="flex flex-col sm:flex-row gap-2 w-full md:w-auto">
                <div className="relative flex-1">
                    <Search className="absolute left-2 top-2.5 text-gray-400" size={16} />
                    <input 
                        type="text" 
                        placeholder="Search..." 
                        value={searchTerm}
                        onChange={(e) => setSearchTerm(e.target.value)}
                        className="pl-8 pr-4 py-2 bg-gray-50 border border-gray-200 rounded-lg text-sm focus:outline-none focus:ring-1 focus:ring-primary w-full"
                    />
                </div>
                <select 
                    value={filterAccount}
                    onChange={(e) => setFilterAccount(e.target.value)}
                    className="py-2 px-3 bg-gray-50 border border-gray-200 rounded-lg text-sm focus:outline-none focus:ring-1 focus:ring-primary w-full sm:w-auto"
                >
                    <option value="ALL">All Accounts</option>
                    {accounts.map(a => <option key={a} value={a}>{a}</option>)}
                </select>
            </div>
        </div>

        {/* Desktop Table View */}
        <div className="hidden md:block overflow-x-auto w-full">
            <div className="min-w-full">
                <table className="w-full text-left text-sm text-gray-600 table-auto">
                    <thead className="bg-gray-50 text-gray-700 font-semibold uppercase text-xs">
                        <tr>
                            <th className="px-4 py-3 w-28">Date</th>
                            <th className="px-4 py-3 w-40">Category</th>
                            <th className="px-4 py-3 w-40">Account</th>
                            <th className="px-4 py-3 w-28 text-right">Amount</th>
                            <th className="px-4 py-3">Notes</th>
                            <th className="px-4 py-3 w-16 text-center">Action</th>
                        </tr>
                    </thead>
                    <tbody className="divide-y divide-gray-100">
                        {filteredList.length === 0 ? (
                            <tr><td colSpan={6} className="px-4 py-8 text-center text-gray-400">No transactions found.</td></tr>
                        ) : (
                            filteredList.map(t => (
                                <tr key={t.id} className="hover:bg-gray-50 group">
                                    <td className="px-4 py-3 whitespace-nowrap">{t.date}</td>
                                    <td className="px-4 py-3">
                                        <span className={`inline-flex items-center px-2 py-0.5 rounded text-xs font-medium whitespace-nowrap ${
                                            t.type === TransactionType.INCOME ? 'bg-emerald-100 text-emerald-800' : 
                                            t.type === TransactionType.EXPENSE ? 'bg-rose-100 text-rose-800' : 'bg-blue-100 text-blue-800'
                                        }`}>
                                            {t.category}
                                        </span>
                                    </td>
                                    <td className="px-4 py-3">
                                        <div className="flex flex-col">
                                            <span className="truncate max-w-[150px]" title={t.accountId}>{t.accountId}</span>
                                            {t.type === TransactionType.TRANSFER && (
                                                <span className="flex items-center text-xs text-gray-400 mt-0.5 truncate max-w-[150px]">
                                                    <ArrowRight size={10} className="mr-1" /> {t.toAccountId}
                                                </span>
                                            )}
                                        </div>
                                    </td>
                                    <td className={`px-4 py-3 text-right font-bold whitespace-nowrap ${
                                        t.type === TransactionType.INCOME ? 'text-emerald-600' : 'text-rose-600'
                                    }`}>
                                        {t.type === TransactionType.EXPENSE ? '-' : ''}{formatCurrency(t.amount)}
                                    </td>
                                    <td className="px-4 py-3 max-w-xs truncate text-gray-500" title={t.notes}>
                                        {t.notes || '-'}
                                    </td>
                                    <td className="px-4 py-3 text-center">
                                        <button 
                                            onClick={() => {
                                                if (window.confirm('Archive this transaction?')) {
                                                    onDeleteTransaction(t.id);
                                                }
                                            }}
                                            className="text-gray-400 hover:text-rose-600 p-1 transition-colors"
                                            title="Archive"
                                        >
                                            <Archive size={16} />
                                        </button>
                                    </td>
                                </tr>
                            ))
                        )}
                    </tbody>
                </table>
            </div>
        </div>

        {/* Mobile Card View */}
        <div className="md:hidden divide-y divide-gray-100">
             {filteredList.length === 0 ? (
                <div className="px-4 py-8 text-center text-gray-400 text-sm">No transactions found.</div>
             ) : (
                filteredList.map(t => (
                    <div key={t.id} className="p-4 space-y-2 hover:bg-gray-50 transition-colors">
                        <div className="flex justify-between items-start">
                            <div className="flex flex-col">
                                <span className="text-xs font-medium text-gray-500">{t.date}</span>
                                <span className="font-bold text-gray-800 text-sm mt-0.5">{t.category}</span>
                            </div>
                             <span className={`font-bold text-base ${
                                t.type === TransactionType.INCOME ? 'text-emerald-600' : 'text-rose-600'
                            }`}>
                                {t.type === TransactionType.EXPENSE ? '-' : ''}{formatCurrency(t.amount)}
                            </span>
                        </div>

                        <div className="flex justify-between items-center text-xs text-gray-600 bg-gray-50 p-2 rounded-md">
                             <div className="flex flex-col">
                                 <span>{t.accountId}</span>
                                 {t.type === TransactionType.TRANSFER && (
                                     <span className="flex items-center text-gray-400 mt-0.5">
                                         <ArrowRight size={10} className="mr-1" /> {t.toAccountId}
                                     </span>
                                 )}
                             </div>
                             {t.recipient && <span className="text-gray-500 italic">{t.recipient}</span>}
                        </div>

                        {(t.notes || t.id) && (
                            <div className="flex justify-between items-end pt-1">
                                <p className="text-xs text-gray-400 line-clamp-2 flex-1 mr-4">{t.notes}</p>
                                <button 
                                    onClick={() => {
                                        if (window.confirm('Archive this transaction?')) {
                                            onDeleteTransaction(t.id);
                                        }
                                    }}
                                    className="text-gray-400 hover:text-rose-600 p-1"
                                >
                                    <Archive size={16} />
                                </button>
                            </div>
                        )}
                    </div>
                ))
             )}
        </div>
      </div>
    </div>
  );
};

export default Transactions;

