                    <div className="w-full sm:w-32">
                         <label className="text-xs font-medium text-gray-500 mb-1 block">Type</label>
                         <select 
                            className="w-full p-2 border border-gray-300 rounded-md text-sm focus:ring-primary focus:border-primary"
                            value={newCatType}
                            onChange={(e) => setNewCatType(e.target.value as any)}
                        >
                            <option value="EXPENSE">Expense</option>
                            <option value="INCOME">Income</option>
                            <option value="BOTH">Both</option>
                         </select>
                    </div>
                    <button 
                        onClick={handleAddCategory}
                        className="bg-primary text-white p-2.5 rounded-md hover:bg-teal-800 flex justify-center items-center shadow-sm"
                    >
                        <Plus size={20} />
                    </button>
                </div>

                <div className="space-y-2">
                    {categories.map(cat => (
                        <div key={cat.id} className="flex justify-between items-center p-3 border border-gray-100 rounded-lg hover:bg-gray-50 transition-colors bg-white">
                            <div>
                                <span className="font-medium text-gray-700 block">{cat.name}</span>
                                <span className={`text-[10px] px-2 py-0.5 rounded-full uppercase font-bold tracking-wide ${
                                    cat.type === 'INCOME' ? 'bg-emerald-100 text-emerald-800' :
                                    cat.type === 'EXPENSE' ? 'bg-rose-100 text-rose-800' : 'bg-blue-100 text-blue-800'
                                }`}>{cat.type}</span>
                            </div>
                            <button onClick={() => onDeleteCategory(cat.id)} className="text-gray-400 hover:text-red-600 p-2">
                                <Trash2 size={18} />
                            </button>
                        </div>
                    ))}
                </div>
            </div>
        )}

        {activeSection === 'USERS' && (
             <div className="space-y-6">
                 <h3 className="text-lg font-bold text-gray-800 border-b pb-2">User Management</h3>
                 <p className="text-sm text-gray-500">Define users and finance representatives for reporting.</p>

                 <div className="grid gap-4">
                     {users.map(user => (
