                 <div className="text-center p-6 border-2 border-dashed border-gray-200 rounded-lg text-gray-400 text-sm">
                     User addition disabled in demo.
                 </div>
             </div>
        )}

        {activeSection === 'ARCHIVE' && (
            <div className="space-y-6">
                <h3 className="text-lg font-bold text-gray-800 border-b pb-2">Archived Transactions</h3>
                {archivedTransactions.length === 0 ? (
                    <div className="text-center py-12 bg-gray-50 rounded-lg border border-dashed border-gray-200">
                         <p className="text-gray-400 font-medium">No archived records found.</p>
                    </div>
                ) : (
                    <>
                        {/* Desktop Table */}
                        <div className="hidden md:block overflow-x-auto border rounded-lg">
                            <table className="w-full text-sm text-left">
                                <thead className="bg-gray-50 text-gray-500 border-b">
                                    <tr>
                                        <th className="p-3 font-medium">Date</th>
                                        <th className="p-3 font-medium">Category</th>
                                        <th className="p-3 font-medium">Amount</th>
                                        <th className="p-3 font-medium text-right">Action</th>
                                    </tr>
                                </thead>
                                <tbody className="divide-y">
                                    {archivedTransactions.map(t => (
                                        <tr key={t.id} className="hover:bg-gray-50">
                                            <td className="p-3 text-gray-600">{t.date}</td>
                                            <td className="p-3 font-medium text-gray-800">{t.category}</td>
                                            <td className="p-3 font-mono text-gray-600">{formatCurrency(t.amount)}</td>
                                            <td className="p-3 text-right">
                                                <button 
                                                    onClick={() => onRestoreTransaction(t.id)}
                                                    className="text-primary hover:text-teal-800 font-medium text-xs inline-flex items-center gap-1"
                                                >
                                                    <RefreshCw size={14} /> Restore
                                                </button>
                                            </td>
                                        </tr>
                                    ))}
                                </tbody>
                            </table>
                        </div>

                        {/* Mobile Cards */}
                        <div className="md:hidden space-y-3">
                             {archivedTransactions.map(t => (
                                <div key={t.id} className="p-4 border rounded-lg bg-white shadow-sm space-y-3">
                                    <div className="flex justify-between items-start">
                                        <div>
                                            <p className="font-bold text-sm text-gray-800">{t.category}</p>
                                            <p className="text-xs text-gray-500">{t.date}</p>
                                        </div>
                                        <span className="font-bold text-gray-700">{formatCurrency(t.amount)}</span>
                                    </div>
                                    <div className="pt-2 border-t border-gray-100 flex justify-end">
                                         <button 
                                            onClick={() => onRestoreTransaction(t.id)}
                                            className="w-full sm:w-auto flex items-center justify-center gap-1.5 px-3 py-2 bg-primary/10 text-primary hover:bg-primary/20 rounded-md text-xs font-bold transition-colors"
                                        >
                                            <RefreshCw size={14} /> Restore Transaction
                                        </button>
                                    </div>
                                </div>
                             ))}
                        </div>
                    </>
                )}
            </div>
        )}
      </div>
    </div>
  );
};

export default Settings;

import React, { useState } from 'react';
import { Transaction, TransactionType, User, Category, AccountType } from '../types';
import { formatCurrency, getGreeting } from '../utils';
import { jsPDF } from 'jspdf';
import { FileText, Plus, Save } from 'lucide-react';

interface ReportsProps {
  transactions: Transaction[];
  users: User[];
  onAddTransaction: (t: Omit<Transaction, 'id'>) => void;
  financeRep: User | undefined;
}

type ReportType = 'WEEKLY' | 'MONTHLY' | 'QUARTERLY' | 'YEARLY';

const Reports: React.FC<ReportsProps> = ({ transactions, users, onAddTransaction, financeRep }) => {
  const [activeTab, setActiveTab] = useState<ReportType>('WEEKLY');

  const [plannedItems, setPlannedItems] = useState<{item: string, amount: number}[]>([{ item: '', amount: 0 }]);
  const [weeklyOfferings, setWeeklyOfferings] = useState<{type: 'CASH' | 'MOMO', amount: number}[]>([{ type: 'CASH', amount: 0 }]);

  const generatePDF = () => {
    const doc = new jsPDF();
    const pageWidth = doc.internal.pageSize.getWidth();

    doc.setFontSize(18);
    doc.text("Thesaurus Children's Finance Report", 10, 20);
    doc.setFontSize(12);
    doc.text(`Report Type: ${activeTab}`, 10, 30);
    doc.text(`Generated: ${new Date().toLocaleDateString()}`, 10, 36);

    if (activeTab === 'WEEKLY') {
        const totalPlanned = plannedItems.reduce((acc, i) => acc + i.amount, 0);
        const financeName = financeRep?.name || 'Finance Director';
        const requestAmount = formatCurrency(totalPlanned);

        let yPos = 50;
        doc.setFontSize(11);
        doc.setFont("helvetica", "bold");
