                                </div>
                                <div className="bg-blue-50 p-3 rounded-lg border border-blue-100">
                                    <p className="text-xs text-blue-600 font-bold">MOMO</p>
                                    <p className="text-lg font-bold text-gray-800">{formatCurrency(weeklyStats.snacks.momo)}</p>
                                </div>
                            </div>
                             <div className="mt-4 pt-4 border-t border-gray-100 flex justify-between items-center">
                                <span className="text-sm font-medium text-gray-500">Total Snacks</span>
