                                        <th className="p-3">Date</th>
                                        <th className="p-3">Category</th>
                                        <th className="p-3 text-right">Amount</th>
                                    </tr>
                                </thead>
                                <tbody className="divide-y divide-gray-100">
                                    {monthlyStats.snippet.length === 0 ? (
                                        <tr><td colSpan={3} className="p-4 text-center text-gray-400">No transactions this month.</td></tr>
                                    ) : (
                                        monthlyStats.snippet.map(t => (
                                            <tr key={t.id} className="hover:bg-gray-50">
                                                <td className="p-3">{t.date}</td>
                                                <td className="p-3">{t.category}</td>
                                                <td className={`p-3 text-right font-medium ${t.type === TransactionType.INCOME ? 'text-emerald-600' : 'text-rose-600'}`}>
                                                    {t.type === TransactionType.EXPENSE && '-'}{formatCurrency(t.amount)}
                                                </td>
                                            </tr>
                                        ))
                                    )}
                                </tbody>
                            </table>
                        </div>
                        <div className="p-2 text-center border-t bg-gray-50 text-xs text-gray-500">
                            Showing last {monthlyStats.snippet.length} transactions
                        </div>
                    </div>
                 </div>
            )}

            {/* --- QUARTERLY VIEW --- */}
            {activeTab === 'QUARTERLY' && (
                <div className="space-y-6 animate-in fade-in duration-300">
                    <div className="bg-white p-4 sm:p-6 rounded-xl shadow-sm border border-gray-200">
                         <h4 className="font-bold text-gray-700 mb-4">Quarterly Comparison</h4>
                         <div className="h-72 w-full">
                            <ResponsiveContainer width="100%" height="100%">
                                <BarChart data={quarterlyStats.chartData} margin={{ top: 20, right: 30, left: 20, bottom: 5 }}>
                                    <CartesianGrid strokeDasharray="3 3" vertical={false} />
                                    <XAxis dataKey="name" tickLine={false} axisLine={false} />
                                    <YAxis tickLine={false} axisLine={false} tickFormatter={(val) => `GHS ${val}`} />
                                    <Tooltip cursor={{fill: 'transparent'}} formatter={(value: number) => formatCurrency(value)} />
                                    <Legend />
                                    <Bar dataKey="Income" fill="#10b981" radius={[4, 4, 0, 0]} />
                                    <Bar dataKey="Expense" fill="#f43f5e" radius={[4, 4, 0, 0]} />
                                </BarChart>
                            </ResponsiveContainer>
                         </div>
                    </div>

                    <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                        {/* Top Income */}
                        <div className="bg-white p-6 rounded-xl border border-gray-200 shadow-sm">
                            <h4 className="font-bold text-gray-700 mb-4 flex items-center text-emerald-700"><Award size={18} className="mr-2" /> Top 3 Income Sources</h4>
                            <div className="space-y-3">
                                {quarterlyStats.topIncome.length === 0 ? <p className="text-gray-400 text-sm">No data available.</p> :
                                    quarterlyStats.topIncome.map((item, idx) => (
                                        <div key={idx} className="flex justify-between items-center p-3 bg-emerald-50 rounded-lg">
                                            <span className="text-sm font-medium text-gray-700 flex items-center">
                                                <span className="w-5 h-5 rounded-full bg-emerald-200 text-emerald-800 flex items-center justify-center text-xs mr-2">{idx + 1}</span>
                                                {item.name}
                                            </span>
                                            <span className="font-bold text-emerald-700">{formatCurrency(item.value)}</span>
                                        </div>
                                    ))
                                }
                            </div>
                        </div>

                        {/* Top Expense */}
                        <div className="bg-white p-6 rounded-xl border border-gray-200 shadow-sm">
                            <h4 className="font-bold text-gray-700 mb-4 flex items-center text-rose-700"><Award size={18} className="mr-2" /> Top 3 Expenses</h4>
                             <div className="space-y-3">
                                {quarterlyStats.topExpense.length === 0 ? <p className="text-gray-400 text-sm">No data available.</p> :
                                    quarterlyStats.topExpense.map((item, idx) => (
                                        <div key={idx} className="flex justify-between items-center p-3 bg-rose-50 rounded-lg">
                                            <span className="text-sm font-medium text-gray-700 flex items-center">
                                                <span className="w-5 h-5 rounded-full bg-rose-200 text-rose-800 flex items-center justify-center text-xs mr-2">{idx + 1}</span>
                                                {item.name}
                                            </span>
                                            <span className="font-bold text-rose-700">{formatCurrency(item.value)}</span>
                                        </div>
                                    ))
                                }
                            </div>
                        </div>
                    </div>
                </div>
            )}

            {/* --- YEARLY VIEW --- */}
            {activeTab === 'YEARLY' && (
                <div className="space-y-6 animate-in fade-in duration-300">
                     <div className="grid grid-cols-1 sm:grid-cols-3 gap-4">
                        <div className="bg-white p-4 rounded-xl border border-gray-200 shadow-sm text-center">
                            <p className="text-gray-500 text-xs uppercase tracking-wide">Annual Income</p>
                            <p className="text-2xl font-bold text-emerald-600 mt-1">{formatCurrency(yearlyStats.totalIncome)}</p>
                        </div>
                         <div className="bg-white p-4 rounded-xl border border-gray-200 shadow-sm text-center">
                            <p className="text-gray-500 text-xs uppercase tracking-wide">Annual Expense</p>
                            <p className="text-2xl font-bold text-rose-600 mt-1">{formatCurrency(yearlyStats.totalExpense)}</p>
                        </div>
                         <div className="bg-white p-4 rounded-xl border border-gray-200 shadow-sm text-center">
                            <p className="text-gray-500 text-xs uppercase tracking-wide">Net Result</p>
                            <p className={`text-2xl font-bold mt-1 ${yearlyStats.balance >= 0 ? 'text-blue-600' : 'text-rose-600'}`}>{formatCurrency(yearlyStats.balance)}</p>
                        </div>
                    </div>

                    <div className="bg-white p-6 rounded-xl shadow-sm border border-gray-200">
                        <h4 className="font-bold text-gray-800 mb-6">Annual Financial Trends</h4>
                        <div className="h-80 w-full">
                            <ResponsiveContainer width="100%" height="100%">
                                <AreaChart data={yearlyStats.chartData} margin={{ top: 10, right: 30, left: 0, bottom: 0 }}>
                                    <defs>
                                        <linearGradient id="colorInc" x1="0" y1="0" x2="0" y2="1">
                                            <stop offset="5%" stopColor="#10b981" stopOpacity={0.8}/>
                                            <stop offset="95%" stopColor="#10b981" stopOpacity={0}/>
                                        </linearGradient>
                                        <linearGradient id="colorExp" x1="0" y1="0" x2="0" y2="1">
                                            <stop offset="5%" stopColor="#f43f5e" stopOpacity={0.8}/>
                                            <stop offset="95%" stopColor="#f43f5e" stopOpacity={0}/>
                                        </linearGradient>
                                    </defs>
                                    <XAxis dataKey="name" axisLine={false} tickLine={false} />
                                    <YAxis axisLine={false} tickLine={false} tickFormatter={(val) => `${val/1000}k`} />
                                    <CartesianGrid vertical={false} strokeDasharray="3 3" />
                                    <Tooltip contentStyle={{borderRadius: '8px'}} formatter={(value: number) => formatCurrency(value)} />
                                    <Area type="monotone" dataKey="Income" stroke="#10b981" fillOpacity={1} fill="url(#colorInc)" />
                                    <Area type="monotone" dataKey="Expense" stroke="#f43f5e" fillOpacity={1} fill="url(#colorExp)" />
                                </AreaChart>
                            </ResponsiveContainer>
                        </div>
                    </div>
                </div>
            )}
        </div>
      </div>
    </div>
  );
};

export default Reports;

import React, { useState, useMemo } from 'react';
import { Transaction, TransactionType, User, AccountType } from '../types';
import { formatCurrency, getGreeting } from '../utils';
import { jsPDF } from 'jspdf';
import { FileText, Calendar, TrendingUp, TrendingDown, Plus, Save, Trash2, Award } from 'lucide-react';
import { 
  BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, Legend, ResponsiveContainer, 
  AreaChart, Area
} from 'recharts';

interface ReportsProps {
  transactions: Transaction[];
  users: User[];
  onAddTransaction: (t: Omit<Transaction, 'id'>) => void;
  financeRep: User | undefined;
}

type ReportType = 'WEEKLY' | 'MONTHLY' | 'QUARTERLY' | 'YEARLY';

const Reports: React.FC<ReportsProps> = ({ transactions, users, onAddTransaction, financeRep }) => {
  const [activeTab, setActiveTab] = useState<ReportType>('WEEKLY');
  const [selectedYear, setSelectedYear] = useState(new Date().getFullYear());
  const [selectedMonth, setSelectedMonth] = useState(new Date().getMonth());
  const [selectedQuarter, setSelectedQuarter] = useState(Math.floor(new Date().getMonth() / 3) + 1);
  const [selectedWeekDate, setSelectedWeekDate] = useState(new Date().toISOString().split('T')[0]);

  // --- Weekly Input States ---
  const [offeringsInput, setOfferingsInput] = useState<{type: 'CASH' | 'MOMO', amount: string}[]>([
    { type: 'CASH', amount: '' }
  ]);
  const [planInput, setPlanInput] = useState<{item: string, cost: string}[]>([
    { item: '', cost: '' }
  ]);

  // --- Helpers ---
  const getQuarterMonths = (q: number) => {
    const start = (q - 1) * 3;
    return [start, start + 1, start + 2];
  };

  const getMonthName = (monthIndex: number) => {
    return new Date(2025, monthIndex, 1).toLocaleString('default', { month: 'long' });
  };

  const getWeekRange = (dateStr: string) => {
    const date = new Date(dateStr);
    const day = date.getDay(); // 0 (Sun) to 6 (Sat)
    const diff = date.getDate() - day + (day === 0 ? -6 : 1); // Adjust to get Monday
    const monday = new Date(date.setDate(diff));
    const sunday = new Date(date.setDate(monday.getDate() + 6));
    monday.setHours(0,0,0,0);
    sunday.setHours(23,59,59,999);
    return { start: monday, end: sunday };
  };

  // --- Data Calculations ---

  // 1. Weekly Stats
  const weeklyStats = useMemo(() => {
    const { start, end } = getWeekRange(selectedWeekDate);
    const weekTrans = transactions.filter(t => {
      const d = new Date(t.date);
      return !t.isArchived && d >= start && d <= end;
    });

    const offerings = weekTrans.filter(t => t.category === 'Offerings & Tithes' && t.type === TransactionType.INCOME);
    const offeringsCash = offerings.filter(t => t.accountId === AccountType.CASH).reduce((acc, t) => acc + t.amount, 0);
    const offeringsMoMo = offerings.filter(t => t.accountId === AccountType.MOMO).reduce((acc, t) => acc + t.amount, 0);

    const snacks = weekTrans.filter(t => t.category === 'Snacks & Meals' && t.type === TransactionType.EXPENSE);
    const snacksCash = snacks.filter(t => t.accountId === AccountType.CASH).reduce((acc, t) => acc + t.amount, 0);
    const snacksMoMo = snacks.filter(t => t.accountId === AccountType.MOMO).reduce((acc, t) => acc + t.amount, 0);

    const otherExpenses = weekTrans.filter(t => t.category !== 'Snacks & Meals' && t.type === TransactionType.EXPENSE);
    const otherExpensesTotal = otherExpenses.reduce((acc, t) => acc + t.amount, 0);

    return {
        totalIncome: weekTrans.filter(t => t.type === TransactionType.INCOME).reduce((acc, t) => acc + t.amount, 0),
        totalExpense: weekTrans.filter(t => t.type === TransactionType.EXPENSE).reduce((acc, t) => acc + t.amount, 0),
        offerings: { cash: offeringsCash, momo: offeringsMoMo, total: offeringsCash + offeringsMoMo },
        snacks: { cash: snacksCash, momo: snacksMoMo, total: snacksCash + snacksMoMo },
        others: otherExpensesTotal,
        range: `${start.toLocaleDateString()} - ${end.toLocaleDateString()}`
    };
  }, [transactions, selectedWeekDate]);

  // 2. Monthly Stats
  const monthlyStats = useMemo(() => {
    const monthTrans = transactions.filter(t => {
      const d = new Date(t.date);
      return !t.isArchived && d.getFullYear() === selectedYear && d.getMonth() === selectedMonth;
    });
    const income = monthTrans.filter(t => t.type === TransactionType.INCOME).reduce((acc, t) => acc + t.amount, 0);
    const expense = monthTrans.filter(t => t.type === TransactionType.EXPENSE).reduce((acc, t) => acc + t.amount, 0);
    const sorted = [...monthTrans].sort((a,b) => new Date(b.date).getTime() - new Date(a.date).getTime()).slice(0, 5);
    return { income, expense, balance: income - expense, snippet: sorted };
  }, [transactions, selectedYear, selectedMonth]);

  // 3. Quarterly Stats
  const quarterlyStats = useMemo(() => {
    const months = getQuarterMonths(selectedQuarter);
    const chartData = months.map(m => {
        const mTrans = transactions.filter(t => {
            const d = new Date(t.date);
            return !t.isArchived && d.getFullYear() === selectedYear && d.getMonth() === m;
        });
        return {
            name: getMonthName(m).substring(0, 3),
            Income: mTrans.filter(t => t.type === TransactionType.INCOME).reduce((acc, t) => acc + t.amount, 0),
            Expense: mTrans.filter(t => t.type === TransactionType.EXPENSE).reduce((acc, t) => acc + t.amount, 0),
        };
    });
    const qTrans = transactions.filter(t => {
        const d = new Date(t.date);
        return !t.isArchived && d.getFullYear() === selectedYear && months.includes(d.getMonth());
    });
    const groupByCategory = (type: TransactionType) => {
        const map: Record<string, number> = {};
        qTrans.filter(t => t.type === type).forEach(t => {
            map[t.category] = (map[t.category] || 0) + t.amount;
        });
        return Object.entries(map).sort(([, a], [, b]) => b - a).slice(0, 3).map(([name, value]) => ({ name, value }));
    };
    return { chartData, topIncome: groupByCategory(TransactionType.INCOME), topExpense: groupByCategory(TransactionType.EXPENSE) };
  }, [transactions, selectedYear, selectedQuarter]);

  // 4. Yearly Stats
  const yearlyStats = useMemo(() => {
      const yearTrans = transactions.filter(t => !t.isArchived && new Date(t.date).getFullYear() === selectedYear);
      const chartData = Array.from({ length: 12 }, (_, i) => {
          const mTrans = yearTrans.filter(t => new Date(t.date).getMonth() === i);
          return {
              name: new Date(2025, i, 1).toLocaleString('default', { month: 'short' }),
              Income: mTrans.filter(t => t.type === TransactionType.INCOME).reduce((acc, t) => acc + t.amount, 0),
              Expense: mTrans.filter(t => t.type === TransactionType.EXPENSE).reduce((acc, t) => acc + t.amount, 0),
          };
      });
      const totalIncome = yearTrans.filter(t => t.type === TransactionType.INCOME).reduce((acc, t) => acc + t.amount, 0);
      const totalExpense = yearTrans.filter(t => t.type === TransactionType.EXPENSE).reduce((acc, t) => acc + t.amount, 0);
      return { chartData, totalIncome, totalExpense, balance: totalIncome - totalExpense };
  }, [transactions, selectedYear]);

  // --- Handlers ---

  const handleAddOfferingInput = () => setOfferingsInput([...offeringsInput, { type: 'CASH', amount: '' }]);
  const handleRemoveOfferingInput = (idx: number) => setOfferingsInput(offeringsInput.filter((_, i) => i !== idx));

  const handleAddPlanInput = () => setPlanInput([...planInput, { item: '', cost: '' }]);
  const handleRemovePlanInput = (idx: number) => setPlanInput(planInput.filter((_, i) => i !== idx));

  const saveWeeklyData = () => {
    let savedCount = 0;
    const today = new Date().toISOString().split('T')[0];

    // 1. Save Offerings
    offeringsInput.forEach(entry => {
        if (entry.amount && Number(entry.amount) > 0) {
            onAddTransaction({
                date: today,
                type: TransactionType.INCOME,
                category: 'Offerings & Tithes',
                amount: Number(entry.amount),
                accountId: entry.type === 'CASH' ? AccountType.CASH : AccountType.MOMO,
                notes: 'Weekly offering entry',
                isArchived: false
            });
            savedCount++;
        }
    });

    // 2. Save Plan (Consolidated)
    const validPlanItems = planInput.filter(p => p.item && p.cost && Number(p.cost) > 0);
    if (validPlanItems.length > 0) {
        const totalCost = validPlanItems.reduce((acc, p) => acc + Number(p.cost), 0);
        const itemNames = validPlanItems.map(p => `${p.item} (${p.cost})`).join(', ');

        onAddTransaction({
            date: today,
            type: TransactionType.EXPENSE,
            category: 'Snacks & Meals',
            amount: totalCost,
            accountId: AccountType.CASH,
            notes: `Planned items: ${itemNames}`,
            isArchived: false,
            meta: { isPlan: true }
        });
        savedCount++;
    }

    if (savedCount > 0) {
        alert(`Successfully saved ${savedCount} records.`);
        // Reset inputs
        setOfferingsInput([{ type: 'CASH', amount: '' }]);
        setPlanInput([{ item: '', cost: '' }]);
    } else {
        alert('No valid data to save.');
    }
  };

  const generatePDF = () => {
      const doc = new jsPDF();
      const pageWidth = doc.internal.pageSize.getWidth();
      const margin = 15;
      let yPos = 20;

      // Header
      doc.setFontSize(18);
      doc.setTextColor(15, 118, 110); // Primary color
      doc.text("Thesaurus Children's Finance", margin, yPos);
      yPos += 8;
      doc.setFontSize(10);
      doc.setTextColor(100);
      doc.text(`Report Type: ${activeTab} | Generated: ${new Date().toLocaleDateString()}`, margin, yPos);
      yPos += 15;

      doc.setDrawColor(200);
      doc.line(margin, yPos, pageWidth - margin, yPos);
      yPos += 10;

      if (activeTab === 'WEEKLY') {
          doc.setTextColor(0);
          doc.setFontSize(14);
          doc.text("Weekly Financial Summary", margin, yPos);
          yPos += 10;

          // Stats Table
          const cols = ["Category", "Cash", "MoMo", "Total"];
          const data = [
              ["Offerings & Tithes (Income)", formatCurrency(weeklyStats.offerings.cash), formatCurrency(weeklyStats.offerings.momo), formatCurrency(weeklyStats.offerings.total)],
              ["Snacks & Meals (Expense)", formatCurrency(weeklyStats.snacks.cash), formatCurrency(weeklyStats.snacks.momo), formatCurrency(weeklyStats.snacks.total)],
              ["Other Expenses", "-", "-", formatCurrency(weeklyStats.others)]
          ];

          doc.setFontSize(10);
          let colX = margin;
          // Simple table render
          cols.forEach((col, i) => {
              doc.setFont("helvetica", "bold");
              doc.text(col, colX + (i * 45), yPos);
          });
          yPos += 8;
          doc.setFont("helvetica", "normal");
          data.forEach(row => {
              row.forEach((cell, i) => {
                  doc.text(cell, colX + (i * 45), yPos);
              });
              yPos += 7;
          });

          yPos += 10;
          doc.setFont("helvetica", "bold");
          doc.text(`Net Weekly Position: ${formatCurrency(weeklyStats.totalIncome - weeklyStats.totalExpense)}`, margin, yPos);
          yPos += 20;

          // --- REQUEST GENERATION LOGIC ---
          // 1. Calculate total planned expenses for next week (from input state)
          const totalPlannedCost = planInput.reduce((acc, curr) => acc + (Number(curr.cost) || 0), 0);

          // 2. Logic: Deduct available CASH Offerings from the Planned Cost.
          // Note: Using weeklyStats.offerings.cash as "Cash at Hand" for this calculation logic per prompt interpretation
          const cashAvailable = weeklyStats.offerings.cash;
          const deficit = totalPlannedCost - cashAvailable;
          const requestAmount = deficit > 0 ? deficit : 0;
          const financeName = financeRep?.name || "Finance Director";

          if (totalPlannedCost > 0) {
              doc.setFontSize(12);
              doc.setTextColor(0);
              doc.text("Formal Request to Finance", margin, yPos);
              yPos += 8;

              doc.setFontSize(10);
              doc.setFont("helvetica", "normal");

              const greeting = `${getGreeting()} ${financeName}. I pray you are well.`;
              const body = `Could you kindly send ${formatCurrency(requestAmount)} to [Recipient Name] for the purchase of the following items for Children's Ministry? (Total Plan: ${formatCurrency(totalPlannedCost)} less Cash at Hand: ${formatCurrency(cashAvailable)})`;

              doc.text(greeting, margin, yPos);
              yPos += 6;
              const splitBody = doc.splitTextToSize(body, pageWidth - (margin * 2));
              doc.text(splitBody, margin, yPos);
              yPos += (splitBody.length * 5) + 5;

              doc.setFont("helvetica", "bold");
              doc.text("Planned Items:", margin, yPos);
              yPos += 6;
              doc.setFont("helvetica", "normal");

              planInput.filter(p => p.item).forEach(p => {
                  doc.text(`- ${p.item}: ${formatCurrency(Number(p.cost))}`, margin + 5, yPos);
                  yPos += 5;
              });
          }

      } else if (activeTab === 'MONTHLY') {
          doc.text(`Total Income: ${formatCurrency(monthlyStats.income)}`, margin, yPos);
          yPos += 8;
          doc.text(`Total Expense: ${formatCurrency(monthlyStats.expense)}`, margin, yPos);
          yPos += 8;
          doc.text(`Net Balance: ${formatCurrency(monthlyStats.balance)}`, margin, yPos);
      } else {
          doc.text("See dashboard for charts.", margin, yPos);
      }

      doc.save(`finance_report_${activeTab.toLowerCase()}.pdf`);
  };

  return (
    <div className="space-y-6">
      <div className="bg-white rounded-xl shadow-sm border border-gray-200 overflow-hidden">
        {/* Navigation Tabs */}
         <div className="flex border-b border-gray-100 overflow-x-auto no-scrollbar">
          {(['WEEKLY', 'MONTHLY', 'QUARTERLY', 'YEARLY'] as ReportType[]).map(tab => (
            <button
              key={tab}
              onClick={() => setActiveTab(tab)}
              className={`flex-1 min-w-[100px] py-4 text-sm font-semibold tracking-wide transition-colors whitespace-nowrap ${
                activeTab === tab ? 'bg-gray-50 text-primary border-b-2 border-primary' : 'text-gray-500 hover:bg-gray-50'
              }`}
            >
              {tab}
            </button>
          ))}
        </div>

        <div className="p-4 sm:p-6 bg-gray-50/50 min-h-[400px]">
            {/* Header & Controls */}
            <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center mb-6 gap-4">
                <div className="flex flex-col">
                    <h3 className="text-xl font-bold text-gray-800 capitalize">{activeTab.toLowerCase()} Report</h3>
                    {activeTab === 'WEEKLY' && <span className="text-sm text-gray-500">{weeklyStats.range}</span>}
                </div>

                <div className="flex flex-wrap gap-2 w-full sm:w-auto">
                    {/* Controls based on active tab */}
                    {activeTab === 'WEEKLY' && (
                         <input 
                            type="date" 
                            className="p-2 border rounded-md text-sm bg-white"
                            value={selectedWeekDate}
                            onChange={(e) => setSelectedWeekDate(e.target.value)}
                         />
                    )}

                    {(activeTab === 'MONTHLY' || activeTab === 'QUARTERLY' || activeTab === 'YEARLY') && (
                        <select 
                            className="p-2 border rounded-md text-sm bg-white"
                            value={selectedYear}
                            onChange={(e) => setSelectedYear(Number(e.target.value))}
                        >
                            {[2024, 2025, 2026].map(y => <option key={y} value={y}>{y}</option>)}
                        </select>
                    )}

                    {activeTab === 'MONTHLY' && (
                        <select 
                            className="p-2 border rounded-md text-sm bg-white"
                            value={selectedMonth}
                            onChange={(e) => setSelectedMonth(Number(e.target.value))}
                        >
                            {Array.from({length: 12}, (_, i) => (
                                <option key={i} value={i}>{getMonthName(i)}</option>
                            ))}
                        </select>
                    )}

                    {activeTab === 'QUARTERLY' && (
                        <select 
                            className="p-2 border rounded-md text-sm bg-white"
                            value={selectedQuarter}
                            onChange={(e) => setSelectedQuarter(Number(e.target.value))}
                        >
                            <option value={1}>Q1 (Jan-Mar)</option>
                            <option value={2}>Q2 (Apr-Jun)</option>
                            <option value={3}>Q3 (Jul-Sep)</option>
                            <option value={4}>Q4 (Oct-Dec)</option>
                        </select>
                    )}

                    <button 
                        onClick={generatePDF}
                        className="flex items-center px-4 py-2 bg-gray-800 text-white rounded-lg hover:bg-gray-700 transition-colors text-sm shadow-sm"
                    >
                        <FileText size={16} className="mr-2" /> PDF Report
                    </button>
                </div>
            </div>

            {/* --- WEEKLY VIEW --- */}
            {activeTab === 'WEEKLY' && (
                <div className="space-y-8 animate-in fade-in duration-300">
                    {/* 1. Statistics Section */}
                    <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                        {/* Income Breakdown */}
