import React, { useState, useEffect } from 'react';
import { Transaction, TransactionType, AccountType, Category } from '../types';
import { formatCurrency } from '../utils';
import { Search, Plus, Save, X, Archive, ArrowRight, Filter, Eye, EyeOff } from 'lucide-react';

interface TransactionsProps {
  transactions: Transaction[];
  categories: Category[];
  accounts: AccountType[];
  preSelectedAccount: AccountType | null;
  onAddTransaction: (t: Omit<Transaction, 'id'>) => void;
  onDeleteTransaction: (id: string) => void;
}

type TabType = 'INCOME' | 'EXPENSE' | 'TRANSFER';

const Transactions: React.FC<TransactionsProps> = ({ 
  transactions, 
  categories, 
  accounts, 
  preSelectedAccount,
  onAddTransaction,
  onDeleteTransaction
}) => {
  const [activeTab, setActiveTab] = useState<TabType>('INCOME');
  const [filterAccount, setFilterAccount] = useState<string>(preSelectedAccount || 'ALL');
  const [searchTerm, setSearchTerm] = useState('');
  const [showArchived, setShowArchived] = useState(false);

  const [entries, setEntries] = useState<any[]>([{ 
    amount: '', 
    date: new Date().toISOString().split('T')[0],
    category: '',
    accountId: '',
    toAccountId: '',
    recipient: '',
    notes: '',
    receivedFromFinance: false
  }]);

  useEffect(() => {
    if (preSelectedAccount) setFilterAccount(preSelectedAccount);
  }, [preSelectedAccount]);

  const handleAddEntry = () => {
    setEntries([...entries, { 
      amount: '', 
      date: new Date().toISOString().split('T')[0],
      category: '',
      accountId: '',
      toAccountId: '',
      recipient: '',
      notes: '',
      receivedFromFinance: false
    }]);
  };

  const handleRemoveEntry = (index: number) => {
    if (entries.length > 1) {
      setEntries(entries.filter((_, i) => i !== index));
    }
  };

  const updateEntry = (index: number, field: string, value: any) => {
    const newEntries = [...entries];
    newEntries[index] = { ...newEntries[index], [field]: value };
    setEntries(newEntries);
  };

  const validateAndSave = () => {
    for (const entry of entries) {
      if (!entry.amount || Number(entry.amount) <= 0) {
        alert('Please enter a valid amount.');
        return;
      }
      if (!entry.date) {
        alert('Please select a date.');
        return;
      }
      if (activeTab !== 'TRANSFER' && !entry.category) {
        alert('Please select a category.');
        return;
      }
      if (!entry.accountId) {
        alert('Please select an account.');
        return;
      }
      if (activeTab === 'TRANSFER' && !entry.toAccountId) {
         alert('Please select a destination account.');
         return;
      }
    }

    entries.forEach(entry => {
      onAddTransaction({
        date: entry.date,
        amount: Number(entry.amount),
        type: activeTab === 'INCOME' ? TransactionType.INCOME : activeTab === 'EXPENSE' ? TransactionType.EXPENSE : TransactionType.TRANSFER,
        category: activeTab === 'TRANSFER' ? 'Finance Transfer' : entry.category,
        accountId: entry.accountId,
        toAccountId: activeTab === 'TRANSFER' ? entry.toAccountId : undefined,
        recipient: entry.recipient,
        notes: entry.notes,
        isArchived: false,
        meta: {
            receivedFromFinance: entry.receivedFromFinance
        }
      });
    });

    setEntries([{ 
      amount: '', 
      date: new Date().toISOString().split('T')[0],
      category: '',
      accountId: '',
      toAccountId: '',
      recipient: '',
      notes: '',
      receivedFromFinance: false
    }]);
    alert('Transaction(s) saved successfully!');
  };

  const filteredList = transactions
    .filter(t => showArchived ? true : !t.isArchived)
    .filter(t => filterAccount === 'ALL' || t.accountId === filterAccount || t.toAccountId === filterAccount)
    .filter(t => 
      t.category.toLowerCase().includes(searchTerm.toLowerCase()) || 
      t.notes?.toLowerCase().includes(searchTerm.toLowerCase()) ||
      t.recipient?.toLowerCase().includes(searchTerm.toLowerCase())
    )
    .sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());

  return (
    <div className="space-y-6">
      <div className="bg-white rounded-xl shadow-sm border border-gray-200 overflow-hidden">
        {/* Form Tabs */}
        <div className="flex border-b border-gray-100 overflow-x-auto no-scrollbar">
          {(['INCOME', 'EXPENSE', 'TRANSFER'] as TabType[]).map(tab => (
            <button
              key={tab}
              onClick={() => setActiveTab(tab)}
              className={`flex-1 min-w-[100px] py-4 text-sm font-semibold tracking-wide transition-colors whitespace-nowrap ${
                activeTab === tab 
                  ? tab === 'INCOME' ? 'bg-emerald-50 text-emerald-700 border-b-2 border-emerald-500' 
                    : tab === 'EXPENSE' ? 'bg-rose-50 text-rose-700 border-b-2 border-rose-500'
                    : 'bg-blue-50 text-blue-700 border-b-2 border-blue-500'
                  : 'text-gray-500 hover:bg-gray-50'
              }`}
            >
              {tab}
            </button>
          ))}
        </div>

        {/* Form Body */}
        <div className="p-4 sm:p-6">
          <div className="space-y-6">
            {entries.map((entry, index) => (
              <div key={index} className="relative p-4 bg-gray-50 rounded-lg border border-gray-200 space-y-4">
                {entries.length > 1 && (
                    <button onClick={() => handleRemoveEntry(index)} className="absolute top-2 right-2 text-red-400 hover:text-red-600 z-10 p-1 bg-white rounded-full shadow-sm border border-gray-200">
                        <X size={16} />
                    </button>
                )}

                <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
                  <div>
                    <label className="block text-xs font-medium text-gray-500 mb-1">Date</label>
                    <input 
                        type="date" 
                        value={entry.date}
                        onChange={(e) => updateEntry(index, 'date', e.target.value)}
                        className="w-full rounded-md border-gray-300 shadow-sm focus:ring-primary focus:border-primary p-2 border text-sm"
                    />
                  </div>

                  <div>
                    <label className="block text-xs font-medium text-gray-500 mb-1">Value (GHC)</label>
                    <input 
                        type="number" 
                        placeholder="0.00"
                        value={entry.amount}
                        onChange={(e) => updateEntry(index, 'amount', e.target.value)}
                        className="w-full rounded-md border-gray-300 shadow-sm focus:ring-primary focus:border-primary p-2 border text-sm"
                    />
                  </div>

                  {activeTab !== 'TRANSFER' && (
                    <div className="sm:col-span-2">
                        <label className="block text-xs font-medium text-gray-500 mb-1">Category</label>
                        <select 
                            value={entry.category}
                            onChange={(e) => updateEntry(index, 'category', e.target.value)}
                            className="w-full rounded-md border-gray-300 shadow-sm focus:ring-primary focus:border-primary p-2 border text-sm"
                        >
                            <option value="">Select Category...</option>
                            {categories
                                .filter(c => c.type === 'BOTH' || c.type === activeTab)
                                .map(c => <option key={c.id} value={c.name}>{c.name}</option>)}
                        </select>
                    </div>
                  )}
                </div>

                <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                   <div>
                        <label className="block text-xs font-medium text-gray-500 mb-1">
                            {activeTab === 'TRANSFER' ? 'From Account' : 'Account'}
                        </label>
                        <select 
                            value={entry.accountId}
                            onChange={(e) => updateEntry(index, 'accountId', e.target.value)}
                            className="w-full rounded-md border-gray-300 shadow-sm focus:ring-primary focus:border-primary p-2 border text-sm"
                        >
                            <option value="">Select Account...</option>
                            {accounts.map(a => <option key={a} value={a}>{a}</option>)}
                        </select>

                        {activeTab === 'EXPENSE' && entry.accountId === AccountType.MOMO && (
                            <div className="mt-3 flex items-start">
                                <input 
                                    type="checkbox" 
                                    id={`finance-check-${index}`}
                                    checked={entry.receivedFromFinance}
                                    onChange={(e) => updateEntry(index, 'receivedFromFinance', e.target.checked)}
                                    className="mt-0.5 h-4 w-4 text-primary focus:ring-primary border-gray-300 rounded"
                                />
                                <label htmlFor={`finance-check-${index}`} className="ml-2 block text-xs text-red-600 font-medium leading-tight">
                                    Was this digital cash received from Finance? (Mandatory)
                                </label>
                            </div>
                        )}
                   </div>

                   {activeTab === 'TRANSFER' ? (
                       <div>
                            <label className="block text-xs font-medium text-gray-500 mb-1">To Account</label>
                            <select 
                                value={entry.toAccountId}
                                onChange={(e) => updateEntry(index, 'toAccountId', e.target.value)}
                                className="w-full rounded-md border-gray-300 shadow-sm focus:ring-primary focus:border-primary p-2 border text-sm"
                            >
                                <option value="">Select Account...</option>
                                {accounts.map(a => <option key={a} value={a}>{a}</option>)}
                            </select>
                       </div>
                   ) : (
                       <div>
                           <label className="block text-xs font-medium text-gray-500 mb-1">From/To (Optional)</label>
                           <input 
                                type="text"
                                placeholder="Recipient Name"
                                value={entry.recipient}
                                onChange={(e) => updateEntry(index, 'recipient', e.target.value)}
                                className="w-full rounded-md border-gray-300 shadow-sm focus:ring-primary focus:border-primary p-2 border text-sm"
                            />
                       </div>
                   )}
                </div>

                <div>
                    <label className="block text-xs font-medium text-gray-500 mb-1">Notes (Optional)</label>
                    <textarea 
                        rows={2}
                        value={entry.notes}
                        onChange={(e) => updateEntry(index, 'notes', e.target.value)}
                        className="w-full rounded-md border-gray-300 shadow-sm focus:ring-primary focus:border-primary p-2 border text-sm"
                        placeholder="Add details here..."
                    />
                </div>
              </div>
            ))}

            <div className="flex flex-col sm:flex-row justify-between items-center gap-4">
                <button 
                    onClick={handleAddEntry}
                    className="w-full sm:w-auto flex items-center justify-center text-sm font-medium text-primary hover:text-teal-800 p-2"
                >
                    <Plus size={16} className="mr-1" /> Add another entry
                </button>
                <button 
                    onClick={validateAndSave}
                    className={`w-full sm:w-auto flex items-center justify-center px-6 py-2.5 rounded-lg text-white font-medium shadow-sm transition-colors ${
                        activeTab === 'INCOME' ? 'bg-emerald-600 hover:bg-emerald-700' 
                        : activeTab === 'EXPENSE' ? 'bg-rose-600 hover:bg-rose-700' 
                        : 'bg-blue-600 hover:bg-blue-700'
                    }`}
                >
                    <Save size={18} className="mr-2" /> Save Transaction
                </button>
            </div>
          </div>
        </div>
      </div>

      {/* Transaction List */}
      <div className="bg-white rounded-xl shadow-sm border border-gray-200">
        <div className="p-4 border-b border-gray-100 flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
            <h3 className="font-bold text-gray-800">History</h3>
            <div className="flex flex-col sm:flex-row gap-2 w-full md:w-auto">
                <div className="relative flex-1">
                    <Search className="absolute left-2 top-2.5 text-gray-400" size={16} />
                    <input 
                        type="text" 
                        placeholder="Search..." 
                        value={searchTerm}
                        onChange={(e) => setSearchTerm(e.target.value)}
                        className="pl-8 pr-4 py-2 bg-gray-50 border border-gray-200 rounded-lg text-sm focus:outline-none focus:ring-1 focus:ring-primary w-full"
                    />
                </div>

                <div className="flex gap-2">
                    <button
                        onClick={() => setShowArchived(!showArchived)}
                        className={`flex items-center gap-1.5 px-3 py-2 rounded-lg text-sm border transition-colors whitespace-nowrap ${
                            showArchived 
                            ? 'bg-gray-800 text-white border-gray-800' 
                            : 'bg-white text-gray-600 border-gray-200 hover:bg-gray-50'
                        }`}
                        title={showArchived ? "Hide Archived" : "Show Archived"}
                    >
                        {showArchived ? <EyeOff size={16} /> : <Eye size={16} />}
                        <span className="hidden sm:inline">{showArchived ? 'Hide Archived' : 'Show Archived'}</span>
                    </button>

                    <select 
                        value={filterAccount}
                        onChange={(e) => setFilterAccount(e.target.value)}
                        className="py-2 px-3 bg-gray-50 border border-gray-200 rounded-lg text-sm focus:outline-none focus:ring-1 focus:ring-primary w-full sm:w-auto"
                    >
                        <option value="ALL">All Accounts</option>
                        {accounts.map(a => <option key={a} value={a}>{a}</option>)}
                    </select>
                </div>
            </div>
        </div>

        {/* Desktop Table View */}
        <div className="hidden md:block overflow-x-auto w-full">
            <div className="min-w-full">
                <table className="w-full text-left text-sm text-gray-600 table-auto">
                    <thead className="bg-gray-50 text-gray-700 font-semibold uppercase text-xs">
                        <tr>
                            <th className="px-4 py-3 w-28">Date</th>
                            <th className="px-4 py-3 w-40">Category</th>
                            <th className="px-4 py-3 w-40">Account</th>
                            <th className="px-4 py-3 w-28 text-right">Amount</th>
                            <th className="px-4 py-3">Notes</th>
                            <th className="px-4 py-3 w-16 text-center">Action</th>
                        </tr>
                    </thead>
                    <tbody className="divide-y divide-gray-100">
                        {filteredList.length === 0 ? (
                            <tr><td colSpan={6} className="px-4 py-8 text-center text-gray-400">No transactions found.</td></tr>
                        ) : (
                            filteredList.map(t => (
                                <tr key={t.id} className={`group transition-colors ${t.isArchived ? 'bg-gray-50 opacity-75' : 'hover:bg-gray-50'}`}>
                                    <td className="px-4 py-3 whitespace-nowrap">
                                        {t.date}
                                        {t.isArchived && <span className="block text-[10px] text-gray-400 font-bold uppercase tracking-wider mt-0.5">Archived</span>}
                                    </td>
                                    <td className="px-4 py-3">
                                        <span className={`inline-flex items-center px-2 py-0.5 rounded text-xs font-medium whitespace-nowrap ${
                                            t.isArchived ? 'bg-gray-200 text-gray-500' :
                                            t.type === TransactionType.INCOME ? 'bg-emerald-100 text-emerald-800' : 
                                            t.type === TransactionType.EXPENSE ? 'bg-rose-100 text-rose-800' : 'bg-blue-100 text-blue-800'
                                        }`}>
                                            {t.category}
                                        </span>
                                    </td>
                                    <td className="px-4 py-3">
                                        <div className="flex flex-col">
                                            <span className="truncate max-w-[150px]" title={t.accountId}>{t.accountId}</span>
                                            {t.type === TransactionType.TRANSFER && (
                                                <span className="flex items-center text-xs text-gray-400 mt-0.5 truncate max-w-[150px]">
                                                    <ArrowRight size={10} className="mr-1" /> {t.toAccountId}
                                                </span>
                                            )}
                                        </div>
                                    </td>
                                    <td className={`px-4 py-3 text-right font-bold whitespace-nowrap ${
                                        t.isArchived ? 'text-gray-500' :
                                        t.type === TransactionType.INCOME ? 'text-emerald-600' : 'text-rose-600'
                                    }`}>
                                        {t.type === TransactionType.EXPENSE ? '-' : ''}{formatCurrency(t.amount)}
                                    </td>
                                    <td className="px-4 py-3 max-w-xs truncate text-gray-500" title={t.notes}>
                                        {t.notes || '-'}
                                    </td>
                                    <td className="px-4 py-3 text-center">
                                        {!t.isArchived ? (
                                            <button 
                                                onClick={() => {
                                                    if (window.confirm('Archive this transaction?')) {
                                                        onDeleteTransaction(t.id);
                                                    }
                                                }}
                                                className="text-gray-400 hover:text-rose-600 p-1 transition-colors"
                                                title="Archive"
                                            >
                                                <Archive size={16} />
                                            </button>
                                        ) : (
                                            <span className="text-gray-300 cursor-not-allowed" title="Already Archived">
                                                <Archive size={16} />
                                            </span>
                                        )}
                                    </td>
                                </tr>
                            ))
                        )}
                    </tbody>
                </table>
            </div>
        </div>

        {/* Mobile Card View */}
        <div className="md:hidden divide-y divide-gray-100 bg-gray-50 p-2 space-y-3">
             {filteredList.length === 0 ? (
                <div className="px-4 py-8 text-center text-gray-400 text-sm">No transactions found.</div>
             ) : (
                filteredList.map(t => (
                    <div key={t.id} className={`p-4 rounded-lg shadow-sm border border-gray-200 flex flex-col gap-3 ${t.isArchived ? 'bg-gray-100 border-gray-300 opacity-80' : 'bg-white'}`}>
                        <div className="flex justify-between items-start">
                            <div>
                                <div className="flex items-center gap-2 mb-1">
                                    <span className={`text-xs font-medium px-1.5 py-0.5 rounded ${t.isArchived ? 'bg-gray-200 text-gray-500' : 'bg-gray-100 text-gray-400'}`}>{t.date}</span>
                                    {t.isArchived && <span className="text-[10px] font-bold bg-gray-600 text-white px-1.5 py-0.5 rounded uppercase">Archived</span>}
                                    <span className={`text-[10px] px-1.5 py-0.5 rounded font-medium border ${
                                        t.isArchived ? 'bg-gray-200 text-gray-500 border-gray-300' :
                                        t.type === TransactionType.INCOME ? 'bg-emerald-50 text-emerald-700 border-emerald-100' :
                                        t.type === TransactionType.EXPENSE ? 'bg-rose-50 text-rose-700 border-rose-100' : 'bg-blue-50 text-blue-700 border-blue-100'
                                    }`}>{t.type.slice(0,3)}</span>
                                </div>
                                <h4 className={`font-bold text-sm ${t.isArchived ? 'text-gray-600' : 'text-gray-800'}`}>{t.category}</h4>
                            </div>
                             <span className={`font-bold text-base ${
                                t.isArchived ? 'text-gray-500' :
                                t.type === TransactionType.INCOME ? 'text-emerald-600' : 'text-rose-600'
                            }`}>
                                {t.type === TransactionType.EXPENSE ? '-' : ''}{formatCurrency(t.amount)}
                            </span>
                        </div>

                        <div className={`text-sm space-y-1.5 p-2.5 rounded-md border ${t.isArchived ? 'bg-gray-100 border-gray-200 text-gray-500' : 'bg-gray-50 border-gray-100 text-gray-600'}`}>
                             <div className="flex justify-between items-center">
                                 <span className="text-xs font-medium opacity-70">Account:</span>
                                 <span className="font-medium text-xs">{t.accountId}</span>
                             </div>
                             {t.type === TransactionType.TRANSFER && (
                                 <div className="flex justify-between items-center">
                                    <span className="text-xs font-medium opacity-70">To:</span>
                                    <span className="font-medium text-xs flex items-center"><ArrowRight size={10} className="mx-1"/> {t.toAccountId}</span>
                                 </div>
                             )}
                             {t.recipient && (
                                 <div className="flex justify-between items-center">
                                    <span className="text-xs font-medium opacity-70">Recipient:</span>
                                    <span className="font-medium text-xs">{t.recipient}</span>
                                 </div>
                             )}
                             {t.notes && (
                                 <div className={`pt-1.5 mt-1 border-t ${t.isArchived ? 'border-gray-300' : 'border-gray-200'}`}>
                                    <p className="text-xs italic opacity-80 leading-snug">{t.notes}</p>
                                 </div>
                             )}
                        </div>

                        {!t.isArchived && (
                            <div className="flex justify-end pt-1">
                                 <button 
                                    type="button"
                                    onClick={(e) => {
                                        e.stopPropagation();
                                        if (window.confirm('Are you sure you want to archive this transaction?')) {
                                            onDeleteTransaction(t.id);
                                        }
                                    }}
                                    className="flex items-center gap-1.5 px-3 py-2 text-xs font-bold text-rose-600 bg-rose-50 hover:bg-rose-100 rounded-lg transition-colors border border-rose-100 w-full justify-center sm:w-auto"
                                >
                                    <Archive size={14} />
                                    Archive Record
                                </button>
                            </div>
                        )}
                    </div>
                ))
             )}
        </div>
      </div>
    </div>
  );
};

export default Transactions;

import React, { useState, useMemo } from 'react';
import { Transaction, TransactionType, User, AccountType } from '../types';
import { formatCurrency, getGreeting } from '../utils';
import { jsPDF } from 'jspdf';
import { FileText, Calendar, TrendingUp, TrendingDown, Plus, Save, Trash2, Award, Download, ArrowRight } from 'lucide-react';
import { 
  BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, Legend, ResponsiveContainer, 
  AreaChart, Area
} from 'recharts';

interface ReportsProps {
  transactions: Transaction[];
  users: User[];
  onAddTransaction: (t: Omit<Transaction, 'id'>) => void;
  financeRep: User | undefined;
}

type ReportType = 'WEEKLY' | 'MONTHLY' | 'QUARTERLY' | 'YEARLY';

const Reports: React.FC<ReportsProps> = ({ transactions, users, onAddTransaction, financeRep }) => {
  const [activeTab, setActiveTab] = useState<ReportType>('WEEKLY');
  const [selectedYear, setSelectedYear] = useState(new Date().getFullYear());
  const [selectedMonth, setSelectedMonth] = useState(new Date().getMonth());
  const [selectedQuarter, setSelectedQuarter] = useState(Math.floor(new Date().getMonth() / 3) + 1);
  const [selectedWeekDate, setSelectedWeekDate] = useState(new Date().toISOString().split('T')[0]);

  // --- Weekly Input States ---
  const [offeringsInput, setOfferingsInput] = useState<{type: 'CASH' | 'MOMO', amount: string}[]>([
    { type: 'CASH', amount: '' }
  ]);
  const [planInput, setPlanInput] = useState<{item: string, cost: string}[]>([
    { item: '', cost: '' }
  ]);

  // --- Helpers ---
  const getQuarterMonths = (q: number) => {
    const start = (q - 1) * 3;
    return [start, start + 1, start + 2];
  };

  const getMonthName = (monthIndex: number) => {
    return new Date(2025, monthIndex, 1).toLocaleString('default', { month: 'long' });
  };

  const getWeekRange = (dateStr: string) => {
    const date = new Date(dateStr);
    const day = date.getDay(); // 0 (Sun) to 6 (Sat)
    const diff = date.getDate() - day + (day === 0 ? -6 : 1); // Adjust to get Monday
    const monday = new Date(date.setDate(diff));
    const sunday = new Date(date.setDate(monday.getDate() + 6));
    monday.setHours(0,0,0,0);
    sunday.setHours(23,59,59,999);
    return { start: monday, end: sunday };
  };

  // --- Data Calculations ---

  // 1. Weekly Stats
  const weeklyStats = useMemo(() => {
    const { start, end } = getWeekRange(selectedWeekDate);
    const weekTrans = transactions.filter(t => {
      const d = new Date(t.date);
      return !t.isArchived && d >= start && d <= end;
    });

    const offerings = weekTrans.filter(t => t.category === 'Offerings & Tithes' && t.type === TransactionType.INCOME);
    const offeringsCash = offerings.filter(t => t.accountId === AccountType.CASH).reduce((acc, t) => acc + t.amount, 0);
    const offeringsMoMo = offerings.filter(t => t.accountId === AccountType.MOMO).reduce((acc, t) => acc + t.amount, 0);

    const snacks = weekTrans.filter(t => t.category === 'Snacks & Meals' && t.type === TransactionType.EXPENSE);
    const snacksCash = snacks.filter(t => t.accountId === AccountType.CASH).reduce((acc, t) => acc + t.amount, 0);
    const snacksMoMo = snacks.filter(t => t.accountId === AccountType.MOMO).reduce((acc, t) => acc + t.amount, 0);

    const otherExpenses = weekTrans.filter(t => t.category !== 'Snacks & Meals' && t.type === TransactionType.EXPENSE);
    const otherExpensesTotal = otherExpenses.reduce((acc, t) => acc + t.amount, 0);

    return {
        totalIncome: weekTrans.filter(t => t.type === TransactionType.INCOME).reduce((acc, t) => acc + t.amount, 0),
        totalExpense: weekTrans.filter(t => t.type === TransactionType.EXPENSE).reduce((acc, t) => acc + t.amount, 0),
        offerings: { cash: offeringsCash, momo: offeringsMoMo, total: offeringsCash + offeringsMoMo },
        snacks: { cash: snacksCash, momo: snacksMoMo, total: snacksCash + snacksMoMo },
        others: otherExpensesTotal,
        range: `${start.toLocaleDateString()} - ${end.toLocaleDateString()}`
    };
  }, [transactions, selectedWeekDate]);

  // 2. Monthly Stats
  const monthlyStats = useMemo(() => {
    const monthTrans = transactions.filter(t => {
      const d = new Date(t.date);
      return !t.isArchived && d.getFullYear() === selectedYear && d.getMonth() === selectedMonth;
    });
    const income = monthTrans.filter(t => t.type === TransactionType.INCOME).reduce((acc, t) => acc + t.amount, 0);
    const expense = monthTrans.filter(t => t.type === TransactionType.EXPENSE).reduce((acc, t) => acc + t.amount, 0);
    const sorted = [...monthTrans].sort((a,b) => new Date(b.date).getTime() - new Date(a.date).getTime()).slice(0, 5);
    return { income, expense, balance: income - expense, snippet: sorted };
  }, [transactions, selectedYear, selectedMonth]);

  // 3. Quarterly Stats
  const quarterlyStats = useMemo(() => {
    const months = getQuarterMonths(selectedQuarter);
    const chartData = months.map(m => {
        const mTrans = transactions.filter(t => {
            const d = new Date(t.date);
            return !t.isArchived && d.getFullYear() === selectedYear && d.getMonth() === m;
        });
        return {
            name: getMonthName(m).substring(0, 3),
            Income: mTrans.filter(t => t.type === TransactionType.INCOME).reduce((acc, t) => acc + t.amount, 0),
            Expense: mTrans.filter(t => t.type === TransactionType.EXPENSE).reduce((acc, t) => acc + t.amount, 0),
        };
    });
    const qTrans = transactions.filter(t => {
        const d = new Date(t.date);
        return !t.isArchived && d.getFullYear() === selectedYear && months.includes(d.getMonth());
    });
    const groupByCategory = (type: TransactionType) => {
        const map: Record<string, number> = {};
        qTrans.filter(t => t.type === type).forEach(t => {
            map[t.category] = (map[t.category] || 0) + t.amount;
        });
        return Object.entries(map).sort(([, a], [, b]) => b - a).slice(0, 3).map(([name, value]) => ({ name, value }));
    };
    return { chartData, topIncome: groupByCategory(TransactionType.INCOME), topExpense: groupByCategory(TransactionType.EXPENSE) };
  }, [transactions, selectedYear, selectedQuarter]);

  // 4. Yearly Stats
  const yearlyStats = useMemo(() => {
      const yearTrans = transactions.filter(t => !t.isArchived && new Date(t.date).getFullYear() === selectedYear);
      const chartData = Array.from({ length: 12 }, (_, i) => {
          const mTrans = yearTrans.filter(t => new Date(t.date).getMonth() === i);
          return {
              name: new Date(2025, i, 1).toLocaleString('default', { month: 'short' }),
              Income: mTrans.filter(t => t.type === TransactionType.INCOME).reduce((acc, t) => acc + t.amount, 0),
              Expense: mTrans.filter(t => t.type === TransactionType.EXPENSE).reduce((acc, t) => acc + t.amount, 0),
          };
      });
      const totalIncome = yearTrans.filter(t => t.type === TransactionType.INCOME).reduce((acc, t) => acc + t.amount, 0);
      const totalExpense = yearTrans.filter(t => t.type === TransactionType.EXPENSE).reduce((acc, t) => acc + t.amount, 0);
      return { chartData, totalIncome, totalExpense, balance: totalIncome - totalExpense };
  }, [transactions, selectedYear]);

  // --- Handlers ---

  const handleAddOfferingInput = () => setOfferingsInput([...offeringsInput, { type: 'CASH', amount: '' }]);
  const handleRemoveOfferingInput = (idx: number) => setOfferingsInput(offeringsInput.filter((_, i) => i !== idx));

  const handleAddPlanInput = () => setPlanInput([...planInput, { item: '', cost: '' }]);
  const handleRemovePlanInput = (idx: number) => setPlanInput(planInput.filter((_, i) => i !== idx));

  const saveWeeklyData = () => {
    let savedCount = 0;
    const today = new Date().toISOString().split('T')[0];

    // 1. Save Offerings
    offeringsInput.forEach(entry => {
        if (entry.amount && Number(entry.amount) > 0) {
            onAddTransaction({
                date: today,
                type: TransactionType.INCOME,
                category: 'Offerings & Tithes',
                amount: Number(entry.amount),
                accountId: entry.type === 'CASH' ? AccountType.CASH : AccountType.MOMO,
                notes: 'Weekly offering entry',
                isArchived: false
            });
            savedCount++;
        }
    });

    // 2. Save Plan (Consolidated)
    const validPlanItems = planInput.filter(p => p.item && p.cost && Number(p.cost) > 0);
    if (validPlanItems.length > 0) {
        const totalCost = validPlanItems.reduce((acc, p) => acc + Number(p.cost), 0);
        const itemNames = validPlanItems.map(p => `${p.item} (${p.cost})`).join(', ');

        onAddTransaction({
            date: today,
            type: TransactionType.EXPENSE,
            category: 'Snacks & Meals',
            amount: totalCost,
            accountId: AccountType.CASH,
            notes: `Planned items: ${itemNames}`,
            isArchived: false,
            meta: { isPlan: true }
        });
        savedCount++;
    }

    if (savedCount > 0) {
        alert(`Successfully saved ${savedCount} records.`);
        // Reset inputs
        setOfferingsInput([{ type: 'CASH', amount: '' }]);
        setPlanInput([{ item: '', cost: '' }]);
    } else {
        alert('No valid data to save.');
    }
  };

  const generatePDF = () => {
      const doc = new jsPDF();
      const pageWidth = doc.internal.pageSize.getWidth();
      const margin = 15;
      let yPos = 20;

      // Header
      doc.setFontSize(18);
      doc.setTextColor(15, 118, 110); // Primary color
      doc.text("Thesaurus Children's Finance", margin, yPos);
      yPos += 8;
      doc.setFontSize(10);
      doc.setTextColor(100);
      doc.text(`Report Type: ${activeTab} | Generated: ${new Date().toLocaleDateString()}`, margin, yPos);
      yPos += 15;

      doc.setDrawColor(200);
      doc.line(margin, yPos, pageWidth - margin, yPos);
      yPos += 10;

      if (activeTab === 'WEEKLY') {
          doc.setTextColor(0);
          doc.setFontSize(14);
          doc.text("Weekly Financial Summary", margin, yPos);
          yPos += 10;

          // Stats Table
          const cols = ["Category", "Cash", "MoMo", "Total"];
          const data = [
              ["Offerings & Tithes (Income)", formatCurrency(weeklyStats.offerings.cash), formatCurrency(weeklyStats.offerings.momo), formatCurrency(weeklyStats.offerings.total)],
              ["Snacks & Meals (Expense)", formatCurrency(weeklyStats.snacks.cash), formatCurrency(weeklyStats.snacks.momo), formatCurrency(weeklyStats.snacks.total)],
              ["Other Expenses", "-", "-", formatCurrency(weeklyStats.others)]
          ];

          doc.setFontSize(10);
          let colX = margin;
          // Simple table render
          cols.forEach((col, i) => {
              doc.setFont("helvetica", "bold");
              doc.text(col, colX + (i * 45), yPos);
          });
          yPos += 8;
          doc.setFont("helvetica", "normal");
          data.forEach(row => {
              row.forEach((cell, i) => {
                  doc.text(cell, colX + (i * 45), yPos);
              });
              yPos += 7;
          });

          yPos += 10;
          doc.setFont("helvetica", "bold");
          doc.text(`Net Weekly Position: ${formatCurrency(weeklyStats.totalIncome - weeklyStats.totalExpense)}`, margin, yPos);
          yPos += 20;

          // --- REQUEST GENERATION LOGIC ---
          const totalPlannedCost = planInput.reduce((acc, curr) => acc + (Number(curr.cost) || 0), 0);
          const cashAvailable = weeklyStats.offerings.cash;
          const deficit = totalPlannedCost - cashAvailable;
          const requestAmount = deficit > 0 ? deficit : 0;
          const financeName = financeRep?.name || "Finance Director";

          if (totalPlannedCost > 0) {
              doc.setFontSize(12);
              doc.setTextColor(0);
              doc.text("Formal Request to Finance", margin, yPos);
              yPos += 8;

              doc.setFontSize(10);
              doc.setFont("helvetica", "normal");

              const greeting = `${getGreeting()} ${financeName}. I pray you are well.`;
