                                    <Tooltip contentStyle={{borderRadius: '12px', border: 'none', boxShadow: '0 10px 15px -3px rgb(0 0 0 / 0.1)'}} formatter={(value: number) => formatCurrency(value)} />
                                    <Area type="monotone" dataKey="Income" stroke="#10b981" strokeWidth={3} fillOpacity={1} fill="url(#colorInc)" />
                                    <Area type="monotone" dataKey="Expense" stroke="#f43f5e" strokeWidth={3} fillOpacity={1} fill="url(#colorExp)" />
                                </AreaChart>
                            </ResponsiveContainer>
                        </div>
                    </div>
                </div>
            )}
        </div>
      </div>
    </div>
  );
};

export default Reports;

import React, { useState, useEffect } from 'react';
import { Transaction, TransactionType, AccountType, Category } from '../types';
import { formatCurrency } from '../utils';
import { Search, Plus, Save, X, Archive, ArrowRight, Filter, Eye, EyeOff, Calendar, Tag, CreditCard, User, FileText } from 'lucide-react';

interface TransactionsProps {
  transactions: Transaction[];
  categories: Category[];
  accounts: AccountType[];
  preSelectedAccount: AccountType | null;
  onAddTransaction: (t: Omit<Transaction, 'id'>) => void;
  onDeleteTransaction: (id: string) => void;
}

type TabType = 'INCOME' | 'EXPENSE' | 'TRANSFER';

const Transactions: React.FC<TransactionsProps> = ({ 
  transactions, 
  categories, 
  accounts, 
  preSelectedAccount,
  onAddTransaction,
  onDeleteTransaction
}) => {
  const [activeTab, setActiveTab] = useState<TabType>('INCOME');
  const [filterAccount, setFilterAccount] = useState<string>(preSelectedAccount || 'ALL');
  const [searchTerm, setSearchTerm] = useState('');
  const [showArchived, setShowArchived] = useState(false);
  const [selectedTransaction, setSelectedTransaction] = useState<Transaction | null>(null);

  const [entries, setEntries] = useState<any[]>([{ 
    amount: '', 
    date: new Date().toISOString().split('T')[0],
    category: '',
    accountId: '',
    toAccountId: '',
    recipient: '',
    notes: '',
    receivedFromFinance: false
  }]);

  useEffect(() => {
    if (preSelectedAccount) setFilterAccount(preSelectedAccount);
  }, [preSelectedAccount]);

  const handleAddEntry = () => {
    setEntries([...entries, { 
      amount: '', 
      date: new Date().toISOString().split('T')[0],
      category: '',
      accountId: '',
      toAccountId: '',
      recipient: '',
      notes: '',
      receivedFromFinance: false
    }]);
  };

  const handleRemoveEntry = (index: number) => {
    if (entries.length > 1) {
      setEntries(entries.filter((_, i) => i !== index));
    }
  };

  const updateEntry = (index: number, field: string, value: any) => {
    const newEntries = [...entries];
    newEntries[index] = { ...newEntries[index], [field]: value };
    setEntries(newEntries);
  };

  const validateAndSave = () => {
    for (const entry of entries) {
      if (!entry.amount || Number(entry.amount) <= 0) {
        alert('Please enter a valid amount.');
        return;
      }
      if (!entry.date) {
        alert('Please select a date.');
        return;
      }
      if (activeTab !== 'TRANSFER' && !entry.category) {
        alert('Please select a category.');
        return;
      }
      if (!entry.accountId) {
        alert('Please select an account.');
        return;
      }
      if (activeTab === 'TRANSFER' && !entry.toAccountId) {
         alert('Please select a destination account.');
         return;
      }
    }

    entries.forEach(entry => {
      onAddTransaction({
        date: entry.date,
        amount: Number(entry.amount),
        type: activeTab === 'INCOME' ? TransactionType.INCOME : activeTab === 'EXPENSE' ? TransactionType.EXPENSE : TransactionType.TRANSFER,
        category: activeTab === 'TRANSFER' ? 'Finance Transfer' : entry.category,
        accountId: entry.accountId,
        toAccountId: activeTab === 'TRANSFER' ? entry.toAccountId : undefined,
        recipient: entry.recipient,
        notes: entry.notes,
        isArchived: false,
        meta: {
            receivedFromFinance: entry.receivedFromFinance
        }
      });
    });

    setEntries([{ 
      amount: '', 
      date: new Date().toISOString().split('T')[0],
      category: '',
      accountId: '',
      toAccountId: '',
      recipient: '',
      notes: '',
      receivedFromFinance: false
    }]);
    alert('Transaction(s) saved successfully!');
  };

  const handleArchive = (id: string) => {
      if (window.confirm('Are you sure you want to move this record to the archives?')) {
          onDeleteTransaction(id);
          setSelectedTransaction(null); // Close modal if open
      }
  };

  const filteredList = transactions
    .filter(t => showArchived ? true : !t.isArchived)
    .filter(t => filterAccount === 'ALL' || t.accountId === filterAccount || t.toAccountId === filterAccount)
    .filter(t => 
      t.category.toLowerCase().includes(searchTerm.toLowerCase()) || 
      t.notes?.toLowerCase().includes(searchTerm.toLowerCase()) ||
      t.recipient?.toLowerCase().includes(searchTerm.toLowerCase())
    )
    .sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());

  return (
    <div className="space-y-6">
      <div className="bg-white rounded-2xl shadow-sm border border-gray-200 overflow-hidden">
        {/* Form Tabs */}
        <div className="flex border-b border-gray-100 overflow-x-auto no-scrollbar">
          {(['INCOME', 'EXPENSE', 'TRANSFER'] as TabType[]).map(tab => (
            <button
              key={tab}
              onClick={() => setActiveTab(tab)}
              className={`flex-1 min-w-[100px] py-4 text-sm font-bold tracking-wide transition-colors whitespace-nowrap outline-none focus:ring-inset focus:ring-2 focus:ring-primary/20 ${
                activeTab === tab 
                  ? tab === 'INCOME' ? 'bg-emerald-50 text-emerald-700 border-b-2 border-emerald-500' 
                    : tab === 'EXPENSE' ? 'bg-rose-50 text-rose-700 border-b-2 border-rose-500'
                    : 'bg-blue-50 text-blue-700 border-b-2 border-blue-500'
                  : 'text-gray-500 hover:bg-gray-50'
              }`}
            >
              {tab}
            </button>
          ))}
        </div>

        {/* Form Body */}
        <div className="p-4 sm:p-6">
          <div className="space-y-6">
            {entries.map((entry, index) => (
              <div key={index} className="relative p-5 bg-gray-50/50 rounded-xl border border-gray-200 space-y-4 shadow-sm">
                {entries.length > 1 && (
                    <button onClick={() => handleRemoveEntry(index)} className="absolute top-2 right-2 text-red-400 hover:text-red-600 z-10 p-1 bg-white rounded-full shadow-sm border border-gray-200 hover:shadow-md transition-all">
                        <X size={16} />
                    </button>
                )}

                <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-5">
                  <div>
                    <label className="block text-xs font-bold text-gray-500 mb-1 uppercase tracking-wide">Date</label>
                    <input 
                        type="date" 
                        value={entry.date}
                        onChange={(e) => updateEntry(index, 'date', e.target.value)}
                        className="w-full rounded-lg border-gray-300 shadow-sm focus:ring-2 focus:ring-primary/20 focus:border-primary p-2.5 border text-sm"
                    />
                  </div>

                  <div>
                    <label className="block text-xs font-bold text-gray-500 mb-1 uppercase tracking-wide">Value (GHC)</label>
                    <input 
                        type="number" 
                        placeholder="0.00"
                        value={entry.amount}
                        onChange={(e) => updateEntry(index, 'amount', e.target.value)}
                        className="w-full rounded-lg border-gray-300 shadow-sm focus:ring-2 focus:ring-primary/20 focus:border-primary p-2.5 border text-sm"
                    />
                  </div>

                  {activeTab !== 'TRANSFER' && (
                    <div className="sm:col-span-2">
                        <label className="block text-xs font-bold text-gray-500 mb-1 uppercase tracking-wide">Category</label>
                        <select 
                            value={entry.category}
                            onChange={(e) => updateEntry(index, 'category', e.target.value)}
                            className="w-full rounded-lg border-gray-300 shadow-sm focus:ring-2 focus:ring-primary/20 focus:border-primary p-2.5 border text-sm"
                        >
                            <option value="">Select Category...</option>
                            {categories
                                .filter(c => c.type === 'BOTH' || c.type === activeTab)
                                .map(c => <option key={c.id} value={c.name}>{c.name}</option>)}
                        </select>
                    </div>
                  )}
                </div>

                <div className="grid grid-cols-1 sm:grid-cols-2 gap-5">
                   <div>
                        <label className="block text-xs font-bold text-gray-500 mb-1 uppercase tracking-wide">
                            {activeTab === 'TRANSFER' ? 'From Account' : 'Account'}
                        </label>
                        <select 
                            value={entry.accountId}
                            onChange={(e) => updateEntry(index, 'accountId', e.target.value)}
                            className="w-full rounded-lg border-gray-300 shadow-sm focus:ring-2 focus:ring-primary/20 focus:border-primary p-2.5 border text-sm"
                        >
                            <option value="">Select Account...</option>
                            {accounts.map(a => <option key={a} value={a}>{a}</option>)}
                        </select>

                        {activeTab === 'EXPENSE' && entry.accountId === AccountType.MOMO && (
                            <div className="mt-3 flex items-start bg-rose-50 p-3 rounded-lg border border-rose-100">
                                <input 
                                    type="checkbox" 
                                    id={`finance-check-${index}`}
                                    checked={entry.receivedFromFinance}
                                    onChange={(e) => updateEntry(index, 'receivedFromFinance', e.target.checked)}
                                    className="mt-0.5 h-4 w-4 text-primary focus:ring-primary border-gray-300 rounded"
                                />
                                <label htmlFor={`finance-check-${index}`} className="ml-2 block text-xs text-rose-800 font-medium leading-tight">
                                    Was this digital cash received from Finance? (Mandatory)
                                </label>
                            </div>
                        )}
                   </div>

                   {activeTab === 'TRANSFER' ? (
                       <div>
                            <label className="block text-xs font-bold text-gray-500 mb-1 uppercase tracking-wide">To Account</label>
                            <select 
                                value={entry.toAccountId}
                                onChange={(e) => updateEntry(index, 'toAccountId', e.target.value)}
                                className="w-full rounded-lg border-gray-300 shadow-sm focus:ring-2 focus:ring-primary/20 focus:border-primary p-2.5 border text-sm"
                            >
                                <option value="">Select Account...</option>
                                {accounts.map(a => <option key={a} value={a}>{a}</option>)}
                            </select>
                       </div>
                   ) : (
                       <div>
                           <label className="block text-xs font-bold text-gray-500 mb-1 uppercase tracking-wide">From/To (Optional)</label>
                           <input 
                                type="text"
                                placeholder="Recipient Name"
                                value={entry.recipient}
                                onChange={(e) => updateEntry(index, 'recipient', e.target.value)}
                                className="w-full rounded-lg border-gray-300 shadow-sm focus:ring-2 focus:ring-primary/20 focus:border-primary p-2.5 border text-sm"
                            />
                       </div>
                   )}
                </div>

                <div>
                    <label className="block text-xs font-bold text-gray-500 mb-1 uppercase tracking-wide">Notes (Optional)</label>
                    <textarea 
                        rows={2}
                        value={entry.notes}
                        onChange={(e) => updateEntry(index, 'notes', e.target.value)}
                        className="w-full rounded-lg border-gray-300 shadow-sm focus:ring-2 focus:ring-primary/20 focus:border-primary p-2.5 border text-sm"
                        placeholder="Add details here..."
                    />
                </div>
              </div>
            ))}

            <div className="flex flex-col sm:flex-row justify-between items-center gap-4 pt-2">
                <button 
                    onClick={handleAddEntry}
                    className="w-full sm:w-auto flex items-center justify-center text-sm font-bold text-primary hover:text-teal-800 p-2.5 hover:bg-teal-50 rounded-lg transition-colors"
                >
                    <Plus size={18} className="mr-1" /> Add another entry
                </button>
                <button 
                    onClick={validateAndSave}
                    className={`w-full sm:w-auto flex items-center justify-center px-8 py-3 rounded-xl text-white font-bold shadow-md hover:shadow-lg transition-all active:scale-95 duration-200 ${
                        activeTab === 'INCOME' ? 'bg-emerald-600 hover:bg-emerald-700' 
                        : activeTab === 'EXPENSE' ? 'bg-rose-600 hover:bg-rose-700' 
                        : 'bg-blue-600 hover:bg-blue-700'
                    }`}
                >
                    <Save size={20} className="mr-2" /> Save Transaction
                </button>
            </div>
          </div>
        </div>
      </div>

      {/* Transaction List */}
      <div className="bg-white rounded-2xl shadow-sm border border-gray-200 overflow-hidden">
        <div className="p-5 border-b border-gray-100 flex flex-col md:flex-row justify-between items-start md:items-center gap-4 bg-gray-50/30">
            <h3 className="font-bold text-gray-800 text-lg">Transaction History</h3>
            <div className="flex flex-col sm:flex-row gap-2 w-full md:w-auto">
                <div className="relative flex-1">
                    <Search className="absolute left-3 top-3 text-gray-400" size={16} />
                    <input 
                        type="text" 
                        placeholder="Search records..." 
                        value={searchTerm}
                        onChange={(e) => setSearchTerm(e.target.value)}
                        className="pl-9 pr-4 py-2.5 bg-white border border-gray-200 rounded-xl text-sm focus:outline-none focus:ring-2 focus:ring-primary/20 w-full shadow-sm"
                    />
                </div>

                <div className="flex gap-2">
                    <button
                        onClick={() => setShowArchived(!showArchived)}
                        className={`flex items-center gap-2 px-4 py-2.5 rounded-xl text-sm border transition-colors whitespace-nowrap font-medium shadow-sm ${
                            showArchived 
                            ? 'bg-gray-800 text-white border-gray-800' 
                            : 'bg-white text-gray-600 border-gray-200 hover:bg-gray-50'
                        }`}
                        title={showArchived ? "Hide Archived" : "Show Archived"}
                    >
                        {showArchived ? <EyeOff size={16} /> : <Eye size={16} />}
                        <span className="hidden sm:inline">{showArchived ? 'Hide Archived' : 'Show Archived'}</span>
                    </button>

                    <select 
                        value={filterAccount}
                        onChange={(e) => setFilterAccount(e.target.value)}
                        className="py-2.5 px-3 bg-white border border-gray-200 rounded-xl text-sm focus:outline-none focus:ring-2 focus:ring-primary/20 w-full sm:w-auto cursor-pointer shadow-sm"
                    >
                        <option value="ALL">All Accounts</option>
                        {accounts.map(a => <option key={a} value={a}>{a}</option>)}
                    </select>
                </div>
            </div>
        </div>

        {/* Desktop Table View */}
        <div className="hidden md:block overflow-x-auto w-full">
            <div className="min-w-full">
                <table className="w-full text-left text-sm text-gray-600 table-auto">
                    <thead className="bg-gray-50/50 text-gray-500 font-bold uppercase text-xs border-b border-gray-100">
                        <tr>
                            <th className="px-5 py-4 w-32 tracking-wider">Date</th>
                            <th className="px-5 py-4 w-48 tracking-wider">Category</th>
                            <th className="px-5 py-4 w-48 tracking-wider">Account</th>
                            <th className="px-5 py-4 w-32 text-right tracking-wider">Amount</th>
                            <th className="px-5 py-4 tracking-wider">Notes</th>
                            <th className="px-5 py-4 w-20 text-center tracking-wider">View</th>
                        </tr>
                    </thead>
                    <tbody className="divide-y divide-gray-50">
                        {filteredList.length === 0 ? (
                            <tr><td colSpan={6} className="px-5 py-12 text-center text-gray-400 italic">No transactions found matching your criteria.</td></tr>
                        ) : (
                            filteredList.map(t => (
                                <tr 
                                    key={t.id} 
                                    onClick={() => setSelectedTransaction(t)}
                                    className={`group transition-all cursor-pointer ${
                                        t.isArchived 
                                        ? 'bg-gray-50 opacity-60 hover:opacity-80' 
                                        : 'hover:bg-blue-50/30 hover:scale-[1.002]'
                                    }`}
                                >
                                    <td className="px-5 py-4 whitespace-nowrap">
                                        <span className="font-medium text-gray-700">{t.date}</span>
                                        {t.isArchived && <span className="block text-[10px] text-gray-400 font-bold uppercase tracking-wider mt-0.5">Archived</span>}
                                    </td>
                                    <td className="px-5 py-4">
                                        <span className={`inline-flex items-center px-2.5 py-1 rounded-md text-xs font-bold whitespace-nowrap ${
                                            t.isArchived ? 'bg-gray-200 text-gray-500' :
                                            t.type === TransactionType.INCOME ? 'bg-emerald-100 text-emerald-800' : 
                                            t.type === TransactionType.EXPENSE ? 'bg-rose-100 text-rose-800' : 'bg-blue-100 text-blue-800'
                                        }`}>
                                            {t.category}
                                        </span>
                                    </td>
                                    <td className="px-5 py-4">
                                        <div className="flex flex-col">
                                            <span className="truncate max-w-[150px] font-medium" title={t.accountId}>{t.accountId}</span>
                                            {t.type === TransactionType.TRANSFER && (
                                                <span className="flex items-center text-xs text-gray-400 mt-0.5 truncate max-w-[150px]">
                                                    <ArrowRight size={10} className="mr-1" /> {t.toAccountId}
                                                </span>
                                            )}
                                        </div>
                                    </td>
                                    <td className={`px-5 py-4 text-right font-bold whitespace-nowrap text-base ${
                                        t.isArchived ? 'text-gray-500' :
                                        t.type === TransactionType.INCOME ? 'text-emerald-600' : 'text-rose-600'
                                    }`}>
                                        {t.type === TransactionType.EXPENSE ? '-' : ''}{formatCurrency(t.amount)}
                                    </td>
                                    <td className="px-5 py-4 max-w-xs truncate text-gray-500" title={t.notes}>
                                        {t.notes || '-'}
                                    </td>
                                    <td className="px-5 py-4 text-center">
                                        <ArrowRight size={16} className="text-gray-300 group-hover:text-primary mx-auto transition-colors" />
                                    </td>
                                </tr>
                            ))
                        )}
                    </tbody>
                </table>
            </div>
        </div>

        {/* Mobile Card View */}
        <div className="md:hidden divide-y divide-gray-100 bg-gray-50/50 p-3 space-y-3">
             {filteredList.length === 0 ? (
                <div className="px-4 py-12 text-center text-gray-400 text-sm italic">No transactions found.</div>
             ) : (
                filteredList.map(t => (
                    <div 
                        key={t.id} 
                        onClick={() => setSelectedTransaction(t)}
                        className={`p-4 rounded-xl shadow-sm border border-gray-100 flex flex-col gap-3 active:scale-95 transition-transform ${
                            t.isArchived ? 'bg-gray-100 border-gray-200 opacity-80' : 'bg-white'
                        }`}
                    >
                        <div className="flex justify-between items-start">
                            <div>
                                <div className="flex items-center gap-2 mb-1">
                                    <span className={`text-xs font-bold px-2 py-0.5 rounded-md ${t.isArchived ? 'bg-gray-200 text-gray-500' : 'bg-gray-100 text-gray-500'}`}>{t.date}</span>
                                    {t.isArchived && <span className="text-[10px] font-black bg-gray-600 text-white px-1.5 py-0.5 rounded uppercase tracking-wide">Archived</span>}
                                    <span className={`text-[10px] px-1.5 py-0.5 rounded font-bold border ${
                                        t.isArchived ? 'bg-gray-200 text-gray-500 border-gray-300' :
                                        t.type === TransactionType.INCOME ? 'bg-emerald-50 text-emerald-700 border-emerald-100' :
                                        t.type === TransactionType.EXPENSE ? 'bg-rose-50 text-rose-700 border-rose-100' : 'bg-blue-50 text-blue-700 border-blue-100'
                                    }`}>{t.type.slice(0,3)}</span>
                                </div>
                                <h4 className={`font-bold text-sm ${t.isArchived ? 'text-gray-600' : 'text-gray-800'}`}>{t.category}</h4>
                            </div>
                             <span className={`font-black text-lg ${
                                t.isArchived ? 'text-gray-500' :
                                t.type === TransactionType.INCOME ? 'text-emerald-600' : 'text-rose-600'
                            }`}>
                                {t.type === TransactionType.EXPENSE ? '-' : ''}{formatCurrency(t.amount)}
                            </span>
                        </div>

                        <div className={`text-sm space-y-2 p-3 rounded-lg border ${t.isArchived ? 'bg-gray-100 border-gray-200 text-gray-500' : 'bg-gray-50/50 border-gray-100 text-gray-600'}`}>
                             <div className="flex justify-between items-center">
                                 <span className="text-xs font-bold opacity-70 uppercase tracking-wide">Account</span>
                                 <span className="font-medium text-xs">{t.accountId}</span>
                             </div>
                             {t.type === TransactionType.TRANSFER && (
                                 <div className="flex justify-between items-center">
                                    <span className="text-xs font-bold opacity-70 uppercase tracking-wide">To</span>
                                    <span className="font-medium text-xs flex items-center"><ArrowRight size={10} className="mx-1"/> {t.toAccountId}</span>
                                 </div>
                             )}
                             {t.recipient && (
                                 <div className="flex justify-between items-center">
                                    <span className="text-xs font-bold opacity-70 uppercase tracking-wide">Recipient</span>
                                    <span className="font-medium text-xs">{t.recipient}</span>
                                 </div>
                             )}
                             {t.notes && (
                                 <div className={`pt-2 mt-1 border-t ${t.isArchived ? 'border-gray-300' : 'border-gray-200'}`}>
                                    <p className="text-xs italic opacity-80 leading-relaxed line-clamp-2">{t.notes}</p>
                                 </div>
                             )}
                        </div>
                    </div>
                ))
             )}
        </div>
      </div>

      {/* Transaction Details Modal */}
      {selectedTransaction && (
          <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-gray-900/60 backdrop-blur-sm animate-in fade-in duration-200">
              <div className="bg-white rounded-2xl shadow-2xl w-full max-w-md overflow-hidden animate-in zoom-in-95 duration-200 border border-gray-100">
                  <div className={`p-6 border-b border-gray-100 flex justify-between items-start ${
                      selectedTransaction.isArchived ? 'bg-gray-100' : 
                      selectedTransaction.type === TransactionType.INCOME ? 'bg-emerald-50/50' :
                      selectedTransaction.type === TransactionType.EXPENSE ? 'bg-rose-50/50' : 'bg-blue-50/50'
                  }`}>
                      <div>
                          <p className="text-xs font-bold uppercase tracking-widest opacity-60 mb-1">Transaction Details</p>
                          <h3 className="text-xl font-bold text-gray-900">{selectedTransaction.category}</h3>
                          {selectedTransaction.isArchived && <span className="inline-block mt-1 px-2 py-0.5 bg-gray-600 text-white text-[10px] font-bold rounded uppercase">Archived Record</span>}
                      </div>
                      <button onClick={() => setSelectedTransaction(null)} className="p-2 bg-white/50 hover:bg-white rounded-full transition-colors text-gray-500 hover:text-gray-800">
                          <X size={20} />
                      </button>
                  </div>

                  <div className="p-6 space-y-6">
                      <div className="flex flex-col items-center justify-center py-2">
                          <span className={`text-4xl font-black ${
                             selectedTransaction.isArchived ? 'text-gray-500' : 
                             selectedTransaction.type === TransactionType.INCOME ? 'text-emerald-600' : 'text-rose-600'
                          }`}>
                              {selectedTransaction.type === TransactionType.EXPENSE && '-'}
                              {formatCurrency(selectedTransaction.amount)}
                          </span>
                          <span className="text-sm font-medium text-gray-400 mt-1 uppercase tracking-wide">{selectedTransaction.type}</span>
                      </div>

                      <div className="space-y-4">
                          <div className="flex items-start gap-4">
                              <div className="p-2.5 bg-gray-50 rounded-lg text-gray-400"><Calendar size={18}/></div>
                              <div>
                                  <p className="text-xs font-bold text-gray-400 uppercase tracking-wide">Date</p>
                                  <p className="font-medium text-gray-800">{new Date(selectedTransaction.date).toLocaleDateString('en-GB', { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' })}</p>
                              </div>
                          </div>

                          <div className="flex items-start gap-4">
                              <div className="p-2.5 bg-gray-50 rounded-lg text-gray-400"><CreditCard size={18}/></div>
                              <div className="flex-1">
                                  <p className="text-xs font-bold text-gray-400 uppercase tracking-wide">Account</p>
                                  <p className="font-medium text-gray-800">{selectedTransaction.accountId}</p>
                                  {selectedTransaction.toAccountId && (
                                      <div className="mt-1 flex items-center text-sm text-gray-600">
                                          <ArrowRight size={12} className="mr-1"/> To: <span className="font-medium ml-1">{selectedTransaction.toAccountId}</span>
                                      </div>
                                  )}
                              </div>
                          </div>

                          {selectedTransaction.recipient && (
                            <div className="flex items-start gap-4">
                                <div className="p-2.5 bg-gray-50 rounded-lg text-gray-400"><User size={18}/></div>
                                <div>
                                    <p className="text-xs font-bold text-gray-400 uppercase tracking-wide">Recipient / Source</p>
                                    <p className="font-medium text-gray-800">{selectedTransaction.recipient}</p>
                                </div>
                            </div>
                          )}

                          <div className="flex items-start gap-4">
                              <div className="p-2.5 bg-gray-50 rounded-lg text-gray-400"><FileText size={18}/></div>
                              <div>
                                  <p className="text-xs font-bold text-gray-400 uppercase tracking-wide">Notes</p>
                                  <p className="font-medium text-gray-800 text-sm leading-relaxed">{selectedTransaction.notes || 'No notes provided.'}</p>
                              </div>
                          </div>
                      </div>

                      {/* Meta Data Display */}
                      {selectedTransaction.meta && (selectedTransaction.meta.receivedFromFinance || selectedTransaction.meta.isPlan) && (
                          <div className="mt-4 p-3 bg-gray-50 rounded-lg border border-gray-100 text-xs text-gray-500">
                              {selectedTransaction.meta.receivedFromFinance && <p>• Funds received from Finance Dept.</p>}
                              {selectedTransaction.meta.isPlan && <p>• Generated from Weekly Plan.</p>}
                          </div>
                      )}

                  </div>

                  <div className="p-6 border-t border-gray-100 bg-gray-50/50 flex flex-col gap-3">
                      {!selectedTransaction.isArchived ? (
                          <button 
                              onClick={() => handleArchive(selectedTransaction.id)}
                              className="w-full flex items-center justify-center gap-2 px-4 py-3 bg-white border border-rose-100 text-rose-600 font-bold rounded-xl hover:bg-rose-50 transition-colors shadow-sm"
                          >
                              <Archive size={18} /> Move to Archives
                          </button>
                      ) : (
                          <p className="text-center text-xs text-gray-400 font-medium italic">
                              This record is currently in the archives. Go to Settings to restore it.
                          </p>
                      )}
                      <button 
                        onClick={() => setSelectedTransaction(null)}
                        className="w-full py-3 text-sm font-bold text-gray-500 hover:text-gray-800 transition-colors"
                      >
                          Close Details
                      </button>
                  </div>
              </div>
          </div>
      )}
    </div>
  );
};

