      >
        <div className="p-4 border-b border-gray-100 flex items-center justify-between h-16">
          {!isSidebarCollapsed && (
            <div className="animate-in fade-in duration-300">
              <h1 className="text-lg font-bold text-primary leading-tight">Thesaurus</h1>
              <p className="text-gray-400 text-[10px] font-bold uppercase tracking-widest">Finance Portal</p>
            </div>
          )}
          <button 
            onClick={() => setIsSidebarCollapsed(!isSidebarCollapsed)}
            className="p-2 hover:bg-gray-100 rounded-lg text-gray-400 transition-colors mx-auto"
          >
            {isSidebarCollapsed ? <ChevronRight size={20} /> : <ChevronLeft size={20} />}
          </button>
        </div>

        <nav className="flex-1 p-3 space-y-2 mt-4">
          {navItems.map(item => (
            <button
              key={item.id}
              onClick={() => setActiveView(item.id as any)}
              className={`w-full flex items-center gap-3 px-3 py-3 rounded-xl transition-all group relative ${
                activeView === item.id 
                  ? 'bg-primary text-white shadow-lg shadow-primary/20' 
                  : 'text-gray-500 hover:bg-gray-50 hover:text-primary'
              }`}
            >
              <item.icon size={22} className="min-w-[22px]" />
              {!isSidebarCollapsed && (
                <span className="font-semibold text-sm animate-in fade-in slide-in-from-left-2 duration-200">
                  {item.label}
                </span>
              )}
              {isSidebarCollapsed && (
                <div className="absolute left-full ml-4 px-2 py-1 bg-gray-800 text-white text-xs rounded opacity-0 group-hover:opacity-100 pointer-events-none transition-opacity whitespace-nowrap z-50">
                  {item.label}
                </div>
              )}
            </button>
          ))}
        </nav>

        {!isSidebarCollapsed && (
          <div className="p-6 border-t border-gray-100 animate-in fade-in duration-500">
            <div className="bg-gray-50 p-3 rounded-xl">
              <p className="text-[10px] text-gray-400 text-center font-bold tracking-tighter">THE PRIVY CLOSET v1.0</p>
            </div>
          </div>
