      </aside>

      {/* Mobile Header */}
      <div className="md:hidden fixed top-0 w-full bg-white/80 backdrop-blur-md border-b border-gray-200 z-30 flex justify-between items-center px-4 py-3 h-16 shadow-sm">
         <div>
            <h1 className="text-lg font-bold text-primary leading-none">Thesaurus</h1>
            <p className="text-[10px] text-gray-400 font-bold uppercase tracking-tighter">Finance</p>
