import React, { useState } from 'react';
import { LayoutDashboard, Receipt, Settings as SettingsIcon, PieChart, Menu, X, ChevronLeft, ChevronRight } from 'lucide-react';
import { Transaction, Category, User, AccountType } from './types';
import { INITIAL_TRANSACTIONS, INITIAL_CATEGORIES, INITIAL_USERS } from './utils';

import Overview from './components/Overview';
import Transactions from './components/Transactions';
import Reports from './components/Reports';
import Settings from './components/Settings';

function App() {
  const [transactions, setTransactions] = useState<Transaction[]>(INITIAL_TRANSACTIONS);
  const [categories, setCategories] = useState<Category[]>(INITIAL_CATEGORIES);
  const [users, setUsers] = useState<User[]>(INITIAL_USERS);
  const [activeView, setActiveView] = useState<'OVERVIEW' | 'TRANSACTIONS' | 'REPORTS' | 'SETTINGS'>('OVERVIEW');

  // Sidebar states
  const [isSidebarCollapsed, setIsSidebarCollapsed] = useState(false);
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);

  const [preSelectedAccount, setPreSelectedAccount] = useState<AccountType | null>(null);

  const handleAccountFilter = (account: AccountType | null) => {
    setPreSelectedAccount(account);
    setActiveView('TRANSACTIONS');
  };

  const addTransaction = (t: Omit<Transaction, 'id'>) => {
    const newT = { ...t, id: Math.random().toString(36).substr(2, 9) };
    setTransactions(prev => [newT, ...prev]);
  };

  const deleteTransaction = (id: string) => {
    setTransactions(prev => prev.map(t => t.id === id ? { ...t, isArchived: true } : t));
  };

  const restoreTransaction = (id: string) => {
    setTransactions(prev => prev.map(t => t.id === id ? { ...t, isArchived: false } : t));
  };

  const addCategory = (c: Category) => {
    setCategories(prev => [...prev, c]);
  };

  const deleteCategory = (id: string) => {
    setCategories(prev => prev.filter(c => c.id !== id));
  };

  const navItems = [
    { id: 'OVERVIEW', label: 'Overview', icon: LayoutDashboard },
    { id: 'TRANSACTIONS', label: 'Transactions', icon: Receipt },
    { id: 'REPORTS', label: 'Generate Reports', icon: PieChart },
    { id: 'SETTINGS', label: 'Settings', icon: SettingsIcon },
  ];

  return (
    <div className="flex min-h-screen bg-gray-50 font-sans text-slate-900">

      {/* Sidebar (Desktop & Tablet) */}
      <aside 
        className={`hidden md:flex flex-col bg-white border-r border-gray-200 fixed h-full z-20 transition-all duration-300 ease-in-out shadow-sm ${
          isSidebarCollapsed ? 'w-20' : 'w-64'
        }`}
      >
        <div className="p-4 border-b border-gray-100 flex items-center justify-between h-16">
          {!isSidebarCollapsed && (
            <div className="animate-in fade-in slide-in-from-left-2 duration-300">
              <h1 className="text-lg font-black text-primary leading-tight tracking-tighter uppercase">Thesaurus</h1>
            </div>
          )}
          <button 
            onClick={() => setIsSidebarCollapsed(!isSidebarCollapsed)}
            className="p-2 hover:bg-gray-100 rounded-xl text-gray-400 transition-all mx-auto active:scale-90"
          >
            {isSidebarCollapsed ? <ChevronRight size={20} /> : <ChevronLeft size={20} />}
          </button>
        </div>

        <nav className="flex-1 p-3 space-y-2 mt-4">
          {navItems.map(item => (
            <button
              key={item.id}
              onClick={() => setActiveView(item.id as any)}
              className={`w-full flex items-center gap-3 px-3 py-3 rounded-2xl transition-all group relative ${
                activeView === item.id 
                  ? 'bg-primary text-white shadow-lg shadow-primary/20' 
                  : 'text-gray-400 hover:bg-gray-50 hover:text-primary'
              }`}
            >
              <item.icon size={22} className="min-w-[22px]" />
              {!isSidebarCollapsed && (
                <span className="font-bold text-sm tracking-tight animate-in fade-in slide-in-from-left-2 duration-200">
                  {item.label}
                </span>
              )}
              {isSidebarCollapsed && (
                <div className="absolute left-full ml-4 px-3 py-2 bg-gray-900 text-white text-[10px] font-black uppercase tracking-widest rounded-lg opacity-0 group-hover:opacity-100 pointer-events-none transition-all whitespace-nowrap z-50 translate-x-[-10px] group-hover:translate-x-0">
                  {item.label}
                </div>
              )}
            </button>
          ))}
        </nav>

        {!isSidebarCollapsed && (
          <div className="p-6 border-t border-gray-100 animate-in fade-in duration-500">
            <div className="bg-gray-50 p-4 rounded-2xl text-center">
              <p className="text-[10px] text-gray-400 font-black uppercase tracking-[0.2em] leading-none">The Privy Closet</p>
              <p className="text-[8px] text-gray-300 mt-1 font-bold">V1.2.0 • 2025</p>
            </div>
          </div>
        )}
      </aside>

      {/* Mobile Header */}
      <div className="md:hidden fixed top-0 w-full bg-white/80 backdrop-blur-md border-b border-gray-200 z-30 flex justify-between items-center px-6 py-3 h-16 shadow-sm">
         <div className="flex flex-col">
            <h1 className="text-xl font-black text-primary leading-none tracking-tighter uppercase">Thesaurus</h1>
            <span className="text-[8px] font-black text-gray-400 uppercase tracking-widest mt-0.5">Finance Management</span>
         </div>
         <button 
            onClick={() => setIsMobileMenuOpen(!isMobileMenuOpen)} 
            className="text-gray-900 p-2.5 rounded-2xl bg-gray-100/50 hover:bg-gray-100 active:scale-90 transition-all border border-gray-200/50"
         >
            {isMobileMenuOpen ? <X size={20} /> : <Menu size={20} />}
         </button>
      </div>

      {/* Mobile Menu Overlay */}
      {isMobileMenuOpen && (
        <div className="md:hidden fixed inset-0 z-40 bg-gray-950/60 backdrop-blur-sm animate-in fade-in duration-300" onClick={() => setIsMobileMenuOpen(false)}>
           <div 
             className="absolute top-16 left-6 right-6 bg-white border border-gray-100 p-4 space-y-2 shadow-2xl rounded-[2rem] animate-in slide-in-from-top-4 duration-400"
             onClick={e => e.stopPropagation()} 
           >
             <div className="p-4 mb-2 text-center border-b border-gray-50">
               <p className="text-[10px] font-black text-gray-400 uppercase tracking-[0.3em]">Navigation Menu</p>
             </div>
             {navItems.map(item => (
              <button
                key={item.id}
                onClick={() => {
                    setActiveView(item.id as any);
                    setIsMobileMenuOpen(false);
                }}
                className={`w-full flex items-center gap-4 px-5 py-5 rounded-[1.5rem] transition-all active:scale-95 ${
                  activeView === item.id 
                    ? 'bg-primary text-white shadow-xl shadow-primary/30' 
                    : 'text-gray-500 hover:bg-gray-50'
                }`}
              >
                <item.icon size={20} />
                <span className="font-black uppercase tracking-widest text-[11px]">{item.label}</span>
              </button>
            ))}
           </div>
        </div>
      )}

      {/* Main Content Area */}
      <main 
        className={`flex-1 transition-all duration-300 ease-in-out ${
          isSidebarCollapsed ? 'md:ml-20' : 'md:ml-64'
        } p-4 md:p-10 pt-20 md:pt-10`}
      >
        <div className="max-w-7xl mx-auto animate-in fade-in slide-in-from-bottom-2 duration-500">
          {activeView === 'OVERVIEW' && (
            <Overview 
                transactions={transactions} 
                onFilterAccount={handleAccountFilter} 
            />
          )}

          {activeView === 'TRANSACTIONS' && (
            <Transactions 
                transactions={transactions}
                categories={categories}
                accounts={[AccountType.MOMO, AccountType.CASH, AccountType.OTHER]}
                preSelectedAccount={preSelectedAccount}
                onAddTransaction={addTransaction}
                onDeleteTransaction={deleteTransaction}
            />
          )}

          {activeView === 'REPORTS' && (
             <Reports 
                transactions={transactions}
                users={users}
                onAddTransaction={addTransaction}
                financeRep={users.find(u => u.role === 'FINANCE_REP')}
             />
          )}

          {activeView === 'SETTINGS' && (
             <Settings 
                categories={categories}
                users={users}
                archivedTransactions={transactions.filter(t => t.isArchived)}
                onAddCategory={addCategory}
                onDeleteCategory={deleteCategory}
                onRestoreTransaction={restoreTransaction}
             />
          )}
        </div>
      </main>
    </div>
  );
}

export default App;

import React, { useState, useMemo } from 'react';
import { Transaction, TransactionType, User, AccountType } from '../types';
import { formatCurrency, getGreeting } from '../utils';
import { jsPDF } from 'jspdf';
import { FileText, Calendar, TrendingUp, TrendingDown, Plus, Save, Trash2, Award, Download, ArrowRight, PieChart } from 'lucide-react';
import { 
  BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, Legend, ResponsiveContainer, 
  AreaChart, Area
} from 'recharts';

interface ReportsProps {
  transactions: Transaction[];
  users: User[];
  onAddTransaction: (t: Omit<Transaction, 'id'>) => void;
  financeRep: User | undefined;
}

type ReportType = 'WEEKLY' | 'MONTHLY' | 'QUARTERLY' | 'YEARLY';

const Reports: React.FC<ReportsProps> = ({ transactions, users, onAddTransaction, financeRep }) => {
  const [activeTab, setActiveTab] = useState<ReportType>('WEEKLY');
  const [selectedYear, setSelectedYear] = useState(new Date().getFullYear());
  const [selectedMonth, setSelectedMonth] = useState(new Date().getMonth());
  const [selectedQuarter, setSelectedQuarter] = useState(Math.floor(new Date().getMonth() / 3) + 1);
  const [selectedWeekDate, setSelectedWeekDate] = useState(new Date().toISOString().split('T')[0]);

  // --- Weekly Input States ---
  const [offeringsInput, setOfferingsInput] = useState<{type: 'CASH' | 'MOMO', amount: string}[]>([
    { type: 'CASH', amount: '' }
  ]);
  const [planInput, setPlanInput] = useState<{item: string, cost: string}[]>([
    { item: '', cost: '' }
  ]);

  // --- Helpers ---
  const getMonthName = (monthIndex: number) => {
    return new Date(2025, monthIndex, 1).toLocaleString('default', { month: 'long' });
  };

  const getWeekRange = (dateStr: string) => {
    const date = new Date(dateStr);
    const day = date.getDay();
    const diff = date.getDate() - day + (day === 0 ? -6 : 1);
    const monday = new Date(date.setDate(diff));
    const sunday = new Date(date.setDate(monday.getDate() + 6));
    monday.setHours(0,0,0,0);
    sunday.setHours(23,59,59,999);
    return { start: monday, end: sunday };
  };

  // --- Data Calculations ---
  const weeklyStats = useMemo(() => {
    const { start, end } = getWeekRange(selectedWeekDate);
    const weekTrans = transactions.filter(t => {
      const d = new Date(t.date);
      return !t.isArchived && d >= start && d <= end;
    });

    const offerings = weekTrans.filter(t => t.category === 'Offerings & Tithes' && t.type === TransactionType.INCOME);
    const snacks = weekTrans.filter(t => t.category === 'Snacks & Meals' && t.type === TransactionType.EXPENSE);

    return {
        totalIncome: weekTrans.filter(t => t.type === TransactionType.INCOME).reduce((acc, t) => acc + t.amount, 0),
        totalExpense: weekTrans.filter(t => t.type === TransactionType.EXPENSE).reduce((acc, t) => acc + t.amount, 0),
        offerings: {
          cash: offerings.filter(t => t.accountId === AccountType.CASH).reduce((acc, t) => acc + t.amount, 0),
          momo: offerings.filter(t => t.accountId === AccountType.MOMO).reduce((acc, t) => acc + t.amount, 0)
        },
        snacks: {
          cash: snacks.filter(t => t.accountId === AccountType.CASH).reduce((acc, t) => acc + t.amount, 0),
          momo: snacks.filter(t => t.accountId === AccountType.MOMO).reduce((acc, t) => acc + t.amount, 0)
        },
        range: `${start.toLocaleDateString()} - ${end.toLocaleDateString()}`
    };
  }, [transactions, selectedWeekDate]);

  const monthlyStats = useMemo(() => {
    const monthTrans = transactions.filter(t => {
      const d = new Date(t.date);
      return !t.isArchived && d.getFullYear() === selectedYear && d.getMonth() === selectedMonth;
    });
    const income = monthTrans.filter(t => t.type === TransactionType.INCOME).reduce((acc, t) => acc + t.amount, 0);
    const expense = monthTrans.filter(t => t.type === TransactionType.EXPENSE).reduce((acc, t) => acc + t.amount, 0);
    return { income, expense, balance: income - expense };
  }, [transactions, selectedYear, selectedMonth]);

  // --- Handlers ---
  const handleAddOfferingInput = () => setOfferingsInput([...offeringsInput, { type: 'CASH', amount: '' }]);
  const handleRemoveOfferingInput = (idx: number) => setOfferingsInput(offeringsInput.filter((_, i) => i !== idx));
  const handleAddPlanInput = () => setPlanInput([...planInput, { item: '', cost: '' }]);
  const handleRemovePlanInput = (idx: number) => setPlanInput(planInput.filter((_, i) => i !== idx));

  const saveWeeklyData = () => {
    let savedCount = 0;
    const today = new Date().toISOString().split('T')[0];

    offeringsInput.forEach(entry => {
      if (entry.amount && Number(entry.amount) > 0) {
        onAddTransaction({
          date: today,
          type: TransactionType.INCOME,
          category: 'Offerings & Tithes',
          amount: Number(entry.amount),
          accountId: entry.type === 'CASH' ? AccountType.CASH : AccountType.MOMO,
          isArchived: false
        });
        savedCount++;
      }
    });

    const validPlanItems = planInput.filter(p => p.item && p.cost && Number(p.cost) > 0);
    if (validPlanItems.length > 0) {
      const totalCost = validPlanItems.reduce((acc, p) => acc + Number(p.cost), 0);
      onAddTransaction({
        date: today,
        type: TransactionType.EXPENSE,
        category: 'Snacks & Meals',
        amount: totalCost,
        accountId: AccountType.CASH,
        notes: `Planned: ${validPlanItems.map(p => p.item).join(', ')}`,
        isArchived: false,
        meta: { isPlan: true }
      });
      savedCount++;
    }

    if (savedCount > 0) {
      alert(`Saved ${savedCount} entries.`);
      setOfferingsInput([{ type: 'CASH', amount: '' }]);
      setPlanInput([{ item: '', cost: '' }]);
    }
  };

  const generatePDF = () => {
    const doc = new jsPDF();
    doc.setFontSize(18);
    doc.text(`Thesaurus ${activeTab} Finance Report`, 15, 20);
    doc.setFontSize(10);
    doc.text(`Generated on: ${new Date().toLocaleString()}`, 15, 30);
    doc.text(`Selected Period: ${activeTab === 'WEEKLY' ? weeklyStats.range : activeTab === 'MONTHLY' ? getMonthName(selectedMonth) + ' ' + selectedYear : selectedYear}`, 15, 35);

    if (activeTab === 'WEEKLY') {
      doc.text(`Total Income: ${formatCurrency(weeklyStats.totalIncome)}`, 15, 50);
      doc.text(`Total Expense: ${formatCurrency(weeklyStats.totalExpense)}`, 15, 60);
    } else if (activeTab === 'MONTHLY') {
      doc.text(`Income: ${formatCurrency(monthlyStats.income)}`, 15, 50);
      doc.text(`Expense: ${formatCurrency(monthlyStats.expense)}`, 15, 60);
      doc.text(`Net: ${formatCurrency(monthlyStats.balance)}`, 15, 70);
    }

    doc.save(`Thesaurus_${activeTab}_Report.pdf`);
  };

  return (
    <div className="space-y-6">
      <div className="bg-white rounded-[2rem] shadow-xl shadow-gray-200/50 border border-gray-100 overflow-hidden">
        {/* Modern Tab Navigation */}
        <div className="flex border-b border-gray-100 overflow-x-auto no-scrollbar bg-gray-50/50">
          {(['WEEKLY', 'MONTHLY', 'QUARTERLY', 'YEARLY'] as ReportType[]).map(tab => (
            <button
              key={tab}
              onClick={() => setActiveTab(tab)}
              className={`flex-1 min-w-[120px] py-6 text-[10px] font-black uppercase tracking-[0.2em] transition-all relative ${
                activeTab === tab ? 'text-primary' : 'text-gray-400 hover:text-gray-600'
              }`}
            >
              {tab}
              {activeTab === tab && (
                <div className="absolute bottom-0 left-0 right-0 h-1 bg-primary rounded-t-full mx-8 animate-in slide-in-from-bottom-2 duration-300" />
              )}
            </button>
          ))}
        </div>

        <div className="p-6 md:p-10 min-h-[500px]">
          {/* Header Controls */}
          <div className="flex flex-col lg:flex-row justify-between items-start lg:items-center mb-10 gap-6">
            <div className="flex flex-col">
              <h3 className="text-3xl font-black text-gray-900 tracking-tighter capitalize">{activeTab.toLowerCase()} Overview</h3>
              {activeTab === 'WEEKLY' && (
                <span className="text-xs font-bold text-gray-400 mt-2 flex items-center gap-2 bg-gray-100 px-3 py-1.5 rounded-full w-fit">
                  <Calendar size={14} className="text-primary"/> {weeklyStats.range}
                </span>
              )}
            </div>

            <div className="flex flex-col sm:flex-row gap-3 w-full lg:w-auto">
              {activeTab === 'WEEKLY' && (
                <input 
                  type="date" 
                  className="p-3 border border-gray-200 rounded-2xl text-sm font-bold bg-white focus:ring-4 focus:ring-primary/10 outline-none"
                  value={selectedWeekDate}
                  onChange={(e) => setSelectedWeekDate(e.target.value)}
                />
              )}
              <button 
                onClick={generatePDF}
                className="flex items-center justify-center px-6 py-4 bg-gray-900 text-white text-xs font-black uppercase tracking-widest rounded-2xl hover:bg-gray-800 transition-all shadow-xl"
              >
                <Download size={18} className="mr-2" /> Export PDF
              </button>
            </div>
          </div>

          {activeTab === 'WEEKLY' && (
            <div className="space-y-10 animate-in fade-in slide-in-from-bottom-4 duration-700">
              {/* Stats Grid */}
              <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                <div className="bg-emerald-50/50 p-8 rounded-3xl border border-emerald-100 relative overflow-hidden group">
                  <TrendingUp className="absolute -bottom-4 -right-4 text-emerald-200 opacity-20" size={120} />
                  <h4 className="text-[10px] font-black text-emerald-700 uppercase tracking-widest mb-6">Sunday Offerings</h4>
                  <div className="space-y-3 relative z-10">
                    <div className="flex justify-between border-b border-emerald-100 pb-2">
                      <span className="text-xs font-bold text-emerald-600">CASH</span>
                      <span className="font-mono font-bold text-emerald-900">{formatCurrency(weeklyStats.offerings.cash)}</span>
                    </div>
                    <div className="flex justify-between border-b border-emerald-100 pb-2">
                      <span className="text-xs font-bold text-emerald-600">MOMO</span>
                      <span className="font-mono font-bold text-emerald-900">{formatCurrency(weeklyStats.offerings.momo)}</span>
                    </div>
                    <div className="pt-2 flex justify-between items-center">
                      <span className="text-sm font-black text-emerald-900">TOTAL</span>
                      <span className="text-2xl font-black text-emerald-950">{formatCurrency(weeklyStats.totalIncome)}</span>
                    </div>
                  </div>
                </div>

                <div className="bg-rose-50/50 p-8 rounded-3xl border border-rose-100 relative overflow-hidden group">
                  <TrendingDown className="absolute -bottom-4 -right-4 text-rose-200 opacity-20" size={120} />
                  <h4 className="text-[10px] font-black text-rose-700 uppercase tracking-widest mb-6">Snack Expenditure</h4>
                  <div className="space-y-3 relative z-10">
                    <div className="flex justify-between border-b border-rose-100 pb-2">
                      <span className="text-xs font-bold text-rose-600">CASH</span>
                      <span className="font-mono font-bold text-rose-900">{formatCurrency(weeklyStats.snacks.cash)}</span>
                    </div>
                    <div className="flex justify-between border-b border-rose-100 pb-2">
                      <span className="text-xs font-bold text-rose-600">MOMO</span>
                      <span className="font-mono font-bold text-rose-900">{formatCurrency(weeklyStats.snacks.momo)}</span>
                    </div>
                    <div className="pt-2 flex justify-between items-center">
                      <span className="text-sm font-black text-rose-900">SPENT</span>
                      <span className="text-2xl font-black text-rose-950">{formatCurrency(weeklyStats.totalExpense)}</span>
                    </div>
                  </div>
                </div>

                <div className="bg-gray-900 p-8 rounded-3xl flex flex-col justify-between md:col-span-2 lg:col-span-1 shadow-2xl">
                  <h4 className="text-[10px] font-black text-gray-400 uppercase tracking-widest">Net Position</h4>
                  <p className={`text-4xl font-black tracking-tighter my-4 ${weeklyStats.totalIncome >= weeklyStats.totalExpense ? 'text-emerald-400' : 'text-rose-400'}`}>
                    {formatCurrency(weeklyStats.totalIncome - weeklyStats.totalExpense)}
                  </p>
                  <div className="bg-white/10 p-3 rounded-2xl text-[10px] text-gray-300 font-bold text-center uppercase tracking-widest">Weekly Audited Balance</div>
                </div>
              </div>

              {/* Weekly Input Section */}
              <div className="grid grid-cols-1 xl:grid-cols-2 gap-8">
                {/* Income Inputs */}
                <div className="bg-white border-2 border-emerald-50 rounded-[2.5rem] shadow-xl shadow-emerald-900/5 p-8">
                  <div className="flex items-center gap-4 mb-8">
                    <div className="p-3 bg-emerald-50 rounded-2xl text-emerald-600"><Plus size={24}/></div>
                    <h3 className="font-black text-emerald-900 uppercase tracking-widest text-sm">Sunday Collections</h3>
                  </div>
                  <div className="space-y-4">
                    {offeringsInput.map((entry, idx) => (
                      <div key={idx} className="flex flex-col sm:flex-row gap-3">
                        <select 
                          className="p-4 border border-gray-100 rounded-2xl bg-gray-50 text-xs font-black uppercase tracking-widest outline-none focus:ring-4 focus:ring-emerald-500/10 w-full sm:w-1/3"
                          value={entry.type}
                          onChange={(e) => {
                            const n = [...offeringsInput];
                            n[idx].type = e.target.value as any;
                            setOfferingsInput(n);
                          }}
                        >
                          <option value="CASH">CASH</option>
                          <option value="MOMO">MOMO</option>
                        </select>
                        <div className="flex-1 flex gap-2">
                          <input 
                            type="number" 
                            placeholder="Amount (GHC)"
                            className="p-4 border border-gray-100 rounded-2xl text-sm font-bold w-full outline-none focus:ring-4 focus:ring-emerald-500/10"
                            value={entry.amount}
                            onChange={(e) => {
                              const n = [...offeringsInput];
                              n[idx].amount = e.target.value;
                              setOfferingsInput(n);
                            }}
                          />
                          {offeringsInput.length > 1 && (
                            <button onClick={() => handleRemoveOfferingInput(idx)} className="p-4 bg-rose-50 text-rose-500 rounded-2xl hover:bg-rose-100 transition-all">
                              <Trash2 size={20} />
                            </button>
                          )}
                        </div>
                      </div>
                    ))}
                    <button onClick={handleAddOfferingInput} className="text-[10px] font-black text-emerald-600 uppercase tracking-widest flex items-center gap-2 hover:underline">
                      <Plus size={16}/> Add another source
                    </button>
                  </div>
                </div>

                {/* Planning Inputs */}
                <div className="bg-white border-2 border-primary/5 rounded-[2.5rem] shadow-xl shadow-primary/5 p-8">
                  <div className="flex items-center gap-4 mb-8">
                    <div className="p-3 bg-primary/5 rounded-2xl text-primary"><PieChart size={24}/></div>
                    <h3 className="font-black text-primary uppercase tracking-widest text-sm">Plan Next Week</h3>
                  </div>
                  <div className="space-y-4">
                    {planInput.map((entry, idx) => (
                      <div key={idx} className="flex flex-col sm:flex-row gap-3">
                        <input 
                          type="text" 
                          placeholder="Item Description"
                          className="p-4 border border-gray-100 rounded-2xl text-sm font-bold flex-1 outline-none focus:ring-4 focus:ring-primary/10"
                          value={entry.item}
                          onChange={(e) => {
                            const n = [...planInput];
                            n[idx].item = e.target.value;
                            setPlanInput(n);
                          }}
                        />
                        <div className="flex gap-2 w-full sm:w-auto">
                          <input 
                            type="number" 
                            placeholder="Cost"
                            className="p-4 border border-gray-100 rounded-2xl text-sm font-bold w-full sm:w-28 outline-none focus:ring-4 focus:ring-primary/10"
                            value={entry.cost}
                            onChange={(e) => {
                              const n = [...planInput];
                              n[idx].cost = e.target.value;
                              setPlanInput(n);
                            }}
                          />
                          {planInput.length > 1 && (
                            <button onClick={() => handleRemovePlanInput(idx)} className="p-4 bg-rose-50 text-rose-500 rounded-2xl hover:bg-rose-100 transition-all">
                              <Trash2 size={20} />
                            </button>
                          )}
                        </div>
                      </div>
                    ))}
                    <button onClick={handleAddPlanInput} className="text-[10px] font-black text-primary uppercase tracking-widest flex items-center gap-2 hover:underline">
                      <Plus size={16}/> Add planned item
                    </button>
                  </div>
                </div>
              </div>

              <div className="flex justify-center xl:justify-end">
                <button 
                  onClick={saveWeeklyData}
                  className="w-full sm:w-auto px-12 py-5 bg-primary text-white text-xs font-black uppercase tracking-[0.2em] rounded-[2rem] shadow-2xl shadow-primary/40 hover:bg-teal-800 hover:scale-105 active:scale-95 transition-all"
                >
                  <Save size={20} className="inline mr-3"/> Commit Weekly Report
                </button>
              </div>
            </div>
          )}

          {activeTab !== 'WEEKLY' && (
            <div className="flex flex-col items-center justify-center py-20 animate-in zoom-in duration-500">
              <div className="p-10 bg-gray-50 rounded-[3rem] mb-6">
                <PieChart size={80} className="text-gray-200" />
              </div>
              <p className="text-xl font-black text-gray-900 tracking-tighter uppercase italic">Compiling {activeTab} Intelligence</p>
              <p className="text-xs font-bold text-gray-400 mt-2 uppercase tracking-widest">Full breakdown available in exported PDF</p>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default Reports;

import React, { useState, useEffect } from 'react';
import { Transaction, TransactionType, AccountType, Category } from '../types';
import { formatCurrency } from '../utils';
import { Search, Plus, Save, X, Archive, ArrowRight, Calendar, CreditCard, User, FileText, ChevronRight } from 'lucide-react';

interface TransactionsProps {
  transactions: Transaction[];
  categories: Category[];
  accounts: AccountType[];
  preSelectedAccount: AccountType | null;
  onAddTransaction: (t: Omit<Transaction, 'id'>) => void;
  onDeleteTransaction: (id: string) => void;
}

type TabType = 'INCOME' | 'EXPENSE' | 'TRANSFER';

const Transactions: React.FC<TransactionsProps> = ({ 
  transactions, 
  categories, 
  accounts, 
  preSelectedAccount,
  onAddTransaction,
  onDeleteTransaction
}) => {
  const [activeTab, setActiveTab] = useState<TabType>('INCOME');
  const [filterAccount, setFilterAccount] = useState<string>(preSelectedAccount || 'ALL');
  const [searchTerm, setSearchTerm] = useState('');
  const [showArchived, setShowArchived] = useState(false);
  const [selectedTransaction, setSelectedTransaction] = useState<Transaction | null>(null);

  const [entries, setEntries] = useState<any[]>([{ 
    amount: '', 
    date: new Date().toISOString().split('T')[0],
    category: '',
    accountId: '',
    toAccountId: '',
    recipient: '',
    notes: '',
    receivedFromFinance: false
  }]);

  useEffect(() => {
    if (preSelectedAccount) setFilterAccount(preSelectedAccount);
  }, [preSelectedAccount]);

  const handleAddEntry = () => {
    setEntries([...entries, { 
      amount: '', 
      date: new Date().toISOString().split('T')[0],
      category: '',
      accountId: '',
      toAccountId: '',
      recipient: '',
      notes: '',
      receivedFromFinance: false
    }]);
  };

  const handleRemoveEntry = (index: number) => {
    if (entries.length > 1) {
      setEntries(entries.filter((_, i) => i !== index));
    }
  };

  const updateEntry = (index: number, field: string, value: any) => {
    const newEntries = [...entries];
    newEntries[index] = { ...newEntries[index], [field]: value };
    setEntries(newEntries);
  };

  const validateAndSave = () => {
    for (const entry of entries) {
      if (!entry.amount || Number(entry.amount) <= 0) {
        alert('Please enter a valid amount.');
        return;
      }
      if (!entry.date) {
        alert('Please select a date.');
        return;
      }
      if (activeTab !== 'TRANSFER' && !entry.category) {
        alert('Please select a category.');
        return;
      }
      if (!entry.accountId) {
        alert('Please select an account.');
        return;
      }
    }

    entries.forEach(entry => {
      onAddTransaction({
        date: entry.date,
        amount: Number(entry.amount),
        type: activeTab === 'INCOME' ? TransactionType.INCOME : activeTab === 'EXPENSE' ? TransactionType.EXPENSE : TransactionType.TRANSFER,
        category: activeTab === 'TRANSFER' ? 'Finance Transfer' : entry.category,
        accountId: entry.accountId,
        toAccountId: activeTab === 'TRANSFER' ? entry.toAccountId : undefined,
        recipient: entry.recipient,
        notes: entry.notes,
        isArchived: false,
        meta: {
            receivedFromFinance: entry.receivedFromFinance
        }
      });
    });

    setEntries([{ 
      amount: '', 
      date: new Date().toISOString().split('T')[0],
      category: '',
      accountId: '',
      toAccountId: '',
      recipient: '',
      notes: '',
      receivedFromFinance: false
    }]);
    alert('Transaction(s) saved successfully!');
  };

  const handleArchive = (id: string) => {
      if (window.confirm('Archive this record? It can be restored in Settings.')) {
          onDeleteTransaction(id);
          setSelectedTransaction(null);
      }
  };

  const filteredList = transactions
    .filter(t => showArchived ? true : !t.isArchived)
    .filter(t => filterAccount === 'ALL' || t.accountId === filterAccount || t.toAccountId === filterAccount)
    .filter(t => 
      t.category.toLowerCase().includes(searchTerm.toLowerCase()) || 
      t.notes?.toLowerCase().includes(searchTerm.toLowerCase()) ||
      t.recipient?.toLowerCase().includes(searchTerm.toLowerCase())
    )
    .sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());

  return (
    <div className="space-y-6">
      {/* Entry Form Card */}
      <div className="bg-white rounded-[2rem] shadow-xl shadow-gray-200/50 border border-gray-100 overflow-hidden">
        <div className="flex border-b border-gray-100 overflow-x-auto no-scrollbar">
          {(['INCOME', 'EXPENSE', 'TRANSFER'] as TabType[]).map(tab => (
            <button
              key={tab}
              onClick={() => setActiveTab(tab)}
              className={`flex-1 min-w-[100px] py-6 text-[10px] font-black tracking-widest transition-all outline-none relative uppercase ${
                activeTab === tab 
                  ? tab === 'INCOME' ? 'text-emerald-600' : tab === 'EXPENSE' ? 'text-rose-600' : 'text-blue-600'
                  : 'text-gray-400 hover:text-gray-600'
              }`}
            >
              {tab}
              {activeTab === tab && (
                <div className={`absolute bottom-0 left-0 right-0 h-1 mx-8 rounded-t-full animate-in slide-in-from-bottom-2 duration-300 ${
                  tab === 'INCOME' ? 'bg-emerald-500' : tab === 'EXPENSE' ? 'bg-rose-500' : 'bg-blue-500'
                }`} />
              )}
            </button>
          ))}
        </div>

        <div className="p-6 md:p-10">
          <div className="space-y-6">
            {entries.map((entry, index) => (
              <div key={index} className="relative p-6 md:p-8 bg-gray-50/50 rounded-3xl border border-gray-200 space-y-6 shadow-inner group transition-all hover:bg-white hover:shadow-lg">
                {entries.length > 1 && (
                    <button onClick={() => handleRemoveEntry(index)} className="absolute top-4 right-4 text-gray-300 hover:text-rose-500 z-10 p-2 bg-white rounded-2xl shadow-sm border border-gray-100 hover:scale-110 transition-all">
                        <X size={18} />
                    </button>
                )}

                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
                  <div>
                    <label className="block text-[10px] font-black text-gray-400 mb-2 uppercase tracking-widest">Entry Date</label>
                    <input 
                        type="date" 
                        value={entry.date}
                        onChange={(e) => updateEntry(index, 'date', e.target.value)}
                        className="w-full rounded-2xl border-gray-100 shadow-sm focus:ring-4 focus:ring-primary/10 focus:border-primary p-3.5 border text-sm font-bold outline-none"
                    />
                  </div>
                  <div>
                    <label className="block text-[10px] font-black text-gray-400 mb-2 uppercase tracking-widest">GHC Amount</label>
                    <input 
                        type="number" 
                        placeholder="0.00"
                        value={entry.amount}
                        onChange={(e) => updateEntry(index, 'amount', e.target.value)}
                        className="w-full rounded-2xl border-gray-100 shadow-sm focus:ring-4 focus:ring-primary/10 focus:border-primary p-3.5 border text-sm font-bold outline-none"
                    />
                  </div>
                  {activeTab !== 'TRANSFER' && (
                    <div className="md:col-span-2">
                        <label className="block text-[10px] font-black text-gray-400 mb-2 uppercase tracking-widest">Classification</label>
                        <select 
                            value={entry.category}
                            onChange={(e) => updateEntry(index, 'category', e.target.value)}
                            className="w-full rounded-2xl border-gray-100 shadow-sm focus:ring-4 focus:ring-primary/10 focus:border-primary p-3.5 border text-sm font-bold outline-none bg-white"
                        >
                            <option value="">Select Category...</option>
                            {categories
                                .filter(c => c.type === 'BOTH' || c.type === activeTab)
                                .map(c => <option key={c.id} value={c.name}>{c.name}</option>)}
                        </select>
                    </div>
                  )}
                </div>

                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                   <div>
                        <label className="block text-[10px] font-black text-gray-400 mb-2 uppercase tracking-widest">
                            {activeTab === 'TRANSFER' ? 'Source Account' : 'Account Type'}
                        </label>
                        <select 
                            value={entry.accountId}
                            onChange={(e) => updateEntry(index, 'accountId', e.target.value)}
                            className="w-full rounded-2xl border-gray-100 shadow-sm focus:ring-4 focus:ring-primary/10 focus:border-primary p-3.5 border text-sm font-bold outline-none bg-white"
                        >
                            <option value="">Select Account...</option>
                            {accounts.map(a => <option key={a} value={a}>{a}</option>)}
                        </select>
                   </div>
                   {activeTab === 'TRANSFER' ? (
                       <div>
                            <label className="block text-[10px] font-black text-gray-400 mb-2 uppercase tracking-widest">Destination</label>
                            <select 
                                value={entry.toAccountId}
                                onChange={(e) => updateEntry(index, 'toAccountId', e.target.value)}
                                className="w-full rounded-2xl border-gray-100 shadow-sm focus:ring-4 focus:ring-primary/10 focus:border-primary p-3.5 border text-sm font-bold outline-none bg-white"
                            >
                                <option value="">To Account...</option>
                                {accounts.map(a => <option key={a} value={a}>{a}</option>)}
                            </select>
                       </div>
                   ) : (
                       <div>
                           <label className="block text-[10px] font-black text-gray-400 mb-2 uppercase tracking-widest">Recipient (Optional)</label>
                           <input 
                                type="text"
                                placeholder="Name"
                                value={entry.recipient}
                                onChange={(e) => updateEntry(index, 'recipient', e.target.value)}
                                className="w-full rounded-2xl border-gray-100 shadow-sm focus:ring-4 focus:ring-primary/10 focus:border-primary p-3.5 border text-sm font-bold outline-none"
                            />
                       </div>
                   )}
                </div>
              </div>
            ))}

            <div className="flex flex-col sm:flex-row justify-between items-center gap-6 pt-4">
                <button 
                    onClick={handleAddEntry}
                    className="w-full sm:w-auto flex items-center justify-center text-[10px] font-black uppercase tracking-widest text-primary hover:text-teal-800 p-4 hover:bg-teal-50 rounded-2xl transition-all"
                >
                    <Plus size={18} className="mr-2" /> Add Batch Item
                </button>
                <button 
                    onClick={validateAndSave}
                    className={`w-full sm:w-auto flex items-center justify-center px-10 py-5 rounded-[2rem] text-white text-xs font-black uppercase tracking-widest shadow-2xl transition-all active:scale-95 duration-200 ${
                        activeTab === 'INCOME' ? 'bg-emerald-600 hover:bg-emerald-700' 
                        : activeTab === 'EXPENSE' ? 'bg-rose-600 hover:bg-rose-700' 
                        : 'bg-blue-600 hover:bg-blue-700'
                    }`}
                >
                    <Save size={20} className="mr-3" /> Commit Records
                </button>
            </div>
          </div>
        </div>
      </div>

      {/* Interactive History List */}
      <div className="bg-white rounded-[2rem] shadow-xl shadow-gray-200/50 border border-gray-100 overflow-hidden">
        <div className="p-6 md:p-10 border-b border-gray-50 flex flex-col xl:flex-row justify-between items-start xl:items-center gap-6 bg-gray-50/30">
            <h3 className="font-black text-gray-900 text-xl tracking-tighter">History Feed</h3>
            <div className="flex flex-col md:flex-row gap-3 w-full xl:w-auto">
                <div className="relative flex-1">
                    <Search className="absolute left-4 top-4 text-gray-400" size={18} />
                    <input 
                        type="text" 
                        placeholder="Filter transactions..." 
                        value={searchTerm}
                        onChange={(e) => setSearchTerm(e.target.value)}
                        className="pl-12 pr-6 py-4 bg-white border border-gray-100 rounded-2xl text-sm font-medium focus:outline-none focus:ring-4 focus:ring-primary/10 w-full shadow-sm"
                    />
                </div>
                <div className="flex gap-3">
                    <button
                        onClick={() => setShowArchived(!showArchived)}
                        className={`flex items-center gap-2 px-5 py-4 rounded-2xl text-[10px] font-black uppercase tracking-widest border transition-all ${
                            showArchived ? 'bg-gray-900 text-white border-gray-900' : 'bg-white text-gray-500 border-gray-100 hover:bg-gray-50'
                        }`}
                    >
                        {showArchived ? 'Active Only' : 'Inc. Archived'}
                    </button>
                    <select 
                        value={filterAccount}
                        onChange={(e) => setFilterAccount(e.target.value)}
                        className="py-4 px-5 bg-white border border-gray-100 rounded-2xl text-[10px] font-black uppercase tracking-widest focus:outline-none shadow-sm cursor-pointer"
                    >
                        <option value="ALL">All Accounts</option>
                        {accounts.map(a => <option key={a} value={a}>{a}</option>)}
                    </select>
                </div>
            </div>
        </div>

        <div className="divide-y divide-gray-50">
            {filteredList.map(t => (
                <div 
                    key={t.id} 
                    onClick={() => setSelectedTransaction(t)}
                    className={`p-6 md:px-10 flex flex-col md:flex-row justify-between items-start md:items-center gap-4 transition-all cursor-pointer hover:bg-primary/5 group ${t.isArchived ? 'opacity-60 bg-gray-50/50' : ''}`}
                >
                    <div className="flex items-center gap-6 flex-1">
                        <div className="text-center min-w-[60px]">
                            <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest leading-none">{new Date(t.date).toLocaleString('default', { month: 'short' })}</p>
                            <p className="text-xl font-black text-gray-900 leading-none mt-1">{new Date(t.date).getDate()}</p>
                        </div>
                        <div className="h-10 w-px bg-gray-100 hidden md:block" />
                        <div>
                            <div className="flex items-center gap-2 mb-1">
                                <span className={`text-[8px] font-black px-2 py-0.5 rounded-full uppercase tracking-widest ${
                                    t.type === TransactionType.INCOME ? 'bg-emerald-100 text-emerald-800' :
                                    t.type === TransactionType.EXPENSE ? 'bg-rose-100 text-rose-800' : 'bg-blue-100 text-blue-800'
                                }`}>{t.type}</span>
                                <span className="text-[10px] font-bold text-gray-400 uppercase tracking-widest">{t.accountId}</span>
                            </div>
                            <h4 className="font-bold text-gray-800 leading-tight">{t.category}</h4>
                            {t.notes && <p className="text-xs text-gray-400 mt-1 italic line-clamp-1">{t.notes}</p>}
                        </div>
                    </div>
                    <div className="flex items-center gap-6 w-full md:w-auto justify-between md:justify-end">
                        <div className="text-right">
                            <p className={`text-xl font-black tracking-tighter ${
                                t.type === TransactionType.INCOME ? 'text-emerald-600' : 'text-rose-600'
                            }`}>
                                {t.type === TransactionType.EXPENSE ? '-' : ''}{formatCurrency(t.amount)}
                            </p>
                            {t.isArchived && <span className="text-[8px] font-black text-gray-400 uppercase tracking-widest">Archived</span>}
                        </div>
                        <ChevronRight className="text-gray-300 group-hover:text-primary transition-all group-hover:translate-x-1" size={20} />
                    </div>
                </div>
            ))}
            {filteredList.length === 0 && (
                <div className="py-20 text-center text-gray-400 italic">No records found.</div>
            )}
        </div>
      </div>

      {/* High-Fidelity Detail Modal */}
      {selectedTransaction && (
          <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-gray-950/70 backdrop-blur-md animate-in fade-in duration-300">
              <div className="bg-white rounded-[2.5rem] shadow-2xl w-full max-w-xl overflow-hidden animate-in zoom-in-95 duration-300">
                  <div className={`p-8 md:p-10 border-b border-gray-50 flex justify-between items-start ${
                      selectedTransaction.type === TransactionType.INCOME ? 'bg-emerald-50/50' :
                      selectedTransaction.type === TransactionType.EXPENSE ? 'bg-rose-50/50' : 'bg-blue-50/50'
                  }`}>
                      <div className="flex-1">
                          <div className="flex items-center gap-2 mb-2">
                             <span className="px-3 py-1 bg-white/80 rounded-full text-[9px] font-black uppercase tracking-widest text-gray-500 shadow-sm">Transaction Audit</span>
                             {selectedTransaction.isArchived && <span className="px-3 py-1 bg-gray-900 text-white text-[9px] font-black rounded-full uppercase tracking-widest">Archived</span>}
                          </div>
                          <h3 className="text-3xl font-black text-gray-900 tracking-tighter leading-none">{selectedTransaction.category}</h3>
                      </div>
                      <button onClick={() => setSelectedTransaction(null)} className="p-3 bg-white/80 hover:bg-white rounded-2xl transition-all text-gray-400 hover:text-gray-900 shadow-sm active:scale-90">
                          <X size={24} />
                      </button>
                  </div>

                  <div className="p-8 md:p-10 space-y-8 overflow-y-auto max-h-[60vh] no-scrollbar">
                      <div className="flex flex-col items-center justify-center py-6 bg-gray-50/50 rounded-[2rem] border border-gray-100">
                          <span className={`text-6xl font-black tracking-tighter ${
                             selectedTransaction.type === TransactionType.INCOME ? 'text-emerald-600' : 'text-rose-600'
                          }`}>
                              {selectedTransaction.type === TransactionType.EXPENSE ? '-' : ''}
                              {formatCurrency(selectedTransaction.amount)}
                          </span>
                          <span className="text-[10px] font-black text-gray-400 mt-4 uppercase tracking-[0.2em]">{selectedTransaction.type} MODALITY</span>
                      </div>

                      <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                          <div className="flex items-start gap-4 p-4 rounded-2xl bg-gray-50/30">
                              <div className="p-3 bg-white rounded-xl text-primary shadow-sm"><Calendar size={20}/></div>
                              <div>
                                  <p className="text-[9px] font-black text-gray-400 uppercase tracking-widest mb-1">Entry Date</p>
                                  <p className="font-bold text-gray-900">{new Date(selectedTransaction.date).toLocaleDateString('en-GB', { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' })}</p>
                              </div>
                          </div>
                          <div className="flex items-start gap-4 p-4 rounded-2xl bg-gray-50/30">
                              <div className="p-3 bg-white rounded-xl text-primary shadow-sm"><CreditCard size={20}/></div>
                              <div>
                                  <p className="text-[9px] font-black text-gray-400 uppercase tracking-widest mb-1">Account</p>
                                  <p className="font-bold text-gray-900">{selectedTransaction.accountId}</p>
                              </div>
                          </div>
                          {selectedTransaction.recipient && (
                            <div className="flex items-start gap-4 p-4 rounded-2xl bg-gray-50/30">
                                <div className="p-3 bg-white rounded-xl text-primary shadow-sm"><User size={20}/></div>
                                <div>
                                    <p className="text-[9px] font-black text-gray-400 uppercase tracking-widest mb-1">Counterparty</p>
                                    <p className="font-bold text-gray-900">{selectedTransaction.recipient}</p>
                                </div>
                            </div>
                          )}
                          <div className="flex items-start gap-4 p-4 rounded-2xl bg-gray-50/30 md:col-span-2">
                              <div className="p-3 bg-white rounded-xl text-primary shadow-sm"><FileText size={20}/></div>
                              <div>
                                  <p className="text-[9px] font-black text-gray-400 uppercase tracking-widest mb-1">Remarks</p>
                                  <p className="font-medium text-gray-700 leading-relaxed text-sm">{selectedTransaction.notes || 'No notes available.'}</p>
                              </div>
                          </div>
                      </div>
                  </div>

                  <div className="p-8 md:p-10 border-t border-gray-50 bg-gray-50/50">
                      {!selectedTransaction.isArchived && (
                          <button 
                              onClick={() => handleArchive(selectedTransaction.id)}
                              className="w-full flex items-center justify-center gap-3 px-8 py-5 bg-white border-2 border-rose-50 text-rose-600 text-xs font-black uppercase tracking-widest rounded-2xl hover:bg-rose-50 hover:border-rose-100 transition-all shadow-xl active:scale-95"
                          >
                              <Archive size={20} /> Archive this record
                          </button>
                      )}
                      {selectedTransaction.isArchived && (
                        <p className="text-center text-[10px] font-black text-gray-400 uppercase tracking-widest">Archived record. See Settings to restore.</p>
                      )}
                  </div>
              </div>
          </div>
      )}
    </div>
  );
};

export default Transactions;

import React, { useState, useEffect } from 'react';
import { Transaction, TransactionType, AccountType, Category } from '../types';
import { formatCurrency } from '../utils';
import { Search, Plus, Save, X, Archive, ArrowRight, Calendar, CreditCard, User, FileText, ChevronRight, Eye, EyeOff } from 'lucide-react';

interface TransactionsProps {
  transactions: Transaction[];
  categories: Category[];
  accounts: AccountType[];
  preSelectedAccount: AccountType | null;
  onAddTransaction: (t: Omit<Transaction, 'id'>) => void;
  onDeleteTransaction: (id: string) => void;
}

type TabType = 'INCOME' | 'EXPENSE' | 'TRANSFER';

const Transactions: React.FC<TransactionsProps> = ({ 
  transactions, 
  categories, 
  accounts, 
  preSelectedAccount,
  onAddTransaction,
  onDeleteTransaction
}) => {
  const [activeTab, setActiveTab] = useState<TabType>('INCOME');
  const [filterAccount, setFilterAccount] = useState<string>(preSelectedAccount || 'ALL');
  const [searchTerm, setSearchTerm] = useState('');
  const [showArchived, setShowArchived] = useState(false);
  const [selectedTransaction, setSelectedTransaction] = useState<Transaction | null>(null);

  const [entries, setEntries] = useState<any[]>([{ 
    amount: '', 
    date: new Date().toISOString().split('T')[0],
    category: '',
    accountId: '',
    toAccountId: '',
    recipient: '',
    notes: '',
    receivedFromFinance: false
  }]);

  useEffect(() => {
    if (preSelectedAccount) setFilterAccount(preSelectedAccount);
  }, [preSelectedAccount]);

  const handleAddEntry = () => {
    setEntries([...entries, { 
      amount: '', 
      date: new Date().toISOString().split('T')[0],
      category: '',
      accountId: '',
      toAccountId: '',
      recipient: '',
      notes: '',
      receivedFromFinance: false
    }]);
  };

  const handleRemoveEntry = (index: number) => {
    if (entries.length > 1) {
      setEntries(entries.filter((_, i) => i !== index));
    }
  };

  const updateEntry = (index: number, field: string, value: any) => {
    const newEntries = [...entries];
    newEntries[index] = { ...newEntries[index], [field]: value };
    setEntries(newEntries);
  };

  const validateAndSave = () => {
    for (const entry of entries) {
      if (!entry.amount || Number(entry.amount) <= 0) {
        alert('Please enter a valid amount.');
        return;
      }
      if (!entry.date) {
        alert('Please select a date.');
        return;
      }
      if (activeTab !== 'TRANSFER' && !entry.category) {
        alert('Please select a category.');
        return;
      }
      if (!entry.accountId) {
        alert('Please select an account.');
        return;
      }
    }

    entries.forEach(entry => {
      onAddTransaction({
        date: entry.date,
        amount: Number(entry.amount),
        type: activeTab === 'INCOME' ? TransactionType.INCOME : activeTab === 'EXPENSE' ? TransactionType.EXPENSE : TransactionType.TRANSFER,
        category: activeTab === 'TRANSFER' ? 'Finance Transfer' : entry.category,
        accountId: entry.accountId,
        toAccountId: activeTab === 'TRANSFER' ? entry.toAccountId : undefined,
        recipient: entry.recipient,
        notes: entry.notes,
        isArchived: false,
        meta: {
            receivedFromFinance: entry.receivedFromFinance
        }
      });
    });

    setEntries([{ 
      amount: '', 
      date: new Date().toISOString().split('T')[0],
      category: '',
      accountId: '',
      toAccountId: '',
      recipient: '',
      notes: '',
      receivedFromFinance: false
    }]);
    alert('Transaction(s) saved successfully!');
  };

  const handleArchive = (id: string) => {
      if (window.confirm('Moving this record to archives will hide it from active balances. Continue?')) {
          onDeleteTransaction(id); // Sets isArchived: true in state
          setSelectedTransaction(null);
      }
  };

  const filteredList = transactions
    .filter(t => showArchived ? true : !t.isArchived)
    .filter(t => filterAccount === 'ALL' || t.accountId === filterAccount || t.toAccountId === filterAccount)
    .filter(t => 
      t.category.toLowerCase().includes(searchTerm.toLowerCase()) || 
      t.notes?.toLowerCase().includes(searchTerm.toLowerCase()) ||
      t.recipient?.toLowerCase().includes(searchTerm.toLowerCase())
    )
    .sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());

  return (
    <div className="space-y-6">
      {/* Entry Form Card */}
      <div className="bg-white rounded-[2rem] shadow-xl shadow-gray-200/50 border border-gray-100 overflow-hidden">
        <div className="flex border-b border-gray-100 overflow-x-auto no-scrollbar bg-gray-50/30">
          {(['INCOME', 'EXPENSE', 'TRANSFER'] as TabType[]).map(tab => (
            <button
              key={tab}
              onClick={() => setActiveTab(tab)}
              className={`flex-1 min-w-[100px] py-6 text-[10px] font-black tracking-widest transition-all outline-none relative uppercase ${
                activeTab === tab 
                  ? tab === 'INCOME' ? 'text-emerald-600' : tab === 'EXPENSE' ? 'text-rose-600' : 'text-blue-600'
                  : 'text-gray-400 hover:text-gray-600'
              }`}
            >
              {tab}
              {activeTab === tab && (
                <div className={`absolute bottom-0 left-0 right-0 h-1 mx-8 rounded-t-full animate-in slide-in-from-bottom-2 duration-300 ${
                  tab === 'INCOME' ? 'bg-emerald-500' : tab === 'EXPENSE' ? 'bg-rose-500' : 'bg-blue-500'
                }`} />
              )}
            </button>
          ))}
        </div>

        <div className="p-6 md:p-10">
          <div className="space-y-6">
            {entries.map((entry, index) => (
              <div key={index} className="relative p-6 md:p-8 bg-gray-50/50 rounded-3xl border border-gray-200 space-y-6 shadow-inner group transition-all hover:bg-white hover:shadow-lg">
                {entries.length > 1 && (
                    <button onClick={() => handleRemoveEntry(index)} className="absolute top-4 right-4 text-gray-300 hover:text-rose-500 z-10 p-2 bg-white rounded-2xl shadow-sm border border-gray-100 hover:scale-110 transition-all">
                        <X size={18} />
                    </button>
                )}

                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
                  <div>
                    <label className="block text-[10px] font-black text-gray-400 mb-2 uppercase tracking-widest">Entry Date</label>
                    <input 
                        type="date" 
                        value={entry.date}
                        onChange={(e) => updateEntry(index, 'date', e.target.value)}
                        className="w-full rounded-2xl border-gray-100 shadow-sm focus:ring-4 focus:ring-primary/10 focus:border-primary p-3.5 border text-sm font-bold outline-none"
                    />
                  </div>
                  <div>
                    <label className="block text-[10px] font-black text-gray-400 mb-2 uppercase tracking-widest">GHC Amount</label>
                    <input 
                        type="number" 
                        placeholder="0.00"
                        value={entry.amount}
                        onChange={(e) => updateEntry(index, 'amount', e.target.value)}
                        className="w-full rounded-2xl border-gray-100 shadow-sm focus:ring-4 focus:ring-primary/10 focus:border-primary p-3.5 border text-sm font-bold outline-none"
                    />
                  </div>
                  {activeTab !== 'TRANSFER' && (
                    <div className="md:col-span-2">
                        <label className="block text-[10px] font-black text-gray-400 mb-2 uppercase tracking-widest">Classification</label>
                        <select 
                            value={entry.category}
                            onChange={(e) => updateEntry(index, 'category', e.target.value)}
                            className="w-full rounded-2xl border-gray-100 shadow-sm focus:ring-4 focus:ring-primary/10 focus:border-primary p-3.5 border text-sm font-bold outline-none bg-white cursor-pointer"
                        >
                            <option value="">Select Category...</option>
                            {categories
                                .filter(c => c.type === 'BOTH' || c.type === activeTab)
                                .map(c => <option key={c.id} value={c.name}>{c.name}</option>)}
                        </select>
                    </div>
                  )}
                </div>

                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                   <div>
                        <label className="block text-[10px] font-black text-gray-400 mb-2 uppercase tracking-widest">
                            {activeTab === 'TRANSFER' ? 'Source Account' : 'Account Type'}
                        </label>
                        <select 
                            value={entry.accountId}
                            onChange={(e) => updateEntry(index, 'accountId', e.target.value)}
                            className="w-full rounded-2xl border-gray-100 shadow-sm focus:ring-4 focus:ring-primary/10 focus:border-primary p-3.5 border text-sm font-bold outline-none bg-white cursor-pointer"
                        >
                            <option value="">Select Account...</option>
                            {accounts.map(a => <option key={a} value={a}>{a}</option>)}
                        </select>
                   </div>
                   {activeTab === 'TRANSFER' ? (
                       <div>
                            <label className="block text-[10px] font-black text-gray-400 mb-2 uppercase tracking-widest">Destination</label>
                            <select 
                                value={entry.toAccountId}
                                onChange={(e) => updateEntry(index, 'toAccountId', e.target.value)}
                                className="w-full rounded-2xl border-gray-100 shadow-sm focus:ring-4 focus:ring-primary/10 focus:border-primary p-3.5 border text-sm font-bold outline-none bg-white cursor-pointer"
                            >
                                <option value="">To Account...</option>
                                {accounts.map(a => <option key={a} value={a}>{a}</option>)}
                            </select>
                       </div>
                   ) : (
                       <div>
                           <label className="block text-[10px] font-black text-gray-400 mb-2 uppercase tracking-widest">Recipient (Optional)</label>
                           <input 
                                type="text"
                                placeholder="Name"
                                value={entry.recipient}
                                onChange={(e) => updateEntry(index, 'recipient', e.target.value)}
                                className="w-full rounded-2xl border-gray-100 shadow-sm focus:ring-4 focus:ring-primary/10 focus:border-primary p-3.5 border text-sm font-bold outline-none"
                            />
                       </div>
                   )}
                </div>
              </div>
            ))}

            <div className="flex flex-col sm:flex-row justify-between items-center gap-6 pt-4">
                <button 
                    onClick={handleAddEntry}
                    className="w-full sm:w-auto flex items-center justify-center text-[10px] font-black uppercase tracking-widest text-primary hover:text-teal-800 p-4 hover:bg-teal-50 rounded-2xl transition-all"
                >
                    <Plus size={18} className="mr-2" /> Add Batch Item
                </button>
                <button 
                    onClick={validateAndSave}
                    className={`w-full sm:w-auto flex items-center justify-center px-10 py-5 rounded-[2rem] text-white text-xs font-black uppercase tracking-widest shadow-2xl transition-all active:scale-95 duration-200 ${
                        activeTab === 'INCOME' ? 'bg-emerald-600 hover:bg-emerald-700' 
                        : activeTab === 'EXPENSE' ? 'bg-rose-600 hover:bg-rose-700' 
                        : 'bg-blue-600 hover:bg-blue-700'
                    }`}
                >
                    <Save size={20} className="mr-3" /> Commit Records
                </button>
            </div>
          </div>
        </div>
      </div>

      {/* History Feed Header */}
      <div className="bg-white rounded-[2rem] shadow-xl shadow-gray-200/50 border border-gray-100 overflow-hidden">
        <div className="p-6 md:p-10 border-b border-gray-50 flex flex-col xl:flex-row justify-between items-start xl:items-center gap-6 bg-gray-50/30">
            <h3 className="font-black text-gray-900 text-xl tracking-tighter">History Feed</h3>
            <div className="flex flex-col md:flex-row gap-3 w-full xl:w-auto">
                <div className="relative flex-1">
                    <Search className="absolute left-4 top-4 text-gray-400" size={18} />
                    <input 
                        type="text" 
                        placeholder="Search categories or notes..." 
                        value={searchTerm}
                        onChange={(e) => setSearchTerm(e.target.value)}
                        className="pl-12 pr-6 py-4 bg-white border border-gray-100 rounded-2xl text-sm font-medium focus:outline-none focus:ring-4 focus:ring-primary/10 w-full shadow-sm"
                    />
                </div>
                <div className="flex gap-3">
                    <button
                        onClick={() => setShowArchived(!showArchived)}
                        className={`flex items-center gap-2 px-5 py-4 rounded-2xl text-[10px] font-black uppercase tracking-widest border transition-all shadow-md ${
                            showArchived ? 'bg-gray-900 text-white border-gray-900' : 'bg-white text-gray-500 border-gray-100 hover:bg-gray-50'
                        }`}
                        title={showArchived ? "Hide Archived Items" : "Show Archived Items"}
                    >
                        {showArchived ? <EyeOff size={18} /> : <Eye size={18} />}
                        <span className="hidden sm:inline">{showArchived ? 'Active Only' : 'Inc. Archived'}</span>
                    </button>
                    <select 
                        value={filterAccount}
                        onChange={(e) => setFilterAccount(e.target.value)}
                        className="py-4 px-5 bg-white border border-gray-100 rounded-2xl text-[10px] font-black uppercase tracking-widest focus:outline-none shadow-sm cursor-pointer"
                    >
