                    </div>
                    <button 
                        onClick={handleAddCategory}
                        className="bg-primary text-white p-4 rounded-2xl hover:bg-teal-800 transition-all shadow-xl shadow-primary/20 flex justify-center items-center active:scale-95"
                    >
                        <Plus size={24} />
                    </button>
                </div>

                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                    {categories.map(cat => (
                        <div key={cat.id} className="flex justify-between items-center p-5 border border-gray-100 rounded-2xl hover:bg-gray-50 transition-all bg-white shadow-sm group">
                            <div>
                                <span className="font-bold text-gray-800 block text-sm">{cat.name}</span>
                                <span className={`text-[9px] px-2 py-0.5 rounded-lg uppercase font-black tracking-widest mt-1 inline-block ${
                                    cat.type === 'INCOME' ? 'bg-emerald-100 text-emerald-800' :
                                    cat.type === 'EXPENSE' ? 'bg-rose-100 text-rose-800' : 'bg-blue-100 text-blue-800'
                                }`}>{cat.type}</span>
                            </div>
                            <button onClick={() => onDeleteCategory(cat.id)} className="text-gray-200 hover:text-rose-600 p-2 hover:bg-rose-50 rounded-xl transition-all opacity-0 group-hover:opacity-100">
                                <Trash2 size={20} />
                            </button>
                        </div>
                    ))}
                </div>
            </div>
        )}

        {/* --- USERS SECTION --- */}
        {activeSection === 'USERS' && (
             <div className="space-y-8 animate-in fade-in duration-500">
                 <div className="flex justify-between items-end border-b border-gray-100 pb-4">
                    <div>
                        <h3 className="text-2xl font-black text-gray-900 tracking-tighter uppercase">Personnel Directory</h3>
                        <p className="text-sm font-medium text-gray-400 mt-1">Authorized ministry finance representatives.</p>
                    </div>
                 </div>

                 <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
                     {users.map(user => (
                         <div key={user.id} className="p-6 border border-gray-100 rounded-[2rem] bg-gray-50 flex items-center justify-between shadow-sm">
                             <div className="flex items-center gap-4">
                                <div className="h-14 w-14 rounded-2xl bg-primary/10 text-primary flex items-center justify-center font-black text-xl">
                                    {user.name.charAt(0)}
                                </div>
                                <div>
                                    <p className="font-black text-gray-900 tracking-tight">{user.name}</p>
                                    <p className="text-xs text-gray-500 font-medium">{user.email}</p>
                                    <p className="text-[10px] text-gray-400 font-bold mt-1 uppercase tracking-widest">{user.phone}</p>
                                </div>
                             </div>
                             <span className="px-3 py-1 bg-white border border-gray-200 text-gray-500 rounded-lg text-[9px] font-black uppercase tracking-widest">
                                 {user.role}
                             </span>
                         </div>
                     ))}
                 </div>
                 <div className="bg-gray-950 p-10 rounded-[2.5rem] text-center shadow-2xl">
                     <p className="text-[10px] font-black text-gray-500 uppercase tracking-[0.4em] mb-4">Centralized Auth Protocol</p>
                     <p className="text-white text-sm font-bold tracking-tight">Cloud user synchronization is managed by the Global Administrator.</p>
                 </div>
             </div>
        )}

        {/* --- ARCHIVE SECTION --- */}
        {activeSection === 'ARCHIVE' && (
            <div className="space-y-8 animate-in fade-in duration-500">
                <div className="flex flex-col lg:flex-row justify-between items-start lg:items-end border-b border-gray-100 pb-6 gap-6">
                    <div>
                        <h3 className="text-2xl font-black text-gray-900 tracking-tighter uppercase">Financial Archives</h3>
                        <p className="text-sm font-medium text-gray-400 mt-1">Audit log of deactivated ministry transactions.</p>
                    </div>
                    <div className="relative w-full lg:w-72">
                        <Search className="absolute left-4 top-4 text-gray-400" size={18} />
                        <input 
                            type="text" 
                            placeholder="Search archives..." 
                            className="pl-12 pr-6 py-4 w-full bg-gray-50 border border-gray-100 rounded-2xl text-sm font-bold focus:outline-none focus:ring-4 focus:ring-primary/5 transition-all"
                            value={archiveSearch}
                            onChange={(e) => setArchiveSearch(e.target.value)}
                        />
                    </div>
                </div>

                {filteredArchive.length === 0 ? (
                    <div className="flex flex-col items-center justify-center py-24 bg-gray-50/50 rounded-[3rem] border-2 border-dashed border-gray-100 text-gray-300">
                         <Archive size={64} className="mb-4 opacity-20" />
                         <p className="font-black uppercase tracking-widest text-xs">No records in vault</p>
                    </div>
                ) : (
                    <div className="space-y-4">
                        {filteredArchive.map(t => (
                            <div key={t.id} className="p-6 border border-gray-100 rounded-[2rem] bg-white shadow-sm flex flex-col md:flex-row justify-between items-start md:items-center gap-6 hover:shadow-md transition-all">
                                <div className="flex items-center gap-6 flex-1">
                                    <div className="p-4 bg-gray-50 rounded-2xl text-center min-w-[70px]">
                                        <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest">{new Date(t.date).toLocaleString('default', { month: 'short' })}</p>
                                        <p className="text-lg font-black text-gray-900">{new Date(t.date).getDate()}</p>
                                    </div>
                                    <div>
                                        <h4 className="font-black text-gray-800 tracking-tight">{t.category}</h4>
                                        <p className="text-xs text-gray-400 font-medium mt-1 line-clamp-1 italic">{t.notes || 'No remarks recorded.'}</p>
                                        <div className="flex gap-2 mt-2">
                                            <span className="text-[9px] font-black uppercase tracking-widest text-gray-400 bg-gray-100 px-2 py-0.5 rounded-lg">{t.accountId}</span>
                                            <span className="text-[9px] font-black uppercase tracking-widest text-rose-400 bg-rose-50 px-2 py-0.5 rounded-lg">Archived</span>
                                        </div>
                                    </div>
                                </div>
                                <div className="flex flex-col md:items-end gap-3 w-full md:w-auto pt-4 md:pt-0 border-t md:border-t-0 border-gray-50">
                                    <p className="text-xl font-black text-gray-900 tracking-tighter">{formatCurrency(t.amount)}</p>
                                    <button 
                                        onClick={() => {
                                            if (window.confirm('Restore this transaction to active balances?')) {
                                                onRestoreTransaction(t.id);
                                            }
                                        }}
                                        className="w-full md:w-auto flex items-center justify-center gap-2 px-6 py-3 bg-primary text-white hover:bg-teal-800 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all shadow-lg shadow-primary/20 active:scale-95"
                                    >
                                        <RefreshCw size={14} /> Restore Item
                                    </button>
                                </div>
                            </div>
                        ))}
                    </div>
                )}

                {archivedTransactions.length > 0 && (
                    <div className="p-8 bg-gray-100 rounded-[2.5rem] border border-gray-200">
                        <div className="flex items-center gap-4 mb-4">
                            <div className="p-2 bg-white rounded-xl text-gray-400"><FileText size={20}/></div>
                            <h4 className="font-black text-gray-900 uppercase tracking-widest text-xs">Retention Policy</h4>
                        </div>
                        <p className="text-xs font-medium text-gray-500 leading-relaxed">
                            Archived records are maintained for audit purposes but are excluded from primary overview dashboards and active liquidity calculations. Total Archived Value: <span className="font-bold text-gray-800">{formatCurrency(archivedTransactions.reduce((acc, t) => acc + t.amount, 0))}</span>.
                        </p>
                    </div>
                )}
            </div>
        )}
      </div>
    </div>
  );
};

export default Settings;

import React, { useState, useEffect } from 'react';
import { Transaction, TransactionType, AccountType, Category } from '../types';
import { formatCurrency } from '../utils';
import { Search, Plus, Save, X, Archive, ArrowRight, Calendar, CreditCard, User, FileText, ChevronRight, Eye, EyeOff, ListFilter } from 'lucide-react';

interface TransactionsProps {
  transactions: Transaction[];
  categories: Category[];
  accounts: AccountType[];
  preSelectedAccount: AccountType | null;
  onAddTransaction: (t: Omit<Transaction, 'id'>) => void;
  onDeleteTransaction: (id: string) => void;
}

type TabType = 'INCOME' | 'EXPENSE' | 'TRANSFER';

const Transactions: React.FC<TransactionsProps> = ({ 
  transactions, 
  categories, 
  accounts, 
  preSelectedAccount,
  onAddTransaction,
  onDeleteTransaction
}) => {
  const [activeTab, setActiveTab] = useState<TabType>('INCOME');
  const [filterAccount, setFilterAccount] = useState<string>(preSelectedAccount || 'ALL');
  const [searchTerm, setSearchTerm] = useState('');
  const [showArchived, setShowArchived] = useState(false);
  const [selectedTransaction, setSelectedTransaction] = useState<Transaction | null>(null);

  // New state for limiting entries
  const [itemsPerPage, setItemsPerPage] = useState<number>(25);

  const [entries, setEntries] = useState<any[]>([{ 
    amount: '', 
    date: new Date().toISOString().split('T')[0],
    category: '',
    accountId: '',
    toAccountId: '',
    recipient: '',
    notes: '',
    receivedFromFinance: false
  }]);

  useEffect(() => {
    if (preSelectedAccount) setFilterAccount(preSelectedAccount);
  }, [preSelectedAccount]);

  const handleAddEntry = () => {
    setEntries([...entries, { 
      amount: '', 
      date: new Date().toISOString().split('T')[0],
      category: '',
      accountId: '',
      toAccountId: '',
      recipient: '',
      notes: '',
      receivedFromFinance: false
    }]);
  };

  const handleRemoveEntry = (index: number) => {
    if (entries.length > 1) {
      setEntries(entries.filter((_, i) => i !== index));
    }
  };

  const updateEntry = (index: number, field: string, value: any) => {
    const newEntries = [...entries];
    newEntries[index] = { ...newEntries[index], [field]: value };
    setEntries(newEntries);
  };

  const validateAndSave = () => {
    for (const entry of entries) {
      if (!entry.amount || Number(entry.amount) <= 0) {
        alert('Please enter a valid amount.');
        return;
      }
      if (!entry.date) {
        alert('Please select a date.');
        return;
      }
      if (activeTab !== 'TRANSFER' && !entry.category) {
        alert('Please select a category.');
        return;
      }
      if (!entry.accountId) {
        alert('Please select an account.');
        return;
      }
    }

    entries.forEach(entry => {
      onAddTransaction({
        date: entry.date,
        amount: Number(entry.amount),
        type: activeTab === 'INCOME' ? TransactionType.INCOME : activeTab === 'EXPENSE' ? TransactionType.EXPENSE : TransactionType.TRANSFER,
        category: activeTab === 'TRANSFER' ? 'Finance Transfer' : entry.category,
        accountId: entry.accountId,
        toAccountId: activeTab === 'TRANSFER' ? entry.toAccountId : undefined,
        recipient: entry.recipient,
        notes: entry.notes,
        isArchived: false,
        meta: {
            receivedFromFinance: entry.receivedFromFinance
        }
      });
    });

    setEntries([{ 
      amount: '', 
      date: new Date().toISOString().split('T')[0],
      category: '',
      accountId: '',
      toAccountId: '',
      recipient: '',
      notes: '',
      receivedFromFinance: false
    }]);
    alert('Transaction(s) saved successfully!');
  };

  // Archive Functionality
  const handleArchive = (id: string) => {
      // Confirms, then calls prop to update state in App.tsx
      if (window.confirm('Are you sure you want to move this record to archives? It will be hidden from current balances and feeds.')) {
          onDeleteTransaction(id); 
          setSelectedTransaction(null); // Close the detail modal
      }
  };

  // 1. Filter Logic
  const filteredList = transactions
    .filter(t => showArchived ? true : !t.isArchived)
    .filter(t => filterAccount === 'ALL' || t.accountId === filterAccount || t.toAccountId === filterAccount)
    .filter(t => 
      t.category.toLowerCase().includes(searchTerm.toLowerCase()) || 
      t.notes?.toLowerCase().includes(searchTerm.toLowerCase()) ||
      t.recipient?.toLowerCase().includes(searchTerm.toLowerCase())
    )
    .sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());

  // 2. Pagination/Limit Logic
  const displayedList = filteredList.slice(0, itemsPerPage);

  return (
    <div className="space-y-6">
      {/* Entry Form Card */}
      <div className="bg-white rounded-[2rem] shadow-xl shadow-gray-200/50 border border-gray-100 overflow-hidden">
        <div className="flex border-b border-gray-100 overflow-x-auto no-scrollbar bg-gray-50/30">
          {(['INCOME', 'EXPENSE', 'TRANSFER'] as TabType[]).map(tab => (
            <button
              key={tab}
              onClick={() => setActiveTab(tab)}
              className={`flex-1 min-w-[100px] py-6 text-[10px] font-black tracking-widest transition-all outline-none relative uppercase ${
                activeTab === tab 
                  ? tab === 'INCOME' ? 'text-emerald-600' : tab === 'EXPENSE' ? 'text-rose-600' : 'text-blue-600'
                  : 'text-gray-400 hover:text-gray-600'
              }`}
            >
              {tab}
              {activeTab === tab && (
                <div className={`absolute bottom-0 left-0 right-0 h-1 mx-8 rounded-t-full animate-in slide-in-from-bottom-2 duration-300 ${
                  tab === 'INCOME' ? 'bg-emerald-500' : tab === 'EXPENSE' ? 'bg-rose-500' : 'bg-blue-500'
                }`} />
              )}
            </button>
          ))}
        </div>

        <div className="p-6 md:p-10">
          <div className="space-y-6">
            {entries.map((entry, index) => (
              <div key={index} className="relative p-6 md:p-8 bg-gray-50/50 rounded-3xl border border-gray-200 space-y-6 shadow-inner group transition-all hover:bg-white hover:shadow-lg">
                {entries.length > 1 && (
                    <button onClick={() => handleRemoveEntry(index)} className="absolute top-4 right-4 text-gray-300 hover:text-rose-500 z-10 p-2 bg-white rounded-2xl shadow-sm border border-gray-100 hover:scale-110 transition-all">
                        <X size={18} />
                    </button>
                )}

                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
                  <div>
                    <label className="block text-[10px] font-black text-gray-400 mb-2 uppercase tracking-widest">Entry Date</label>
                    <input 
                        type="date" 
                        value={entry.date}
                        onChange={(e) => updateEntry(index, 'date', e.target.value)}
                        className="w-full rounded-2xl border-gray-100 shadow-sm focus:ring-4 focus:ring-primary/10 focus:border-primary p-3.5 border text-sm font-bold outline-none"
                    />
                  </div>
                  <div>
                    <label className="block text-[10px] font-black text-gray-400 mb-2 uppercase tracking-widest">GHC Amount</label>
                    <input 
                        type="number" 
                        placeholder="0.00"
                        value={entry.amount}
                        onChange={(e) => updateEntry(index, 'amount', e.target.value)}
                        className="w-full rounded-2xl border-gray-100 shadow-sm focus:ring-4 focus:ring-primary/10 focus:border-primary p-3.5 border text-sm font-bold outline-none"
                    />
                  </div>
                  {activeTab !== 'TRANSFER' && (
                    <div className="md:col-span-2">
                        <label className="block text-[10px] font-black text-gray-400 mb-2 uppercase tracking-widest">Classification</label>
                        <select 
                            value={entry.category}
                            onChange={(e) => updateEntry(index, 'category', e.target.value)}
                            className="w-full rounded-2xl border-gray-100 shadow-sm focus:ring-4 focus:ring-primary/10 focus:border-primary p-3.5 border text-sm font-bold outline-none bg-white cursor-pointer"
                        >
                            <option value="">Select Category...</option>
                            {categories
                                .filter(c => c.type === 'BOTH' || c.type === activeTab)
                                .map(c => <option key={c.id} value={c.name}>{c.name}</option>)}
                        </select>
                    </div>
                  )}
                </div>

                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                   <div>
                        <label className="block text-[10px] font-black text-gray-400 mb-2 uppercase tracking-widest">
                            {activeTab === 'TRANSFER' ? 'Source Account' : 'Account Type'}
                        </label>
                        <select 
                            value={entry.accountId}
                            onChange={(e) => updateEntry(index, 'accountId', e.target.value)}
                            className="w-full rounded-2xl border-gray-100 shadow-sm focus:ring-4 focus:ring-primary/10 focus:border-primary p-3.5 border text-sm font-bold outline-none bg-white cursor-pointer"
                        >
                            <option value="">Select Account...</option>
                            {accounts.map(a => <option key={a} value={a}>{a}</option>)}
                        </select>
                   </div>
                   {activeTab === 'TRANSFER' ? (
                       <div>
                            <label className="block text-[10px] font-black text-gray-400 mb-2 uppercase tracking-widest">Destination</label>
                            <select 
                                value={entry.toAccountId}
                                onChange={(e) => updateEntry(index, 'toAccountId', e.target.value)}
                                className="w-full rounded-2xl border-gray-100 shadow-sm focus:ring-4 focus:ring-primary/10 focus:border-primary p-3.5 border text-sm font-bold outline-none bg-white cursor-pointer"
                            >
                                <option value="">To Account...</option>
                                {accounts.map(a => <option key={a} value={a}>{a}</option>)}
                            </select>
                       </div>
                   ) : (
                       <div>
                           <label className="block text-[10px] font-black text-gray-400 mb-2 uppercase tracking-widest">Recipient (Optional)</label>
                           <input 
                                type="text"
                                placeholder="Name"
                                value={entry.recipient}
                                onChange={(e) => updateEntry(index, 'recipient', e.target.value)}
                                className="w-full rounded-2xl border-gray-100 shadow-sm focus:ring-4 focus:ring-primary/10 focus:border-primary p-3.5 border text-sm font-bold outline-none"
                            />
                       </div>
                   )}
                </div>
              </div>
            ))}

            <div className="flex flex-col sm:flex-row justify-between items-center gap-6 pt-4">
                <button 
                    onClick={handleAddEntry}
                    className="w-full sm:w-auto flex items-center justify-center text-[10px] font-black uppercase tracking-widest text-primary hover:text-teal-800 p-4 hover:bg-teal-50 rounded-2xl transition-all"
                >
                    <Plus size={18} className="mr-2" /> Add Batch Item
                </button>
                <button 
                    onClick={validateAndSave}
                    className={`w-full sm:w-auto flex items-center justify-center px-10 py-5 rounded-[2rem] text-white text-xs font-black uppercase tracking-widest shadow-2xl transition-all active:scale-95 duration-200 ${
                        activeTab === 'INCOME' ? 'bg-emerald-600 hover:bg-emerald-700' 
                        : activeTab === 'EXPENSE' ? 'bg-rose-600 hover:bg-rose-700' 
                        : 'bg-blue-600 hover:bg-blue-700'
                    }`}
                >
                    <Save size={20} className="mr-3" /> Commit Records
                </button>
            </div>
          </div>
        </div>
      </div>

      {/* History Feed List */}
      <div className="bg-white rounded-[2rem] shadow-xl shadow-gray-200/50 border border-gray-100 overflow-hidden">
        <div className="p-6 md:p-10 border-b border-gray-50 flex flex-col xl:flex-row justify-between items-start xl:items-center gap-6 bg-gray-50/30">
            <h3 className="font-black text-gray-900 text-xl tracking-tighter">History Feed</h3>
            <div className="flex flex-col md:flex-row gap-3 w-full xl:w-auto">
                <div className="relative flex-1">
                    <Search className="absolute left-4 top-4 text-gray-400" size={18} />
                    <input 
                        type="text" 
                        placeholder="Search categories or notes..." 
                        value={searchTerm}
                        onChange={(e) => setSearchTerm(e.target.value)}
                        className="pl-12 pr-6 py-4 bg-white border border-gray-100 rounded-2xl text-sm font-medium focus:outline-none focus:ring-4 focus:ring-primary/10 w-full shadow-sm"
                    />
                </div>
                <div className="flex gap-3 overflow-x-auto no-scrollbar pb-1 md:pb-0">
                    <button
                        onClick={() => setShowArchived(!showArchived)}
                        className={`flex items-center gap-2 px-5 py-4 rounded-2xl text-[10px] font-black uppercase tracking-widest border transition-all shadow-md whitespace-nowrap ${
                            showArchived ? 'bg-gray-900 text-white border-gray-900' : 'bg-white text-gray-500 border-gray-100 hover:bg-gray-50'
                        }`}
                        title={showArchived ? "Hide Archived Items" : "Show Archived Items"}
                    >
                        {showArchived ? <EyeOff size={18} /> : <Eye size={18} />}
                        <span className="hidden sm:inline">{showArchived ? 'Active Only' : 'Inc. Archived'}</span>
                    </button>

                    {/* Limit Selection Dropdown */}
                    <div className="relative">
                        <ListFilter className="absolute left-4 top-4 text-gray-400" size={18} />
                        <select 
                            value={itemsPerPage}
                            onChange={(e) => setItemsPerPage(Number(e.target.value))}
                            className="pl-10 pr-8 py-4 bg-white border border-gray-100 rounded-2xl text-[10px] font-black uppercase tracking-widest focus:outline-none shadow-sm cursor-pointer appearance-none"
                        >
                            <option value={25}>Show 25</option>
                            <option value={50}>Show 50</option>
                            <option value={100}>Show 100</option>
                        </select>
                    </div>

                    <select 
                        value={filterAccount}
                        onChange={(e) => setFilterAccount(e.target.value)}
                        className="py-4 px-5 bg-white border border-gray-100 rounded-2xl text-[10px] font-black uppercase tracking-widest focus:outline-none shadow-sm cursor-pointer"
                    >
                        <option value="ALL">All Accounts</option>
                        {accounts.map(a => <option key={a} value={a}>{a}</option>)}
                    </select>
                </div>
            </div>
        </div>

        <div className="divide-y divide-gray-50">
            {displayedList.map(t => (
                <div 
                    key={t.id} 
                    onClick={() => setSelectedTransaction(t)}
                    className={`p-6 md:px-10 flex flex-col md:flex-row justify-between items-start md:items-center gap-4 transition-all cursor-pointer hover:bg-primary/5 group ${t.isArchived ? 'opacity-60 bg-gray-50/50 grayscale-[0.5]' : ''}`}
                >
                    <div className="flex items-center gap-6 flex-1">
                        <div className={`text-center min-w-[60px] p-2 rounded-2xl ${t.isArchived ? 'bg-gray-200' : 'bg-gray-50'}`}>
                            <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest leading-none">{new Date(t.date).toLocaleString('default', { month: 'short' })}</p>
                            <p className="text-xl font-black text-gray-900 leading-none mt-1">{new Date(t.date).getDate()}</p>
                        </div>
                        <div>
                            <div className="flex items-center gap-2 mb-1">
                                <span className={`text-[8px] font-black px-2 py-0.5 rounded-full uppercase tracking-widest ${
                                    t.isArchived ? 'bg-gray-400 text-white' :
                                    t.type === TransactionType.INCOME ? 'bg-emerald-100 text-emerald-800' :
                                    t.type === TransactionType.EXPENSE ? 'bg-rose-100 text-rose-800' : 'bg-blue-100 text-blue-800'
                                }`}>{t.isArchived ? 'ARCHIVED' : t.type}</span>
                                <span className="text-[10px] font-bold text-gray-400 uppercase tracking-widest">{t.accountId}</span>
                            </div>
                            <h4 className={`font-bold leading-tight ${t.isArchived ? 'text-gray-500' : 'text-gray-800'}`}>{t.category}</h4>
                            {t.notes && <p className="text-xs text-gray-400 mt-1 italic line-clamp-1">{t.notes}</p>}
                        </div>
                    </div>
                    <div className="flex items-center gap-6 w-full md:w-auto justify-between md:justify-end">
                        <div className="text-right">
                            <p className={`text-xl font-black tracking-tighter ${
                                t.isArchived ? 'text-gray-500' :
                                t.type === TransactionType.INCOME ? 'text-emerald-600' : 'text-rose-600'
                            }`}>
                                {t.type === TransactionType.EXPENSE ? '-' : ''}{formatCurrency(t.amount)}
                            </p>
                        </div>
                        <ChevronRight className={`transition-all group-hover:translate-x-1 ${t.isArchived ? 'text-gray-300' : 'text-gray-300 group-hover:text-primary'}`} size={20} />
                    </div>
                </div>
            ))}
            {displayedList.length === 0 && (
                <div className="py-24 text-center">
                   <FileText size={48} className="mx-auto text-gray-100 mb-4" />
                   <p className="text-gray-400 font-bold italic">No records match your criteria.</p>
                </div>
            )}
            {filteredList.length > itemsPerPage && (
                <div className="p-6 text-center border-t border-gray-50">
                    <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest">
                        Showing {displayedList.length} of {filteredList.length} records
                    </p>
                </div>
            )}
        </div>
      </div>

      {/* Detail Modal with Functional Archive Button */}
      {selectedTransaction && (
          <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-gray-950/70 backdrop-blur-md animate-in fade-in duration-300">
              <div className="bg-white rounded-[2.5rem] shadow-[0_35px_60px_-15px_rgba(0,0,0,0.5)] w-full max-w-xl overflow-hidden animate-in zoom-in-95 duration-300">
                  <div className={`p-8 md:p-10 border-b border-gray-50 flex justify-between items-start ${
                      selectedTransaction.isArchived ? 'bg-gray-100' :
                      selectedTransaction.type === TransactionType.INCOME ? 'bg-emerald-50/50' :
                      selectedTransaction.type === TransactionType.EXPENSE ? 'bg-rose-50/50' : 'bg-blue-50/50'
                  }`}>
                      <div className="flex-1">
                          <div className="flex items-center gap-2 mb-2">
                             <span className="px-3 py-1 bg-white/80 rounded-full text-[9px] font-black uppercase tracking-widest text-gray-500 shadow-sm">Audit Certificate</span>
                             {selectedTransaction.isArchived && <span className="px-3 py-1 bg-gray-900 text-white text-[9px] font-black rounded-full uppercase tracking-widest">Locked Archive</span>}
                          </div>
                          <h3 className="text-3xl font-black text-gray-900 tracking-tighter leading-none">{selectedTransaction.category}</h3>
                      </div>
                      <button onClick={() => setSelectedTransaction(null)} className="p-3 bg-white/80 hover:bg-white rounded-2xl transition-all text-gray-400 hover:text-gray-900 shadow-sm active:scale-90">
                          <X size={24} />
                      </button>
                  </div>

                  <div className="p-8 md:p-10 space-y-8 overflow-y-auto max-h-[60vh] no-scrollbar">
                      <div className="flex flex-col items-center justify-center py-8 bg-gray-50/50 rounded-[2rem] border border-gray-100 relative overflow-hidden">
                          {selectedTransaction.isArchived && (
                             <div className="absolute inset-0 flex items-center justify-center opacity-[0.03] pointer-events-none">
                                <Archive size={200} />
                             </div>
                          )}
                          <span className={`text-6xl font-black tracking-tighter relative z-10 ${
                             selectedTransaction.isArchived ? 'text-gray-400' :
                             selectedTransaction.type === TransactionType.INCOME ? 'text-emerald-600' : 'text-rose-600'
                          }`}>
                              {selectedTransaction.type === TransactionType.EXPENSE ? '-' : ''}
                              {formatCurrency(selectedTransaction.amount)}
                          </span>
                          <span className="text-[10px] font-black text-gray-400 mt-4 uppercase tracking-[0.2em] relative z-10">
                            {selectedTransaction.isArchived ? 'ARCHIVED VALUATION' : `${selectedTransaction.type} SETTLEMENT`}
                          </span>
                      </div>

                      <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                          <div className="flex items-start gap-4 p-4 rounded-2xl bg-gray-50/30 border border-gray-50">
                              <div className="p-3 bg-white rounded-xl text-primary shadow-sm"><Calendar size={20}/></div>
                              <div>
                                  <p className="text-[9px] font-black text-gray-400 uppercase tracking-widest mb-1">Fiscal Date</p>
                                  <p className="font-bold text-gray-900">{new Date(selectedTransaction.date).toLocaleDateString('en-GB', { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' })}</p>
                              </div>
                          </div>
                          <div className="flex items-start gap-4 p-4 rounded-2xl bg-gray-50/30 border border-gray-50">
                              <div className="p-3 bg-white rounded-xl text-primary shadow-sm"><CreditCard size={20}/></div>
                              <div>
                                  <p className="text-[9px] font-black text-gray-400 uppercase tracking-widest mb-1">Payment Method</p>
                                  <p className="font-bold text-gray-900">{selectedTransaction.accountId}</p>
                              </div>
                          </div>
                          {selectedTransaction.recipient && (
                            <div className="flex items-start gap-4 p-4 rounded-2xl bg-gray-50/30 border border-gray-50">
                                <div className="p-3 bg-white rounded-xl text-primary shadow-sm"><User size={20}/></div>
                                <div>
                                    <p className="text-[9px] font-black text-gray-400 uppercase tracking-widest mb-1">Counterparty</p>
                                    <p className="font-bold text-gray-900">{selectedTransaction.recipient}</p>
                                </div>
                            </div>
                          )}
                          <div className="flex items-start gap-4 p-4 rounded-2xl bg-gray-50/30 border border-gray-50 md:col-span-2">
                              <div className="p-3 bg-white rounded-xl text-primary shadow-sm"><FileText size={20}/></div>
                              <div className="flex-1">
                                  <p className="text-[9px] font-black text-gray-400 uppercase tracking-widest mb-1">Official Notes</p>
                                  <p className="font-medium text-gray-700 leading-relaxed text-sm italic">"{selectedTransaction.notes || 'No remarks provided for this entry.'}"</p>
                              </div>
                          </div>
                      </div>
                  </div>

                  <div className="p-8 md:p-10 border-t border-gray-50 bg-gray-50/50">
                      {!selectedTransaction.isArchived ? (
                          <button 
                              onClick={() => handleArchive(selectedTransaction.id)}
                              className="w-full flex items-center justify-center gap-3 px-8 py-5 bg-white border-2 border-rose-100 text-rose-600 text-xs font-black uppercase tracking-[0.2em] rounded-2xl hover:bg-rose-600 hover:text-white hover:border-rose-600 transition-all shadow-xl active:scale-95"
                          >
                              <Archive size={20} /> Archive this record
                          </button>
                      ) : (
                          <div className="p-5 bg-gray-900 rounded-[1.5rem] text-center">
                            <p className="text-[10px] font-black text-white uppercase tracking-[0.3em] opacity-80 leading-relaxed mb-1">Static Archived Data</p>
                            <p className="text-[9px] text-gray-400 font-bold italic">Restore this item from the Settings &gt; Archives menu if needed.</p>
                          </div>
                      )}
                      <button 
                        onClick={() => setSelectedTransaction(null)}
                        className="w-full mt-4 text-[10px] font-black text-gray-400 uppercase tracking-widest hover:text-gray-900 transition-colors"
                      >
                        Exit Detailed View
                      </button>
                  </div>
              </div>
          </div>
      )}
    </div>
  );
};

export default Transactions;

import React, { useState, useEffect } from 'react';
import { Transaction, TransactionType, AccountType, Category } from '../types';
import { formatCurrency } from '../utils';
import { Search, Plus, Save, X, Archive, ArrowRight, Calendar, CreditCard, User, FileText, ChevronRight, Eye, EyeOff, ListFilter } from 'lucide-react';

interface TransactionsProps {
  transactions: Transaction[];
  categories: Category[];
  accounts: AccountType[];
  preSelectedAccount: AccountType | null;
  onAddTransaction: (t: Omit<Transaction, 'id'>) => void;
  onDeleteTransaction: (id: string) => void;
}

type TabType = 'INCOME' | 'EXPENSE' | 'TRANSFER';

const Transactions: React.FC<TransactionsProps> = ({ 
  transactions, 
  categories, 
  accounts, 
  preSelectedAccount,
  onAddTransaction,
  onDeleteTransaction
}) => {
  const [activeTab, setActiveTab] = useState<TabType>('INCOME');
  const [filterAccount, setFilterAccount] = useState<string>(preSelectedAccount || 'ALL');
  const [searchTerm, setSearchTerm] = useState('');
  const [showArchived, setShowArchived] = useState(false);
  const [selectedTransaction, setSelectedTransaction] = useState<Transaction | null>(null);

  // New state for limiting entries
  const [itemsPerPage, setItemsPerPage] = useState<number>(25);

  const [entries, setEntries] = useState<any[]>([{ 
    amount: '', 
    date: new Date().toISOString().split('T')[0],
    category: '',
    accountId: '',
    toAccountId: '',
    recipient: '',
    notes: '',
    receivedFromFinance: false
  }]);

  useEffect(() => {
    if (preSelectedAccount) setFilterAccount(preSelectedAccount);
  }, [preSelectedAccount]);

  const handleAddEntry = () => {
    setEntries([...entries, { 
      amount: '', 
      date: new Date().toISOString().split('T')[0],
      category: '',
      accountId: '',
      toAccountId: '',
      recipient: '',
      notes: '',
      receivedFromFinance: false
    }]);
  };

  const handleRemoveEntry = (index: number) => {
    if (entries.length > 1) {
      setEntries(entries.filter((_, i) => i !== index));
    }
  };

  const updateEntry = (index: number, field: string, value: any) => {
    const newEntries = [...entries];
    newEntries[index] = { ...newEntries[index], [field]: value };
    setEntries(newEntries);
  };

  const validateAndSave = () => {
    for (const entry of entries) {
      if (!entry.amount || Number(entry.amount) <= 0) {
        alert('Please enter a valid amount.');
        return;
      }
      if (!entry.date) {
        alert('Please select a date.');
        return;
      }
      if (activeTab !== 'TRANSFER' && !entry.category) {
        alert('Please select a category.');
        return;
      }
      if (!entry.accountId) {
        alert('Please select an account.');
        return;
      }
    }

    entries.forEach(entry => {
      onAddTransaction({
        date: entry.date,
        amount: Number(entry.amount),
        type: activeTab === 'INCOME' ? TransactionType.INCOME : activeTab === 'EXPENSE' ? TransactionType.EXPENSE : TransactionType.TRANSFER,
        category: activeTab === 'TRANSFER' ? 'Finance Transfer' : entry.category,
        accountId: entry.accountId,
        toAccountId: activeTab === 'TRANSFER' ? entry.toAccountId : undefined,
        recipient: entry.recipient,
        notes: entry.notes,
        isArchived: false,
        meta: {
            receivedFromFinance: entry.receivedFromFinance
        }
      });
    });

    setEntries([{ 
      amount: '', 
      date: new Date().toISOString().split('T')[0],
      category: '',
      accountId: '',
      toAccountId: '',
      recipient: '',
      notes: '',
      receivedFromFinance: false
    }]);
    alert('Transaction(s) saved successfully!');
  };

  // Archive Functionality
  const handleArchive = (id: string) => {
      // Confirms, then calls prop to update state in App.tsx
      if (window.confirm('Are you sure you want to move this record to archives? It will be hidden from current balances and feeds.')) {
          onDeleteTransaction(id); 
          setSelectedTransaction(null); // Close the detail modal
      }
  };

  // 1. Filter Logic
  const filteredList = transactions
    .filter(t => showArchived ? true : !t.isArchived)
    .filter(t => filterAccount === 'ALL' || t.accountId === filterAccount || t.toAccountId === filterAccount)
    .filter(t => 
      t.category.toLowerCase().includes(searchTerm.toLowerCase()) || 
      t.notes?.toLowerCase().includes(searchTerm.toLowerCase()) ||
      t.recipient?.toLowerCase().includes(searchTerm.toLowerCase())
    )
    .sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());

  // 2. Pagination/Limit Logic
  const displayedList = filteredList.slice(0, itemsPerPage);

  return (
    <div className="space-y-6">
      {/* Entry Form Card */}
      <div className="bg-white rounded-[2rem] shadow-xl shadow-gray-200/50 border border-gray-100 overflow-hidden">
        <div className="flex border-b border-gray-100 overflow-x-auto no-scrollbar bg-gray-50/30">
          {(['INCOME', 'EXPENSE', 'TRANSFER'] as TabType[]).map(tab => (
            <button
              key={tab}
              onClick={() => setActiveTab(tab)}
              className={`flex-1 min-w-[100px] py-6 text-[10px] font-black tracking-widest transition-all outline-none relative uppercase ${
                activeTab === tab 
                  ? tab === 'INCOME' ? 'text-emerald-600' : tab === 'EXPENSE' ? 'text-rose-600' : 'text-blue-600'
                  : 'text-gray-400 hover:text-gray-600'
              }`}
            >
              {tab}
              {activeTab === tab && (
                <div className={`absolute bottom-0 left-0 right-0 h-1 mx-8 rounded-t-full animate-in slide-in-from-bottom-2 duration-300 ${
                  tab === 'INCOME' ? 'bg-emerald-500' : tab === 'EXPENSE' ? 'bg-rose-500' : 'bg-blue-500'
                }`} />
              )}
            </button>
          ))}
        </div>

        <div className="p-6 md:p-10">
          <div className="space-y-6">
            {entries.map((entry, index) => (
              <div key={index} className="relative p-6 md:p-8 bg-gray-50/50 rounded-3xl border border-gray-200 space-y-6 shadow-inner group transition-all hover:bg-white hover:shadow-lg">
                {entries.length > 1 && (
                    <button onClick={() => handleRemoveEntry(index)} className="absolute top-4 right-4 text-gray-300 hover:text-rose-500 z-10 p-2 bg-white rounded-2xl shadow-sm border border-gray-100 hover:scale-110 transition-all">
                        <X size={18} />
                    </button>
                )}

                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
                  <div>
                    <label className="block text-[10px] font-black text-gray-400 mb-2 uppercase tracking-widest">Entry Date</label>
                    <input 
                        type="date" 
                        value={entry.date}
                        onChange={(e) => updateEntry(index, 'date', e.target.value)}
                        className="w-full rounded-2xl border-gray-100 shadow-sm focus:ring-4 focus:ring-primary/10 focus:border-primary p-3.5 border text-sm font-bold outline-none"
                    />
                  </div>
                  <div>
                    <label className="block text-[10px] font-black text-gray-400 mb-2 uppercase tracking-widest">GHC Amount</label>
                    <input 
                        type="number" 
                        placeholder="0.00"
                        value={entry.amount}
                        onChange={(e) => updateEntry(index, 'amount', e.target.value)}
                        className="w-full rounded-2xl border-gray-100 shadow-sm focus:ring-4 focus:ring-primary/10 focus:border-primary p-3.5 border text-sm font-bold outline-none"
                    />
                  </div>
                  {activeTab !== 'TRANSFER' && (
                    <div className="md:col-span-2">
                        <label className="block text-[10px] font-black text-gray-400 mb-2 uppercase tracking-widest">Classification</label>
                        <select 
                            value={entry.category}
                            onChange={(e) => updateEntry(index, 'category', e.target.value)}
                            className="w-full rounded-2xl border-gray-100 shadow-sm focus:ring-4 focus:ring-primary/10 focus:border-primary p-3.5 border text-sm font-bold outline-none bg-white cursor-pointer"
                        >
                            <option value="">Select Category...</option>
                            {categories
                                .filter(c => c.type === 'BOTH' || c.type === activeTab)
                                .map(c => <option key={c.id} value={c.name}>{c.name}</option>)}
                        </select>
                    </div>
                  )}
                </div>

                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                   <div>
                        <label className="block text-[10px] font-black text-gray-400 mb-2 uppercase tracking-widest">
                            {activeTab === 'TRANSFER' ? 'Source Account' : 'Account Type'}
                        </label>
                        <select 
                            value={entry.accountId}
                            onChange={(e) => updateEntry(index, 'accountId', e.target.value)}
                            className="w-full rounded-2xl border-gray-100 shadow-sm focus:ring-4 focus:ring-primary/10 focus:border-primary p-3.5 border text-sm font-bold outline-none bg-white cursor-pointer"
                        >
                            <option value="">Select Account...</option>
                            {accounts.map(a => <option key={a} value={a}>{a}</option>)}
                        </select>
                   </div>
                   {activeTab === 'TRANSFER' ? (
                       <div>
                            <label className="block text-[10px] font-black text-gray-400 mb-2 uppercase tracking-widest">Destination</label>
                            <select 
                                value={entry.toAccountId}
                                onChange={(e) => updateEntry(index, 'toAccountId', e.target.value)}
                                className="w-full rounded-2xl border-gray-100 shadow-sm focus:ring-4 focus:ring-primary/10 focus:border-primary p-3.5 border text-sm font-bold outline-none bg-white cursor-pointer"
                            >
                                <option value="">To Account...</option>
                                {accounts.map(a => <option key={a} value={a}>{a}</option>)}
                            </select>
                       </div>
                   ) : (
                       <div>
                           <label className="block text-[10px] font-black text-gray-400 mb-2 uppercase tracking-widest">Recipient (Optional)</label>
                           <input 
                                type="text"
                                placeholder="Name"
                                value={entry.recipient}
                                onChange={(e) => updateEntry(index, 'recipient', e.target.value)}
                                className="w-full rounded-2xl border-gray-100 shadow-sm focus:ring-4 focus:ring-primary/10 focus:border-primary p-3.5 border text-sm font-bold outline-none"
                            />
                       </div>
                   )}
                </div>
              </div>
            ))}

            <div className="flex flex-col sm:flex-row justify-between items-center gap-6 pt-4">
                <button 
                    onClick={handleAddEntry}
                    className="w-full sm:w-auto flex items-center justify-center text-[10px] font-black uppercase tracking-widest text-primary hover:text-teal-800 p-4 hover:bg-teal-50 rounded-2xl transition-all"
                >
                    <Plus size={18} className="mr-2" /> Add Batch Item
                </button>
                <button 
                    onClick={validateAndSave}
                    className={`w-full sm:w-auto flex items-center justify-center px-10 py-5 rounded-[2rem] text-white text-xs font-black uppercase tracking-widest shadow-2xl transition-all active:scale-95 duration-200 ${
                        activeTab === 'INCOME' ? 'bg-emerald-600 hover:bg-emerald-700' 
                        : activeTab === 'EXPENSE' ? 'bg-rose-600 hover:bg-rose-700' 
                        : 'bg-blue-600 hover:bg-blue-700'
                    }`}
                >
                    <Save size={20} className="mr-3" /> Commit Records
                </button>
            </div>
          </div>
        </div>
      </div>

      {/* History Feed List */}
      <div className="bg-white rounded-[2rem] shadow-xl shadow-gray-200/50 border border-gray-100 overflow-hidden">
        <div className="p-6 md:p-10 border-b border-gray-50 flex flex-col xl:flex-row justify-between items-start xl:items-center gap-6 bg-gray-50/30">
            <h3 className="font-black text-gray-900 text-xl tracking-tighter">History Feed</h3>
            <div className="flex flex-col md:flex-row gap-3 w-full xl:w-auto">
                <div className="relative flex-1">
                    <Search className="absolute left-4 top-4 text-gray-400" size={18} />
                    <input 
                        type="text" 
                        placeholder="Search categories or notes..." 
                        value={searchTerm}
                        onChange={(e) => setSearchTerm(e.target.value)}
                        className="pl-12 pr-6 py-4 bg-white border border-gray-100 rounded-2xl text-sm font-medium focus:outline-none focus:ring-4 focus:ring-primary/10 w-full shadow-sm"
                    />
                </div>
                <div className="flex gap-3 overflow-x-auto no-scrollbar pb-1 md:pb-0">
                    <button
                        onClick={() => setShowArchived(!showArchived)}
                        className={`flex items-center gap-2 px-5 py-4 rounded-2xl text-[10px] font-black uppercase tracking-widest border transition-all shadow-md whitespace-nowrap ${
                            showArchived ? 'bg-gray-900 text-white border-gray-900' : 'bg-white text-gray-500 border-gray-100 hover:bg-gray-50'
                        }`}
                        title={showArchived ? "Hide Archived Items" : "Show Archived Items"}
                    >
                        {showArchived ? <EyeOff size={18} /> : <Eye size={18} />}
                        <span className="hidden sm:inline">{showArchived ? 'Active Only' : 'Inc. Archived'}</span>
                    </button>

                    {/* Limit Selection Dropdown */}
                    <div className="relative">
                        <ListFilter className="absolute left-4 top-4 text-gray-400" size={18} />
                        <select 
                            value={itemsPerPage}
                            onChange={(e) => setItemsPerPage(Number(e.target.value))}
                            className="pl-10 pr-8 py-4 bg-white border border-gray-100 rounded-2xl text-[10px] font-black uppercase tracking-widest focus:outline-none shadow-sm cursor-pointer appearance-none"
                        >
                            <option value={25}>Show 25</option>
                            <option value={50}>Show 50</option>
                            <option value={100}>Show 100</option>
                        </select>
                    </div>

                    <select 
                        value={filterAccount}
                        onChange={(e) => setFilterAccount(e.target.value)}
                        className="py-4 px-5 bg-white border border-gray-100 rounded-2xl text-[10px] font-black uppercase tracking-widest focus:outline-none shadow-sm cursor-pointer"
                    >
                        <option value="ALL">All Accounts</option>
                        {accounts.map(a => <option key={a} value={a}>{a}</option>)}
                    </select>
                </div>
            </div>
        </div>

        <div className="divide-y divide-gray-50">
            {displayedList.map(t => (
                <div 
                    key={t.id} 
                    onClick={() => setSelectedTransaction(t)}
                    className={`p-6 md:px-10 flex flex-col md:flex-row justify-between items-start md:items-center gap-4 transition-all cursor-pointer hover:bg-primary/5 group ${t.isArchived ? 'opacity-60 bg-gray-50/50 grayscale-[0.5]' : ''}`}
                >
                    <div className="flex items-center gap-6 flex-1">
                        <div className={`text-center min-w-[60px] p-2 rounded-2xl ${t.isArchived ? 'bg-gray-200' : 'bg-gray-50'}`}>
                            <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest leading-none">{new Date(t.date).toLocaleString('default', { month: 'short' })}</p>
                            <p className="text-xl font-black text-gray-900 leading-none mt-1">{new Date(t.date).getDate()}</p>
                        </div>
                        <div>
                            <div className="flex items-center gap-2 mb-1">
                                <span className={`text-[8px] font-black px-2 py-0.5 rounded-full uppercase tracking-widest ${
                                    t.isArchived ? 'bg-gray-400 text-white' :
                                    t.type === TransactionType.INCOME ? 'bg-emerald-100 text-emerald-800' :
                                    t.type === TransactionType.EXPENSE ? 'bg-rose-100 text-rose-800' : 'bg-blue-100 text-blue-800'
                                }`}>{t.isArchived ? 'ARCHIVED' : t.type}</span>
                                <span className="text-[10px] font-bold text-gray-400 uppercase tracking-widest">{t.accountId}</span>
                            </div>
                            <h4 className={`font-bold leading-tight ${t.isArchived ? 'text-gray-500' : 'text-gray-800'}`}>{t.category}</h4>
                            {t.notes && <p className="text-xs text-gray-400 mt-1 italic line-clamp-1">{t.notes}</p>}
                        </div>
                    </div>
                    <div className="flex items-center gap-6 w-full md:w-auto justify-between md:justify-end">
                        <div className="text-right">
                            <p className={`text-xl font-black tracking-tighter ${
                                t.isArchived ? 'text-gray-500' :
                                t.type === TransactionType.INCOME ? 'text-emerald-600' : 'text-rose-600'
                            }`}>
                                {t.type === TransactionType.EXPENSE ? '-' : ''}{formatCurrency(t.amount)}
                            </p>
                        </div>
                        <ChevronRight className={`transition-all group-hover:translate-x-1 ${t.isArchived ? 'text-gray-300' : 'text-gray-300 group-hover:text-primary'}`} size={20} />
                    </div>
                </div>
            ))}
            {displayedList.length === 0 && (
                <div className="py-24 text-center">
                   <FileText size={48} className="mx-auto text-gray-100 mb-4" />
                   <p className="text-gray-400 font-bold italic">No records match your criteria.</p>
                </div>
            )}
            {filteredList.length > itemsPerPage && (
                <div className="p-6 text-center border-t border-gray-50">
                    <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest">
                        Showing {displayedList.length} of {filteredList.length} records
                    </p>
                </div>
            )}
        </div>
      </div>

      {/* Detail Modal with Functional Archive Button */}
      {selectedTransaction && (
          <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-gray-950/70 backdrop-blur-md animate-in fade-in duration-300">
              <div className="bg-white rounded-[2.5rem] shadow-[0_35px_60px_-15px_rgba(0,0,0,0.5)] w-full max-w-xl overflow-hidden animate-in zoom-in-95 duration-300">
                  <div className={`p-8 md:p-10 border-b border-gray-50 flex justify-between items-start ${
                      selectedTransaction.isArchived ? 'bg-gray-100' :
                      selectedTransaction.type === TransactionType.INCOME ? 'bg-emerald-50/50' :
                      selectedTransaction.type === TransactionType.EXPENSE ? 'bg-rose-50/50' : 'bg-blue-50/50'
                  }`}>
                      <div className="flex-1">
                          <div className="flex items-center gap-2 mb-2">
                             <span className="px-3 py-1 bg-white/80 rounded-full text-[9px] font-black uppercase tracking-widest text-gray-500 shadow-sm">Audit Certificate</span>
                             {selectedTransaction.isArchived && <span className="px-3 py-1 bg-gray-900 text-white text-[9px] font-black rounded-full uppercase tracking-widest">Locked Archive</span>}
                          </div>
                          <h3 className="text-3xl font-black text-gray-900 tracking-tighter leading-none">{selectedTransaction.category}</h3>
                      </div>
                      <button onClick={() => setSelectedTransaction(null)} className="p-3 bg-white/80 hover:bg-white rounded-2xl transition-all text-gray-400 hover:text-gray-900 shadow-sm active:scale-90">
                          <X size={24} />
                      </button>
                  </div>

                  <div className="p-8 md:p-10 space-y-8 overflow-y-auto max-h-[60vh] no-scrollbar">
                      <div className="flex flex-col items-center justify-center py-8 bg-gray-50/50 rounded-[2rem] border border-gray-100 relative overflow-hidden">
                          {selectedTransaction.isArchived && (
                             <div className="absolute inset-0 flex items-center justify-center opacity-[0.03] pointer-events-none">
                                <Archive size={200} />
                             </div>
                          )}
                          <span className={`text-6xl font-black tracking-tighter relative z-10 ${
                             selectedTransaction.isArchived ? 'text-gray-400' :
                             selectedTransaction.type === TransactionType.INCOME ? 'text-emerald-600' : 'text-rose-600'
                          }`}>
                              {selectedTransaction.type === TransactionType.EXPENSE ? '-' : ''}
                              {formatCurrency(selectedTransaction.amount)}
                          </span>
                          <span className="text-[10px] font-black text-gray-400 mt-4 uppercase tracking-[0.2em] relative z-10">
                            {selectedTransaction.isArchived ? 'ARCHIVED VALUATION' : `${selectedTransaction.type} SETTLEMENT`}
                          </span>
                      </div>

                      <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                          <div className="flex items-start gap-4 p-4 rounded-2xl bg-gray-50/30 border border-gray-50">
                              <div className="p-3 bg-white rounded-xl text-primary shadow-sm"><Calendar size={20}/></div>
                              <div>
                                  <p className="text-[9px] font-black text-gray-400 uppercase tracking-widest mb-1">Fiscal Date</p>
                                  <p className="font-bold text-gray-900">{new Date(selectedTransaction.date).toLocaleDateString('en-GB', { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' })}</p>
                              </div>
                          </div>
                          <div className="flex items-start gap-4 p-4 rounded-2xl bg-gray-50/30 border border-gray-50">
                              <div className="p-3 bg-white rounded-xl text-primary shadow-sm"><CreditCard size={20}/></div>
                              <div>
                                  <p className="text-[9px] font-black text-gray-400 uppercase tracking-widest mb-1">Payment Method</p>
                                  <p className="font-bold text-gray-900">{selectedTransaction.accountId}</p>
                              </div>
                          </div>
                          {selectedTransaction.recipient && (
                            <div className="flex items-start gap-4 p-4 rounded-2xl bg-gray-50/30 border border-gray-50">
                                <div className="p-3 bg-white rounded-xl text-primary shadow-sm"><User size={20}/></div>
                                <div>
                                    <p className="text-[9px] font-black text-gray-400 uppercase tracking-widest mb-1">Counterparty</p>
                                    <p className="font-bold text-gray-900">{selectedTransaction.recipient}</p>
                                </div>
                            </div>
                          )}
                          <div className="flex items-start gap-4 p-4 rounded-2xl bg-gray-50/30 border border-gray-50 md:col-span-2">
                              <div className="p-3 bg-white rounded-xl text-primary shadow-sm"><FileText size={20}/></div>
                              <div className="flex-1">
                                  <p className="text-[9px] font-black text-gray-400 uppercase tracking-widest mb-1">Official Notes</p>
                                  <p className="font-medium text-gray-700 leading-relaxed text-sm italic">"{selectedTransaction.notes || 'No remarks provided for this entry.'}"</p>
                              </div>
                          </div>
                      </div>
                  </div>

                  <div className="p-8 md:p-10 border-t border-gray-50 bg-gray-50/50">
                      {!selectedTransaction.isArchived ? (
                          <button 
                              onClick={() => handleArchive(selectedTransaction.id)}
                              className="w-full flex items-center justify-center gap-3 px-8 py-5 bg-white border-2 border-rose-100 text-rose-600 text-xs font-black uppercase tracking-[0.2em] rounded-2xl hover:bg-rose-600 hover:text-white hover:border-rose-600 transition-all shadow-xl active:scale-95"
                          >
                              <Archive size={20} /> Archive this record
                          </button>
                      ) : (
                          <div className="p-5 bg-gray-900 rounded-[1.5rem] text-center">
                            <p className="text-[10px] font-black text-white uppercase tracking-[0.3em] opacity-80 leading-relaxed mb-1">Static Archived Data</p>
                            <p className="text-[9px] text-gray-400 font-bold italic">Restore this item from the Settings &gt; Archives menu if needed.</p>
                          </div>
                      )}
                      <button 
                        onClick={() => setSelectedTransaction(null)}
                        className="w-full mt-4 text-[10px] font-black text-gray-400 uppercase tracking-widest hover:text-gray-900 transition-colors"
                      >
                        Exit Detailed View
                      </button>
                  </div>
              </div>
          </div>
      )}
    </div>
  );
};

