import React, { useState } from 'react';
import { Category, User, Transaction } from '../types';
import { Trash2, Plus, RefreshCw, Archive, Search, FileText, Edit2, Check, X } from 'lucide-react';
import { formatCurrency } from '../utils';

interface SettingsProps {
  categories: Category[];
  users: User[];
  archivedTransactions: Transaction[];
  onAddCategory: (c: Category) => void;
  onEditCategory: (c: Category) => void;
  onDeleteCategory: (id: string) => void;
  onRestoreTransaction: (id: string) => void;
}

const Settings: React.FC<SettingsProps> = ({ 
  categories, 
  users, 
  archivedTransactions, 
  onAddCategory, 
  onEditCategory,
  onDeleteCategory,
  onRestoreTransaction 
}) => {
  const [activeSection, setActiveSection] = useState<'CATEGORIES' | 'USERS' | 'ARCHIVE'>('CATEGORIES');
  const [newCatName, setNewCatName] = useState('');
  const [newCatType, setNewCatType] = useState<'INCOME' | 'EXPENSE' | 'BOTH'>('EXPENSE');
  const [archiveSearch, setArchiveSearch] = useState('');

  // Editing state
  const [editingId, setEditingId] = useState<string | null>(null);
  const [editName, setEditName] = useState('');
  const [editType, setEditType] = useState<'INCOME' | 'EXPENSE' | 'BOTH'>('EXPENSE');

  const handleAddCategory = () => {
    if (!newCatName) return;
    onAddCategory({
        id: Math.random().toString(36).substr(2, 9),
        name: newCatName,
        type: newCatType
    });
    setNewCatName('');
  };

  const startEditing = (cat: Category) => {
    setEditingId(cat.id);
    setEditName(cat.name);
    setEditType(cat.type);
  };

  const cancelEditing = () => {
    setEditingId(null);
    setEditName('');
    setEditType('EXPENSE');
  };

  const saveEditing = () => {
    if (editingId && editName) {
      onEditCategory({
        id: editingId,
        name: editName,
        type: editType
      });
      cancelEditing();
    }
  };

  const navItems = [
      { id: 'CATEGORIES', label: 'Categories' },
      { id: 'USERS', label: 'Users' },
      { id: 'ARCHIVE', label: 'Archives' },
  ];

  const filteredArchive = archivedTransactions.filter(t => 
    t.category.toLowerCase().includes(archiveSearch.toLowerCase()) || 
    t.notes?.toLowerCase().includes(archiveSearch.toLowerCase())
  ).sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());

  return (
    <div className="bg-white rounded-[2rem] shadow-xl shadow-gray-200/50 border border-gray-100 min-h-[600px] flex flex-col md:flex-row overflow-hidden">
      {/* Sidebar Navigation */}
      <div className="w-full md:w-64 border-b md:border-b-0 md:border-r border-gray-100 bg-gray-50/50">
        <div className="p-8 hidden md:block">
            <h2 className="text-xl font-black text-gray-900 tracking-tighter uppercase">Vault Settings</h2>
            <p className="text-[9px] font-black text-gray-400 mt-1 uppercase tracking-widest">Configuration Panel</p>
        </div>
        <div className="flex md:flex-col overflow-x-auto no-scrollbar p-3 md:p-4 md:pt-0 gap-2">
            {navItems.map(item => (
                <button 
                    key={item.id}
                    onClick={() => setActiveSection(item.id as any)}
                    className={`flex-1 min-w-[120px] md:w-full text-center md:text-left px-5 py-4 rounded-2xl transition-all text-xs font-black uppercase tracking-widest whitespace-nowrap ${
                        activeSection === item.id 
                        ? 'bg-primary text-white shadow-lg shadow-primary/20' 
                        : 'text-gray-500 hover:bg-white hover:shadow-sm'
                    }`}
                >
                    {item.label}
                </button>
            ))}
        </div>
      </div>

      {/* Content Area */}
      <div className="flex-1 p-6 md:p-10 overflow-y-auto max-h-[calc(100vh-250px)] md:max-h-none">

        {/* --- CATEGORIES SECTION --- */}
        {activeSection === 'CATEGORIES' && (
            <div className="space-y-8 animate-in fade-in duration-500">
                <div className="flex justify-between items-end border-b border-gray-100 pb-4">
                    <div>
                        <h3 className="text-2xl font-black text-gray-900 tracking-tighter uppercase">Classification Matrix</h3>
                        <p className="text-sm font-medium text-gray-400 mt-1">Manage financial categories and tagging.</p>
                    </div>
                </div>

                <div className="flex flex-col xl:flex-row gap-4 items-stretch xl:items-end bg-gray-50 p-6 rounded-[2rem] border border-gray-200 shadow-inner">
                    <div className="flex-1">
                        <label className="text-[10px] font-black text-gray-400 mb-2 block uppercase tracking-widest">New Category Name</label>
                        <input 
                            type="text" 
                            className="w-full p-4 border border-gray-100 rounded-2xl text-sm font-bold focus:ring-4 focus:ring-primary/10 outline-none shadow-sm" 
                            value={newCatName}
                            onChange={(e) => setNewCatName(e.target.value)}
                            placeholder="e.g. Outreach Support"
                        />
                    </div>
                    <div className="w-full xl:w-48">
                         <label className="text-[10px] font-black text-gray-400 mb-2 block uppercase tracking-widest">Accounting Type</label>
                         <select 
                            className="w-full p-4 border border-gray-100 rounded-2xl text-sm font-bold focus:ring-4 focus:ring-primary/10 outline-none shadow-sm bg-white cursor-pointer"
                            value={newCatType}
                            onChange={(e) => setNewCatType(e.target.value as any)}
                        >
                            <option value="EXPENSE">EXPENSE ONLY</option>
                            <option value="INCOME">INCOME ONLY</option>
                            <option value="BOTH">DUAL MODALITY</option>
                         </select>
                    </div>
                    <button 
                        onClick={handleAddCategory}
                        className="bg-primary text-white p-4 rounded-2xl hover:bg-teal-800 transition-all shadow-xl shadow-primary/20 flex justify-center items-center active:scale-95"
                    >
                        <Plus size={24} />
                    </button>
                </div>

                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                    {categories.map(cat => (
                        <div key={cat.id} className="flex justify-between items-center p-5 border border-gray-100 rounded-2xl hover:bg-gray-50 transition-all bg-white shadow-sm group min-h-[88px]">
                            {editingId === cat.id ? (
                                <div className="flex flex-1 items-center gap-3 animate-in fade-in duration-200">
                                    <input 
                                        type="text" 
                                        value={editName}
                                        onChange={(e) => setEditName(e.target.value)}
                                        className="flex-1 p-2 border border-gray-200 rounded-xl text-sm font-bold focus:ring-2 focus:ring-primary/20 outline-none"
                                        autoFocus
                                    />
                                    <select 
                                        value={editType}
                                        onChange={(e) => setEditType(e.target.value as any)}
                                        className="p-2 border border-gray-200 rounded-xl text-xs font-black uppercase tracking-widest bg-white outline-none focus:ring-2 focus:ring-primary/20"
                                    >
                                        <option value="EXPENSE">EXPENSE</option>
                                        <option value="INCOME">INCOME</option>
                                        <option value="BOTH">BOTH</option>
                                    </select>
                                    <div className="flex gap-2">
                                        <button onClick={saveEditing} className="p-2 bg-emerald-50 text-emerald-600 rounded-xl hover:bg-emerald-100 transition-colors">
                                            <Check size={18} />
                                        </button>
                                        <button onClick={cancelEditing} className="p-2 bg-gray-50 text-gray-400 rounded-xl hover:bg-gray-100 transition-colors">
                                            <X size={18} />
                                        </button>
                                    </div>
                                </div>
                            ) : (
                                <>
                                    <div>
                                        <span className="font-bold text-gray-800 block text-sm">{cat.name}</span>
                                        <span className={`text-[9px] px-2 py-0.5 rounded-lg uppercase font-black tracking-widest mt-1 inline-block ${
                                            cat.type === 'INCOME' ? 'bg-emerald-100 text-emerald-800' :
                                            cat.type === 'EXPENSE' ? 'bg-rose-100 text-rose-800' : 'bg-blue-100 text-blue-800'
                                        }`}>{cat.type}</span>
                                    </div>
                                    <div className="flex items-center gap-2 opacity-100 md:opacity-0 group-hover:opacity-100 transition-opacity">
                                        <button onClick={() => startEditing(cat)} className="text-gray-400 hover:text-primary p-2 hover:bg-primary/5 rounded-xl transition-all">
                                            <Edit2 size={18} />
                                        </button>
                                        <button onClick={() => onDeleteCategory(cat.id)} className="text-gray-400 hover:text-rose-600 p-2 hover:bg-rose-50 rounded-xl transition-all">
                                            <Trash2 size={18} />
                                        </button>
                                    </div>
                                </>
                            )}
                        </div>
                    ))}
                </div>
            </div>
        )}

        {/* --- USERS SECTION --- */}
        {activeSection === 'USERS' && (
             <div className="space-y-8 animate-in fade-in duration-500">
                 <div className="flex justify-between items-end border-b border-gray-100 pb-4">
                    <div>
                        <h3 className="text-2xl font-black text-gray-900 tracking-tighter uppercase">Personnel Directory</h3>
                        <p className="text-sm font-medium text-gray-400 mt-1">Authorized ministry finance representatives.</p>
                    </div>
                 </div>

                 <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
                     {users.map(user => (
                         <div key={user.id} className="p-6 border border-gray-100 rounded-[2rem] bg-gray-50 flex items-center justify-between shadow-sm">
                             <div className="flex items-center gap-4">
                                <div className="h-14 w-14 rounded-2xl bg-primary/10 text-primary flex items-center justify-center font-black text-xl">
                                    {user.name.charAt(0)}
                                </div>
                                <div>
                                    <p className="font-black text-gray-900 tracking-tight">{user.name}</p>
                                    <p className="text-xs text-gray-500 font-medium">{user.email}</p>
                                    <p className="text-[10px] text-gray-400 font-bold mt-1 uppercase tracking-widest">{user.phone}</p>
                                </div>
                             </div>
                             <span className="px-3 py-1 bg-white border border-gray-200 text-gray-500 rounded-lg text-[9px] font-black uppercase tracking-widest">
                                 {user.role}
                             </span>
                         </div>
                     ))}
                 </div>
                 <div className="bg-gray-950 p-10 rounded-[2.5rem] text-center shadow-2xl">
                     <p className="text-[10px] font-black text-gray-500 uppercase tracking-[0.4em] mb-4">Centralized Auth Protocol</p>
                     <p className="text-white text-sm font-bold tracking-tight">Cloud user synchronization is managed by the Global Administrator.</p>
                 </div>
             </div>
        )}

        {/* --- ARCHIVE SECTION --- */}
        {activeSection === 'ARCHIVE' && (
            <div className="space-y-8 animate-in fade-in duration-500">
                <div className="flex flex-col lg:flex-row justify-between items-start lg:items-end border-b border-gray-100 pb-6 gap-6">
                    <div>
                        <h3 className="text-2xl font-black text-gray-900 tracking-tighter uppercase">Financial Archives</h3>
                        <p className="text-sm font-medium text-gray-400 mt-1">Audit log of deactivated ministry transactions.</p>
                    </div>
                    <div className="relative w-full lg:w-72">
                        <Search className="absolute left-4 top-4 text-gray-400" size={18} />
                        <input 
                            type="text" 
                            placeholder="Search archives..." 
                            className="pl-12 pr-6 py-4 w-full bg-gray-50 border border-gray-100 rounded-2xl text-sm font-bold focus:outline-none focus:ring-4 focus:ring-primary/5 transition-all"
                            value={archiveSearch}
                            onChange={(e) => setArchiveSearch(e.target.value)}
                        />
                    </div>
                </div>

                {filteredArchive.length === 0 ? (
                    <div className="flex flex-col items-center justify-center py-24 bg-gray-50/50 rounded-[3rem] border-2 border-dashed border-gray-100 text-gray-300">
                         <Archive size={64} className="mb-4 opacity-20" />
                         <p className="font-black uppercase tracking-widest text-xs">No records in vault</p>
                    </div>
                ) : (
                    <div className="space-y-4">
                        {filteredArchive.map(t => (
                            <div key={t.id} className="p-6 border border-gray-100 rounded-[2rem] bg-white shadow-sm flex flex-col md:flex-row justify-between items-start md:items-center gap-6 hover:shadow-md transition-all">
                                <div className="flex items-center gap-6 flex-1">
                                    <div className="p-4 bg-gray-50 rounded-2xl text-center min-w-[70px]">
                                        <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest">{new Date(t.date).toLocaleString('default', { month: 'short' })}</p>
                                        <p className="text-lg font-black text-gray-900">{new Date(t.date).getDate()}</p>
                                    </div>
                                    <div>
                                        <h4 className="font-black text-gray-800 tracking-tight">{t.category}</h4>
                                        <p className="text-xs text-gray-400 font-medium mt-1 line-clamp-1 italic">{t.notes || 'No remarks recorded.'}</p>
                                        <div className="flex gap-2 mt-2">
                                            <span className="text-[9px] font-black uppercase tracking-widest text-gray-400 bg-gray-100 px-2 py-0.5 rounded-lg">{t.accountId}</span>
                                            <span className="text-[9px] font-black uppercase tracking-widest text-rose-400 bg-rose-50 px-2 py-0.5 rounded-lg">Archived</span>
                                        </div>
                                    </div>
                                </div>
                                <div className="flex flex-col md:items-end gap-3 w-full md:w-auto pt-4 md:pt-0 border-t md:border-t-0 border-gray-50">
                                    <p className="text-xl font-black text-gray-900 tracking-tighter">{formatCurrency(t.amount)}</p>
                                    <button 
                                        onClick={() => {
                                            if (window.confirm('Restore this transaction to active balances?')) {
                                                onRestoreTransaction(t.id);
                                            }
                                        }}
                                        className="w-full md:w-auto flex items-center justify-center gap-2 px-6 py-3 bg-primary text-white hover:bg-teal-800 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all shadow-lg shadow-primary/20 active:scale-95"
                                    >
                                        <RefreshCw size={14} /> Restore Item
                                    </button>
                                </div>
                            </div>
                        ))}
                    </div>
                )}

                {archivedTransactions.length > 0 && (
                    <div className="p-8 bg-gray-100 rounded-[2.5rem] border border-gray-200">
                        <div className="flex items-center gap-4 mb-4">
                            <div className="p-2 bg-white rounded-xl text-gray-400"><FileText size={20}/></div>
                            <h4 className="font-black text-gray-900 uppercase tracking-widest text-xs">Retention Policy</h4>
                        </div>
                        <p className="text-xs font-medium text-gray-500 leading-relaxed">
                            Archived records are maintained for audit purposes but are excluded from primary overview dashboards and active liquidity calculations. Total Archived Value: <span className="font-bold text-gray-800">{formatCurrency(archivedTransactions.reduce((acc, t) => acc + t.amount, 0))}</span>.
                        </p>
                    </div>
                )}
            </div>
        )}
      </div>
    </div>
  );
};

export default Settings;

import React, { useState } from 'react';
import { LayoutDashboard, Receipt, Settings as SettingsIcon, PieChart, Menu, X, ChevronLeft, ChevronRight } from 'lucide-react';
import { Transaction, Category, User, AccountType } from './types';
import { INITIAL_TRANSACTIONS, INITIAL_CATEGORIES, INITIAL_USERS } from './utils';

import Overview from './components/Overview';
import Transactions from './components/Transactions';
import Reports from './components/Reports';
import Settings from './components/Settings';

function App() {
  const [transactions, setTransactions] = useState<Transaction[]>(INITIAL_TRANSACTIONS);
  const [categories, setCategories] = useState<Category[]>(INITIAL_CATEGORIES);
  const [users, setUsers] = useState<User[]>(INITIAL_USERS);
  const [activeView, setActiveView] = useState<'OVERVIEW' | 'TRANSACTIONS' | 'REPORTS' | 'SETTINGS'>('OVERVIEW');

  // Sidebar states
  const [isSidebarCollapsed, setIsSidebarCollapsed] = useState(false);
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);

  const [preSelectedAccount, setPreSelectedAccount] = useState<AccountType | null>(null);

  const handleAccountFilter = (account: AccountType | null) => {
    setPreSelectedAccount(account);
    setActiveView('TRANSACTIONS');
  };

  const addTransaction = (t: Omit<Transaction, 'id'>) => {
    const newT = { ...t, id: Math.random().toString(36).substr(2, 9) };
    setTransactions(prev => [newT, ...prev]);
  };

  const deleteTransaction = (id: string) => {
    setTransactions(prev => prev.map(t => t.id === id ? { ...t, isArchived: true } : t));
  };

  const restoreTransaction = (id: string) => {
    setTransactions(prev => prev.map(t => t.id === id ? { ...t, isArchived: false } : t));
  };

  const addCategory = (c: Category) => {
    setCategories(prev => [...prev, c]);
  };

  const editCategory = (updatedCategory: Category) => {
    setCategories(prev => prev.map(c => c.id === updatedCategory.id ? updatedCategory : c));
  };

  const deleteCategory = (id: string) => {
    setCategories(prev => prev.filter(c => c.id !== id));
  };

  const navItems = [
    { id: 'OVERVIEW', label: 'Overview', icon: LayoutDashboard },
    { id: 'TRANSACTIONS', label: 'Transactions', icon: Receipt },
    { id: 'REPORTS', label: 'Generate Reports', icon: PieChart },
    { id: 'SETTINGS', label: 'Settings', icon: SettingsIcon },
  ];

  return (
    <div className="flex min-h-screen bg-gray-50 font-sans text-slate-900">

      {/* Sidebar (Desktop & Tablet) */}
      <aside 
        className={`hidden md:flex flex-col bg-white border-r border-gray-200 fixed h-full z-20 transition-all duration-300 ease-in-out shadow-sm ${
          isSidebarCollapsed ? 'w-20' : 'w-64'
        }`}
      >
        <div className="p-4 border-b border-gray-100 flex items-center justify-between h-16">
          {!isSidebarCollapsed && (
            <div className="animate-in fade-in slide-in-from-left-2 duration-300">
              <h1 className="text-lg font-black text-primary leading-tight tracking-tighter uppercase">Thesaurus</h1>
            </div>
          )}
          <button 
            onClick={() => setIsSidebarCollapsed(!isSidebarCollapsed)}
            className="p-2 hover:bg-gray-100 rounded-xl text-gray-400 transition-all mx-auto active:scale-90"
          >
            {isSidebarCollapsed ? <ChevronRight size={20} /> : <ChevronLeft size={20} />}
          </button>
        </div>

        <nav className="flex-1 p-3 space-y-2 mt-4">
          {navItems.map(item => (
            <button
              key={item.id}
              onClick={() => setActiveView(item.id as any)}
              className={`w-full flex items-center gap-3 px-3 py-3 rounded-2xl transition-all group relative ${
                activeView === item.id 
                  ? 'bg-primary text-white shadow-lg shadow-primary/20' 
                  : 'text-gray-400 hover:bg-gray-50 hover:text-primary'
              }`}
            >
              <item.icon size={22} className="min-w-[22px]" />
              {!isSidebarCollapsed && (
