                    />
                </div>

                <div className="flex gap-2 overflow-x-auto no-scrollbar w-full md:w-auto items-center">
                    {/* Date Range Filter */}
                    <div className="flex items-center gap-2 bg-white border border-gray-100 rounded-2xl px-3 py-2 shadow-sm h-[58px]">
                        <CalendarRange size={18} className="text-gray-400 shrink-0" />
                        <div className="flex flex-col sm:flex-row items-center gap-1 sm:gap-2">
                             <input 
                                type="date" 
                                value={dateRange.start}
                                onChange={(e) => setDateRange({...dateRange, start: e.target.value})}
                                className="text-[10px] font-bold uppercase tracking-widest text-gray-600 outline-none w-24 sm:w-auto bg-transparent cursor-pointer"
                                placeholder="Start"
                            />
                            <span className="text-gray-300 hidden sm:inline">-</span>
                            <input 
                                type="date" 
                                value={dateRange.end}
                                onChange={(e) => setDateRange({...dateRange, end: e.target.value})}
                                className="text-[10px] font-bold uppercase tracking-widest text-gray-600 outline-none w-24 sm:w-auto bg-transparent cursor-pointer"
                                placeholder="End"
                            />
                        </div>
                        {(dateRange.start || dateRange.end) && (
                            <button onClick={() => setDateRange({start:'', end:''})} className="text-rose-500 hover:bg-rose-50 p-1 rounded-full"><X size={14}/></button>
                        )}
                    </div>

                    <button
                        onClick={() => setShowArchived(!showArchived)}
                        className={`flex items-center gap-2 px-5 h-[58px] rounded-2xl text-[10px] font-black uppercase tracking-widest border transition-all shadow-md whitespace-nowrap ${
                            showArchived ? 'bg-gray-900 text-white border-gray-900' : 'bg-white text-gray-500 border-gray-100 hover:bg-gray-50'
                        }`}
                        title={showArchived ? "Hide Archived Items" : "Show Archived Items"}
                    >
                        {showArchived ? <EyeOff size={18} /> : <Eye size={18} />}
                        <span className="hidden xl:inline">{showArchived ? 'Active Only' : 'Inc. Archived'}</span>
                    </button>

                    {/* Limit Selection Dropdown */}
                    <div className="relative h-[58px]">
                        <ListFilter className="absolute left-4 top-5 text-gray-400" size={18} />
                        <select 
                            value={itemsPerPage}
                            onChange={(e) => setItemsPerPage(Number(e.target.value))}
                            className="pl-10 pr-8 h-full bg-white border border-gray-100 rounded-2xl text-[10px] font-black uppercase tracking-widest focus:outline-none shadow-sm cursor-pointer appearance-none min-w-[120px]"
                        >
                            <option value={25}>Show 25</option>
                            <option value={50}>Show 50</option>
                            <option value={100}>Show 100</option>
                            <option value={-1}>Show All</option>
                        </select>
                    </div>

                    <select 
                        value={filterAccount}
                        onChange={(e) => setFilterAccount(e.target.value)}
                        className="h-[58px] px-5 bg-white border border-gray-100 rounded-2xl text-[10px] font-black uppercase tracking-widest focus:outline-none shadow-sm cursor-pointer min-w-[140px]"
                    >
                        <option value="ALL">All Accounts</option>
                        {accounts.map(a => <option key={a} value={a}>{a}</option>)}
