import React, { useState, useMemo } from 'react';
import { Transaction, AccountType, TransactionType, Period } from '../types';
import { formatCurrency } from '../utils';
import { AreaChart, Area, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, Legend } from 'recharts';
import { TrendingUp, TrendingDown, Wallet, CreditCard, Banknote } from 'lucide-react';

interface OverviewProps {
  transactions: Transaction[];
  onFilterAccount: (account: AccountType | null) => void;
  selectedYear: number;
  onYearChange: (year: number) => void;
}

const Overview: React.FC<OverviewProps> = ({ transactions, onFilterAccount, selectedYear, onYearChange }) => {
  const [graphPeriod, setGraphPeriod] = useState<'WEEK' | 'QUARTER' | 'YEAR'>('YEAR');

  const availableYears = useMemo(() => {
    const years = new Set<number>(transactions.map(t => new Date(t.date).getFullYear()));
    years.add(new Date().getFullYear());
    return Array.from(years).sort((a, b) => b - a);
  }, [transactions]);

  const filteredTransactions = useMemo(() => {
    return transactions.filter(t => !t.isArchived && new Date(t.date).getFullYear() === selectedYear);
  }, [transactions, selectedYear]);

  const calculateBalance = (account?: AccountType) => {
    return filteredTransactions.reduce((acc, t) => {
      if (t.type === TransactionType.TRANSFER) {
        if (!account) return acc;
        if (t.accountId === account) return acc - t.amount;
        if (t.toAccountId === account) return acc + t.amount;
        return acc;
      }
      if (account && t.accountId !== account) return acc;
      if (t.type === TransactionType.INCOME) return acc + t.amount;
      if (t.type === TransactionType.EXPENSE) return acc - t.amount;
      return acc;
    }, 0);
  };

  const totals = useMemo(() => {
    const income = filteredTransactions
      .filter(t => t.type === TransactionType.INCOME)
      .reduce((acc, t) => acc + t.amount, 0);
    const expense = filteredTransactions
      .filter(t => t.type === TransactionType.EXPENSE)
      .reduce((acc, t) => acc + t.amount, 0);
    return { income, expense, balance: income - expense };
  }, [filteredTransactions]);

  const chartData = useMemo(() => {
    const data: Record<string, { name: string; income: number; expense: number }> = {};
    filteredTransactions.forEach(t => {
      let key = '';
      const date = new Date(t.date);
      if (graphPeriod === 'YEAR') {
        key = date.toLocaleString('default', { month: 'short' });
      } else if (graphPeriod === 'QUARTER') {
        const q = Math.floor((date.getMonth() + 3) / 3);
        key = `Q${q}`;
      } else {
        const firstDay = new Date(date.setDate(date.getDate() - date.getDay()));
        key = `${firstDay.getDate()}/${firstDay.getMonth()+1}`;
      }
      if (!data[key]) data[key] = { name: key, income: 0, expense: 0 };
      if (t.type === TransactionType.INCOME) data[key].income += t.amount;
      if (t.type === TransactionType.EXPENSE) data[key].expense += t.amount;
    });
    return Object.values(data);
  }, [filteredTransactions, graphPeriod]);

  return (
    <div className="space-y-6">
      <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center bg-white p-4 rounded-xl shadow-sm border border-gray-100 gap-4">
        <h2 className="text-2xl font-bold text-gray-800">Overview</h2>
        <div className="flex items-center gap-2 w-full sm:w-auto">
            <span className="text-sm text-gray-500 whitespace-nowrap">Year:</span>
            <select 
                className="bg-gray-50 border border-gray-200 rounded-md p-2 text-sm focus:ring-primary focus:border-primary w-full sm:w-auto cursor-pointer"
                value={selectedYear}
                onChange={(e) => onYearChange(Number(e.target.value))}
            >
                {availableYears.map(y => <option key={y} value={y}>{y}</option>)}
            </select>
        </div>
      </div>

      {/* Snippets - Improved Grid for Tablets (sm:grid-cols-2) */}
      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-4">
        <div className="bg-emerald-50 p-6 rounded-xl border border-emerald-100 flex items-center justify-between shadow-sm">
          <div>
            <p className="text-emerald-600 font-medium text-xs sm:text-sm uppercase tracking-wider">Total Income</p>
            <p className="text-xl sm:text-2xl font-bold text-emerald-900 mt-1">{formatCurrency(totals.income)}</p>
          </div>
          <div className="p-3 bg-white rounded-full text-emerald-600 shadow-sm">
            <TrendingUp size={24} />
          </div>
        </div>
        <div className="bg-rose-50 p-6 rounded-xl border border-rose-100 flex items-center justify-between shadow-sm">
          <div>
            <p className="text-rose-600 font-medium text-xs sm:text-sm uppercase tracking-wider">Total Expenses</p>
            <p className="text-xl sm:text-2xl font-bold text-rose-900 mt-1">{formatCurrency(totals.expense)}</p>
          </div>
          <div className="p-3 bg-white rounded-full text-rose-600 shadow-sm">
            <TrendingDown size={24} />
          </div>
        </div>
        <div className="bg-blue-50 p-6 rounded-xl border border-blue-100 flex items-center justify-between shadow-sm sm:col-span-2 lg:col-span-1">
          <div>
            <p className="text-blue-600 font-medium text-xs sm:text-sm uppercase tracking-wider">Net Balance</p>
            <p className={`text-xl sm:text-2xl font-bold mt-1 ${totals.balance >= 0 ? 'text-blue-900' : 'text-rose-700'}`}>
                {formatCurrency(totals.balance)}
            </p>
          </div>
          <div className="p-3 bg-white rounded-full text-blue-600 shadow-sm">
            <Wallet size={24} />
          </div>
        </div>
      </div>

      {/* Account Cards - Improved Grid for Tablets */}
      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-4">
        {[AccountType.MOMO, AccountType.CASH, AccountType.OTHER].map((acc) => (
          <button
            key={acc}
            onClick={() => onFilterAccount(acc)}
            className="group relative overflow-hidden bg-white p-6 rounded-xl shadow-sm border border-gray-200 hover:shadow-md transition-all text-left active:scale-95 duration-200"
          >
            <div className="absolute top-0 right-0 p-4 opacity-10 group-hover:opacity-20 transition-opacity">
                {acc === AccountType.MOMO ? <CreditCard size={64} /> : acc === AccountType.CASH ? <Banknote size={64} /> : <Wallet size={64} />}
            </div>
            <h3 className="text-gray-500 font-medium text-sm truncate pr-8">{acc}</h3>
            <p className="text-xl font-bold text-gray-800 mt-2">{formatCurrency(calculateBalance(acc))}</p>
            <span className="text-xs text-primary mt-2 inline-block font-medium">Click to view transactions &rarr;</span>
          </button>
        ))}
      </div>

      {/* Balance History Graph */}
      <div className="bg-white p-4 sm:p-6 rounded-xl shadow-sm border border-gray-200">
        <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center mb-6 gap-4">
            <h3 className="text-lg font-bold text-gray-800">Financial History</h3>
            <div className="flex bg-gray-100 rounded-lg p-1 w-full sm:w-auto">
                {(['WEEK', 'QUARTER', 'YEAR'] as const).map((p) => (
                    <button
                        key={p}
                        onClick={() => setGraphPeriod(p)}
                        className={`flex-1 sm:flex-none px-3 py-1.5 text-xs rounded-md font-medium transition-colors ${
                            graphPeriod === p ? 'bg-white text-primary shadow-sm' : 'text-gray-500 hover:text-gray-700'
                        }`}
                    >
                        {p}
                    </button>
                ))}
            </div>
        </div>
        <div className="h-64 sm:h-72 w-full">
            <ResponsiveContainer width="100%" height="100%">
                <AreaChart data={chartData}>
                    <defs>
                        <linearGradient id="colorIncome" x1="0" y1="0" x2="0" y2="1">
                            <stop offset="5%" stopColor="#10b981" stopOpacity={0.1}/>
                            <stop offset="95%" stopColor="#10b981" stopOpacity={0}/>
                        </linearGradient>
                        <linearGradient id="colorExpense" x1="0" y1="0" x2="0" y2="1">
                            <stop offset="5%" stopColor="#f43f5e" stopOpacity={0.1}/>
                            <stop offset="95%" stopColor="#f43f5e" stopOpacity={0}/>
                        </linearGradient>
                    </defs>
                    <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f0f0f0" />
                    <XAxis dataKey="name" axisLine={false} tickLine={false} tick={{fill: '#9ca3af', fontSize: 12}} dy={10} />
                    <YAxis axisLine={false} tickLine={false} tick={{fill: '#9ca3af', fontSize: 12}} />
                    <Tooltip 
                        contentStyle={{ borderRadius: '8px', border: 'none', boxShadow: '0 4px 6px -1px rgb(0 0 0 / 0.1)' }}
                        formatter={(value: number) => formatCurrency(value)}
                    />
                    <Legend iconType="circle" />
                    <Area type="monotone" dataKey="income" stroke="#10b981" strokeWidth={2} fillOpacity={1} fill="url(#colorIncome)" name="Income" />
                    <Area type="monotone" dataKey="expense" stroke="#f43f5e" strokeWidth={2} fillOpacity={1} fill="url(#colorExpense)" name="Expenses" />
                </AreaChart>
            </ResponsiveContainer>
        </div>
      </div>
    </div>
  );
};

export default Overview;

import React, { useState, useEffect } from 'react';
import { Transaction, TransactionType, AccountType, Category } from '../types';
import { formatCurrency } from '../utils';
import { Search, Plus, Save, X, Archive, ArrowRight, Calendar, CreditCard, User, FileText, ChevronRight, Eye, EyeOff, ListFilter, Info } from 'lucide-react';

interface TransactionsProps {
  transactions: Transaction[];
  categories: Category[];
  accounts: AccountType[];
  preSelectedAccount: AccountType | null;
  onAddTransaction: (t: Omit<Transaction, 'id'> | Omit<Transaction, 'id'>[]) => void;
  onDeleteTransaction: (id: string) => void;
  filterYear: number;
}

type TabType = 'INCOME' | 'EXPENSE' | 'TRANSFER';

const Transactions: React.FC<TransactionsProps> = ({ 
  transactions, 
  categories, 
  accounts, 
  preSelectedAccount,
  onAddTransaction,
  onDeleteTransaction,
  filterYear
}) => {
  const [activeTab, setActiveTab] = useState<TabType>('INCOME');
  const [filterAccount, setFilterAccount] = useState<string>(preSelectedAccount || 'ALL');
  const [searchTerm, setSearchTerm] = useState('');
  const [showArchived, setShowArchived] = useState(false);
  const [selectedTransaction, setSelectedTransaction] = useState<Transaction | null>(null);

  // New state for limiting entries, -1 means Show All
  const [itemsPerPage, setItemsPerPage] = useState<number>(25);

  const [entries, setEntries] = useState<any[]>([{ 
    amount: '', 
    date: new Date().toISOString().split('T')[0],
    category: '',
    accountId: '',
    toAccountId: '',
    recipient: '',
    notes: '',
    receivedFromFinance: false
  }]);

  useEffect(() => {
    if (preSelectedAccount) setFilterAccount(preSelectedAccount);
  }, [preSelectedAccount]);

  const handleAddEntry = () => {
    setEntries([...entries, { 
      amount: '', 
      date: new Date().toISOString().split('T')[0],
      category: '',
      accountId: '',
      toAccountId: '',
      recipient: '',
      notes: '',
      receivedFromFinance: false
    }]);
  };

  const handleRemoveEntry = (index: number) => {
    if (entries.length > 1) {
      setEntries(entries.filter((_, i) => i !== index));
    }
  };

  const updateEntry = (index: number, field: string, value: any) => {
    const newEntries = [...entries];
    newEntries[index] = { ...newEntries[index], [field]: value };
    setEntries(newEntries);
  };

  const validateAndSave = () => {
    for (let i = 0; i < entries.length; i++) {
        const entry = entries[i];
        const rowNum = i + 1;

        if (!entry.amount || Number(entry.amount) <= 0) {
            alert(`Row ${rowNum}: Please enter a valid amount.`);
            return;
        }
        if (!entry.date) {
            alert(`Row ${rowNum}: Please select a date.`);
            return;
        }
        if (!entry.category) {
            alert(`Row ${rowNum}: Please select a category.`);
            return;
        }
        if (!entry.accountId) {
            alert(`Row ${rowNum}: Please select an account.`);
            return;
        }

        // Transfer specific validation
        if (activeTab === 'TRANSFER') {
            if (!entry.toAccountId) {
                alert(`Row ${rowNum}: Please select a destination account for the transfer.`);
                return;
            }
            if (entry.accountId === entry.toAccountId) {
                alert(`Row ${rowNum}: Source and Destination accounts cannot be the same.`);
                return;
            }
        }
    }

    const batchToAdd: Omit<Transaction, 'id'>[] = [];

    entries.forEach(entry => {
      batchToAdd.push({
        date: entry.date,
        amount: Number(entry.amount),
        type: activeTab === 'INCOME' ? TransactionType.INCOME : activeTab === 'EXPENSE' ? TransactionType.EXPENSE : TransactionType.TRANSFER,
        category: entry.category,
        accountId: entry.accountId,
        toAccountId: activeTab === 'TRANSFER' ? entry.toAccountId : undefined,
        recipient: entry.recipient,
        notes: entry.notes,
        isArchived: false,
        meta: {
            receivedFromFinance: entry.receivedFromFinance
        }
      });
    });

    onAddTransaction(batchToAdd);

    setEntries([{ 
      amount: '', 
      date: new Date().toISOString().split('T')[0],
      category: '',
      accountId: '',
      toAccountId: '',
      recipient: '',
      notes: '',
      receivedFromFinance: false
    }]);
    alert('Transaction(s) saved successfully!');
  };

  // Archive Functionality
  const handleArchive = (id: string) => {
      // Direct call to delete/archive without window.confirm to ensure it works on all devices
      onDeleteTransaction(id); 
      setSelectedTransaction(null); // Close the detail modal
  };

  // 1. Filter Logic
  const filteredList = transactions
    .filter(t => showArchived ? true : !t.isArchived)
    .filter(t => new Date(t.date).getFullYear() === filterYear)
    .filter(t => filterAccount === 'ALL' || t.accountId === filterAccount || t.toAccountId === filterAccount)
    .filter(t => 
      t.category.toLowerCase().includes(searchTerm.toLowerCase()) || 
      t.notes?.toLowerCase().includes(searchTerm.toLowerCase()) ||
      t.recipient?.toLowerCase().includes(searchTerm.toLowerCase())
    )
    .sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());

  // 2. Pagination/Limit Logic
  const displayedList = itemsPerPage === -1 ? filteredList : filteredList.slice(0, itemsPerPage);

  return (
    <div className="space-y-6">
      {/* Entry Form Card */}
      <div className="bg-white rounded-[2rem] shadow-xl shadow-gray-200/50 border border-gray-100 overflow-hidden">
        <div className="flex border-b border-gray-100 overflow-x-auto no-scrollbar bg-gray-50/30">
          {(['INCOME', 'EXPENSE', 'TRANSFER'] as TabType[]).map(tab => (
            <button
              key={tab}
              onClick={() => setActiveTab(tab)}
              className={`flex-1 min-w-[100px] py-6 text-[10px] font-black tracking-widest transition-all outline-none relative uppercase ${
                activeTab === tab 
                  ? tab === 'INCOME' ? 'text-emerald-600' : tab === 'EXPENSE' ? 'text-rose-600' : 'text-blue-600'
                  : 'text-gray-400 hover:text-gray-600'
              }`}
            >
              {tab}
              {activeTab === tab && (
                <div className={`absolute bottom-0 left-0 right-0 h-1 mx-8 rounded-t-full animate-in slide-in-from-bottom-2 duration-300 ${
                  tab === 'INCOME' ? 'bg-emerald-500' : tab === 'EXPENSE' ? 'bg-rose-500' : 'bg-blue-500'
                }`} />
              )}
            </button>
          ))}
        </div>

        <div className="p-6 md:p-10">
          <div className="space-y-6">
            {entries.map((entry, index) => (
              <div key={index} className="relative p-6 md:p-8 bg-gray-50/50 rounded-3xl border border-gray-200 space-y-6 shadow-inner group transition-all hover:bg-white hover:shadow-lg">
                {entries.length > 1 && (
                    <button onClick={() => handleRemoveEntry(index)} className="absolute top-4 right-4 text-gray-300 hover:text-rose-500 z-10 p-2 bg-white rounded-2xl shadow-sm border border-gray-100 hover:scale-110 transition-all">
                        <X size={18} />
                    </button>
                )}

                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
                  <div>
                    <label className="block text-[10px] font-black text-gray-400 mb-2 uppercase tracking-widest">Entry Date</label>
                    <input 
                        type="date" 
                        value={entry.date}
                        onChange={(e) => updateEntry(index, 'date', e.target.value)}
                        className="w-full rounded-2xl border-gray-100 shadow-sm focus:ring-4 focus:ring-primary/10 focus:border-primary p-3.5 border text-sm font-bold outline-none"
                    />
                  </div>
                  <div>
                    <label className="block text-[10px] font-black text-gray-400 mb-2 uppercase tracking-widest">GHC Amount</label>
                    <input 
                        type="number" 
                        placeholder="0.00"
                        value={entry.amount}
                        onChange={(e) => updateEntry(index, 'amount', e.target.value)}
                        className="w-full rounded-2xl border-gray-100 shadow-sm focus:ring-4 focus:ring-primary/10 focus:border-primary p-3.5 border text-sm font-bold outline-none"
                    />
                  </div>

                  <div className="md:col-span-2">
                      <label className="block text-[10px] font-black text-gray-400 mb-2 uppercase tracking-widest">Classification</label>
                      <select 
                          value={entry.category}
                          onChange={(e) => updateEntry(index, 'category', e.target.value)}
                          className="w-full rounded-2xl border-gray-100 shadow-sm focus:ring-4 focus:ring-primary/10 focus:border-primary p-3.5 border text-sm font-bold outline-none bg-white cursor-pointer"
                      >
                          <option value="">Select Category...</option>
                          {categories
                              .filter(c => c.type === 'BOTH' || (activeTab !== 'TRANSFER' && c.type === activeTab))
                              .map(c => <option key={c.id} value={c.name}>{c.name}</option>)}
                      </select>
                  </div>
                </div>

                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                   <div>
                        <label className="block text-[10px] font-black text-gray-400 mb-2 uppercase tracking-widest">
                            {activeTab === 'TRANSFER' ? 'Source Account' : 'Account Type'}
                        </label>
                        <select 
                            value={entry.accountId}
                            onChange={(e) => updateEntry(index, 'accountId', e.target.value)}
                            className="w-full rounded-2xl border-gray-100 shadow-sm focus:ring-4 focus:ring-primary/10 focus:border-primary p-3.5 border text-sm font-bold outline-none bg-white cursor-pointer"
                        >
                            <option value="">Select Account...</option>
                            {accounts.map(a => <option key={a} value={a}>{a}</option>)}
                        </select>
                   </div>
                   {activeTab === 'TRANSFER' ? (
                       <div>
                            <label className="block text-[10px] font-black text-gray-400 mb-2 uppercase tracking-widest">Destination</label>
                            <select 
                                value={entry.toAccountId}
                                onChange={(e) => updateEntry(index, 'toAccountId', e.target.value)}
                                className="w-full rounded-2xl border-gray-100 shadow-sm focus:ring-4 focus:ring-primary/10 focus:border-primary p-3.5 border text-sm font-bold outline-none bg-white cursor-pointer"
                            >
                                <option value="">To Account...</option>
                                {accounts.map(a => <option key={a} value={a}>{a}</option>)}
                            </select>
                       </div>
                   ) : (
                       <div>
                           <label className="block text-[10px] font-black text-gray-400 mb-2 uppercase tracking-widest">Recipient (Optional)</label>
                           <input 
                                type="text"
                                placeholder="Name"
                                value={entry.recipient}
                                onChange={(e) => updateEntry(index, 'recipient', e.target.value)}
                                className="w-full rounded-2xl border-gray-100 shadow-sm focus:ring-4 focus:ring-primary/10 focus:border-primary p-3.5 border text-sm font-bold outline-none"
                            />
                       </div>
                   )}
                </div>
              </div>
