              {/* Weekly Input Section */}
              <div className="grid grid-cols-1 xl:grid-cols-2 gap-6 sm:gap-8">
                {/* Income Inputs */}
                <div className="bg-white border-2 border-emerald-50 rounded-3xl sm:rounded-[2.5rem] shadow-xl shadow-emerald-900/5 p-5 sm:p-8">
                  <div className="flex items-center gap-3 sm:gap-4 mb-6 sm:mb-8">
                    <div className="p-3 bg-emerald-50 rounded-2xl text-emerald-600"><Plus size={24}/></div>
                    <h3 className="font-black text-emerald-900 uppercase tracking-widest text-sm">Sunday Collections</h3>
