                          />
                          {offeringsInput.length > 1 && (
                            <button onClick={() => handleRemoveOfferingInput(idx)} className="p-3 sm:p-4 bg-rose-50 text-rose-500 rounded-xl sm:rounded-2xl hover:bg-rose-100 transition-all">
                              <Trash2 size={20} />
