                {/* Planning Inputs */}
                <div className="bg-white border-2 border-primary/5 rounded-3xl sm:rounded-[2.5rem] shadow-xl shadow-primary/5 p-5 sm:p-8">
                  <div className="flex items-center gap-3 sm:gap-4 mb-6 sm:mb-8">
                    <div className="p-3 bg-primary/5 rounded-2xl text-primary"><PieChart size={24}/></div>
                    <h3 className="font-black text-primary uppercase tracking-widest text-sm">Plan Next Week</h3>
                  </div>
                  <div className="space-y-4">
                    {planInput.map((entry, idx) => (
                      <div key={idx} className="flex flex-col sm:flex-row gap-3">
                        <input 
                          type="text" 
                          placeholder="Item Description"
                          className="p-3 sm:p-4 border border-gray-100 rounded-xl sm:rounded-2xl text-sm font-bold flex-1 outline-none focus:ring-4 focus:ring-primary/10"
                          value={entry.item}
                          onChange={(e) => {
