                            n[idx].item = e.target.value;
                            setPlanInput(n);
                          }}
                        />
                        <div className="flex gap-2 w-full sm:w-auto">
                          <input 
                            type="number" 
                            placeholder="Cost"
                            className="p-3 sm:p-4 border border-gray-100 rounded-xl sm:rounded-2xl text-sm font-bold w-full sm:w-28 outline-none focus:ring-4 focus:ring-primary/10"
                            value={entry.cost}
                            onChange={(e) => {
                              const n = [...planInput];
                              n[idx].cost = e.target.value;
                              setPlanInput(n);
                            }}
                          />
                          {planInput.length > 1 && (
                            <button onClick={() => handleRemovePlanInput(idx)} className="p-3 sm:p-4 bg-rose-50 text-rose-500 rounded-xl sm:rounded-2xl hover:bg-rose-100 transition-all">
                              <Trash2 size={20} />
                            </button>
                          )}
                        </div>
                      </div>
                    ))}
                    <button onClick={handleAddPlanInput} className="text-[10px] font-black text-primary uppercase tracking-widest flex items-center gap-2 hover:underline">
                      <Plus size={16}/> Add planned item
                    </button>
                  </div>
