              </div>

              <div className="flex justify-center xl:justify-end">
                <button 
                  onClick={saveWeeklyData}
                  className="w-full sm:w-auto px-12 py-5 bg-primary text-white text-xs font-black uppercase tracking-[0.2em] rounded-[2rem] shadow-2xl shadow-primary/40 hover:bg-teal-800 hover:scale-105 active:scale-95 transition-all"
                >
                  <Save size={20} className="inline mr-3"/> Commit Weekly Report
                </button>
