                                            </div>
                                            <div>
                                                <label className="text-[10px] font-black text-gray-400 mb-1 block uppercase tracking-widest">Amount</label>
                                                <input 
                                                    type="number" 
                                                    className="w-full p-3 border border-gray-200 rounded-xl text-sm font-bold outline-none focus:ring-2 focus:ring-primary/20"
                                                    value={editTransData.amount}
                                                    onChange={(e) => setEditTransData({...editTransData, amount: parseFloat(e.target.value)})}
                                                />
                                            </div>
                                            <div>
                                                <label className="text-[10px] font-black text-gray-400 mb-1 block uppercase tracking-widest">Category</label>
                                                <select 
                                                    className="w-full p-3 border border-gray-200 rounded-xl text-sm font-bold outline-none focus:ring-2 focus:ring-primary/20 bg-white"
                                                    value={editTransData.category}
                                                    onChange={(e) => setEditTransData({...editTransData, category: e.target.value})}
                                                >
                                                    {categories.map(c => <option key={c.id} value={c.name}>{c.name}</option>)}
                                                </select>
                                            </div>
                                        </div>
                                        <div>
                                            <label className="text-[10px] font-black text-gray-400 mb-1 block uppercase tracking-widest">Notes</label>
                                            <input 
                                                type="text" 
                                                className="w-full p-3 border border-gray-200 rounded-xl text-sm font-bold outline-none focus:ring-2 focus:ring-primary/20"
