                            </div>
                            <h4 className="text-xl font-black text-gray-900 tracking-tight mb-2">Restore Database</h4>
                            <p className="text-xs text-gray-500 leading-relaxed">
                                Overwrite your current application state with a previously exported backup file. 
                            </p>
                            <div className="mt-4 p-4 bg-rose-50 border border-rose-100 rounded-2xl flex gap-3 items-start">
                                <AlertTriangle size={18} className="text-rose-500 mt-0.5 shrink-0"/>
