                                accept=".json"
                                onChange={handleImportFile}
                                className="absolute inset-0 w-full h-full opacity-0 cursor-pointer z-10"
                             />
                             <button className="w-full py-4 bg-white border-2 border-gray-200 text-gray-600 rounded-2xl text-xs font-black uppercase tracking-widest hover:border-gray-300 hover:bg-gray-50 transition-all flex items-center justify-center gap-3">
                                <Upload size={16} /> Select Backup File
                            </button>
                        </div>
                    </div>
                </div>
            </div>
        )}
      </div>
    </div>
  );
};

