                        <div className="bg-white p-6 sm:p-8 rounded-[2.5rem] shadow-xl shadow-gray-100 border border-gray-100">
                            <h4 className="text-sm font-black text-gray-900 uppercase tracking-widest mb-6 flex items-center gap-2"><TrendingUp size={16} className="text-primary"/> Financial Trend Analysis</h4>
                            <div className="h-[300px] w-full">
                                <ResponsiveContainer width="100%" height="100%">
                                    <BarChart data={analyticalData.chartData} barSize={20}>
                                        <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f3f4f6" />
                                        <XAxis dataKey="name" axisLine={false} tickLine={false} tick={{fill: '#9ca3af', fontSize: 10}} dy={10} />
                                        <YAxis axisLine={false} tickLine={false} tick={{fill: '#9ca3af', fontSize: 10}} />
                                        <Tooltip contentStyle={{ borderRadius: '12px', border: 'none', boxShadow: '0 10px 15px -3px rgb(0 0 0 / 0.1)' }} formatter={(value: number) => formatCurrency(value)} cursor={{fill: '#f9fafb'}} />
                                        <Legend iconType="circle" wrapperStyle={{paddingTop: '20px'}} />
                                        <Bar dataKey="income" name="Income" fill="#10b981" radius={[4, 4, 0, 0]} />
                                        <Bar dataKey="expense" name="Expenses" fill="#f43f5e" radius={[4, 4, 0, 0]} />
                                    </BarChart>
                                </ResponsiveContainer>
                            </div>
                        </div>

                        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                            <div className="bg-white p-6 sm:p-8 rounded-[2.5rem] shadow-xl shadow-gray-100 border border-gray-100">
                                 <h4 className="text-xs font-black text-emerald-700 uppercase tracking-widest mb-6 flex items-center gap-2"><Target size={16}/> Top Income Sources</h4>
                                <div className="space-y-6">
                                    {analyticalData.topIncome.map((item, idx) => (
                                        <div key={idx} className="space-y-2">
                                            <div className="flex justify-between items-center text-sm"><span className="font-bold text-gray-700">{item.name}</span><span className="font-black text-emerald-600">{formatCurrency(item.value)}</span></div>
                                            <div className="h-2 w-full bg-emerald-50 rounded-full overflow-hidden"><div className="h-full bg-emerald-500 rounded-full transition-all duration-1000" style={{ width: `${(item.value / analyticalData.totalIncome) * 100}%` }}/></div>
                                        </div>
                                    ))}
                                    {analyticalData.topIncome.length === 0 && <p className="text-gray-400 text-xs italic">No income data available.</p>}
                                </div>
                            </div>
                            <div className="bg-white p-6 sm:p-8 rounded-[2.5rem] shadow-xl shadow-gray-100 border border-gray-100">
                                 <h4 className="text-xs font-black text-rose-700 uppercase tracking-widest mb-6 flex items-center gap-2"><Target size={16}/> Top Cost Drivers</h4>
                                <div className="space-y-6">
                                    {analyticalData.topExpense.map((item, idx) => (
                                        <div key={idx} className="space-y-2">
                                            <div className="flex justify-between items-center text-sm"><span className="font-bold text-gray-700">{item.name}</span><span className="font-black text-rose-600">{formatCurrency(item.value)}</span></div>
                                            <div className="h-2 w-full bg-rose-50 rounded-full overflow-hidden"><div className="h-full bg-rose-500 rounded-full transition-all duration-1000" style={{ width: `${(item.value / analyticalData.totalExpense) * 100}%` }}/></div>
                                        </div>
                                    ))}
                                    {analyticalData.topExpense.length === 0 && <p className="text-gray-400 text-xs italic">No expense data available.</p>}
                                </div>
                            </div>
                        </div>
                    </>
                )}
             </div>
          )}
        </div>
      </div>

      {/* Cash Request Modal */}
      {isRequestModalOpen && (
          <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-gray-950/70 backdrop-blur-sm animate-in fade-in duration-300">
              <div className="bg-white rounded-[2.5rem] shadow-2xl w-full max-w-md overflow-hidden animate-in zoom-in-95 duration-300">
                  <div className="p-8 bg-rose-50/50 border-b border-rose-100">
                      <div className="flex items-center gap-3 mb-2">
                          <div className="p-2 bg-rose-100 rounded-full text-rose-600"><AlertTriangle size={20}/></div>
                          <h3 className="text-xl font-black text-rose-900 uppercase tracking-tight">Cash Deficit Detected</h3>
                      </div>
                      <p className="text-rose-700 text-sm font-medium">
                          You need <span className="font-black">{formatCurrency(Math.abs(weeklyStats.cashBalance))}</span> to cover expenses.
                      </p>
                  </div>
                  <div className="p-8 space-y-6">
                      <div>
                          <label className="text-[10px] font-black text-gray-400 mb-2 block uppercase tracking-widest">Request From (Finance)</label>
                          <div className="relative">
                              <UserIcon size={16} className="absolute left-4 top-4 text-gray-400" />
                              <input 
                                  list="finance-reps"
                                  className="w-full p-4 pl-12 bg-gray-50 border border-gray-100 rounded-2xl text-sm font-bold outline-none focus:ring-4 focus:ring-primary/10"
                                  placeholder="Select or Type Name..."
                                  value={selectedFinanceRep}
                                  onChange={(e) => setSelectedFinanceRep(e.target.value)}
                              />
                              <datalist id="finance-reps">
                                  {users.filter(u => u.role === 'FINANCE_REP' || u.role === 'ADMIN').map(u => (
                                      <option key={u.id} value={u.name} />
                                  ))}
                              </datalist>
                          </div>
                      </div>

                      <div>
                          <label className="text-[10px] font-black text-gray-400 mb-2 block uppercase tracking-widest">Send MoMo To (Beneficiary)</label>
                          <div className="space-y-3">
                                <div className="relative">
                                    <UserIcon size={16} className="absolute left-4 top-4 text-gray-400" />
                                    <input 
                                        list="beneficiaries"
                                        className="w-full p-4 pl-12 bg-gray-50 border border-gray-100 rounded-2xl text-sm font-bold outline-none focus:ring-4 focus:ring-primary/10"
                                        placeholder="Select or Type Name..."
                                        value={selectedBeneficiary}
                                        onChange={(e) => handleBeneficiarySelect(e.target.value)}
                                    />
                                    <datalist id="beneficiaries">
                                        {users.map(u => (
                                            <option key={u.id} value={u.name} />
                                        ))}
                                    </datalist>
                                </div>
                                <input 
                                    type="text"
                                    className="w-full p-4 bg-gray-50 border border-gray-100 rounded-2xl text-sm font-bold outline-none focus:ring-4 focus:ring-primary/10"
                                    placeholder="MoMo Number"
                                    value={beneficiaryNumber}
                                    onChange={(e) => setBeneficiaryNumber(e.target.value)}
                                />
                          </div>
                      </div>

                      <button 
                          onClick={generateAndOpenWhatsApp}
                          disabled={!selectedFinanceRep || !selectedBeneficiary || !beneficiaryNumber}
                          className="w-full py-4 bg-[#25D366] text-white rounded-2xl text-xs font-black uppercase tracking-widest hover:bg-[#128C7E] transition-all shadow-xl active:scale-95 disabled:opacity-50 disabled:cursor-not-allowed flex items-center justify-center gap-2"
                      >
                          <Send size={16} /> Generate Request
                      </button>

                      <button 
                        onClick={() => setIsRequestModalOpen(false)}
                        className="w-full py-3 text-gray-400 text-[10px] font-black uppercase tracking-widest hover:text-gray-600"
                      >
                          Cancel
                      </button>
                  </div>
              </div>
          </div>
      )}
    </div>
  );
};

export default Reports;

import React, { useState, useEffect, useDeferredValue, useMemo } from 'react';
import { Category, User, Transaction, AccountType, TransactionType } from '../types';
import { Trash2, Plus, RefreshCw, Archive, Search, FileText, Edit2, Check, X, AlertTriangle, Database, Download, Upload, Cloud, Lock, Key, Shield, UserPlus, Power, Eye, EyeOff, Smartphone, BookOpen, Map, Activity, GitMerge, Share2, Layers, ShieldCheck } from 'lucide-react';
import { formatCurrency } from '../utils';

interface SettingsProps {
  transactions: Transaction[];
  categories: Category[];
  users: User[];
  archivedTransactions: Transaction[];
  onAddCategory: (c: Category) => void;
  onEditCategory: (c: Category) => void;
  onDeleteCategory: (id: string) => void;
  onRestoreTransaction: (id: string) => void;
  onPermanentlyDelete: (id: string) => void;
  onUpdateTransaction: (t: Transaction) => void;
  onImportData: (data: { transactions: Transaction[], categories: Category[], users: User[] }) => void;
  cloudConfig: { binId: string; apiKey: string };
  onUpdateCloudConfig: (binId: string, apiKey: string) => void;
  onUserAction: (action: 'ADD' | 'UPDATE' | 'DELETE', user: User) => void;
}

const ADMIN_PIN = '1234';

const Settings: React.FC<SettingsProps> = ({ 
  transactions,
  categories, 
  users, 
  archivedTransactions, 
  onAddCategory, 
  onEditCategory,
  onDeleteCategory,
  onRestoreTransaction,
  onPermanentlyDelete,
  onUpdateTransaction,
  onImportData,
  cloudConfig,
  onUpdateCloudConfig,
  onUserAction
}) => {
  const [activeSection, setActiveSection] = useState<'CATEGORIES' | 'USERS' | 'ARCHIVE' | 'CLOUD' | 'DOCS'>('CATEGORIES');
  const [newCatName, setNewCatName] = useState('');
  const [newCatType, setNewCatType] = useState<'INCOME' | 'EXPENSE' | 'BOTH'>('EXPENSE');

  const [archiveSearch, setArchiveSearch] = useState('');
  const deferredArchiveSearch = useDeferredValue(archiveSearch); // SMOOTH TYPING

  // Archive Editing
  const [isArchiveEditing, setIsArchiveEditing] = useState(false);
  const [archiveEditForm, setArchiveEditForm] = useState<Transaction | null>(null);

  // Cloud Config State
  const [tempBinId, setTempBinId] = useState(cloudConfig.binId);
  const [tempApiKey, setTempApiKey] = useState(cloudConfig.apiKey);
  const [isCloudUnlocked, setIsCloudUnlocked] = useState(false);
  const [adminPinInput, setAdminPinInput] = useState('');

  // User Management State
  const [isUserEditing, setIsUserEditing] = useState(false);
  const [selectedUser, setSelectedUser] = useState<User | null>(null);
  const [userForm, setUserForm] = useState<Partial<User>>({
      name: '', email: '', phone: '', role: 'VIEWER', status: 'ACTIVE', momoNumber: ''
  });

  // Category Editing state
  const [editingCatId, setEditingCatId] = useState<string | null>(null);
  const [editCatName, setEditCatName] = useState('');
  const [editCatType, setEditCatType] = useState<'INCOME' | 'EXPENSE' | 'BOTH'>('EXPENSE');

  // Transaction Editing State
  const [editingTransId, setEditingTransId] = useState<string | null>(null);
  const [editTransData, setEditTransData] = useState<Transaction | null>(null);

  useEffect(() => {
      // Sync props to temp state when unlocked
      if (isCloudUnlocked) {
          setTempBinId(cloudConfig.binId);
          setTempApiKey(cloudConfig.apiKey);
      }
  }, [cloudConfig, isCloudUnlocked]);

  const handleAddCategory = () => {
    if (!newCatName) return;
    onAddCategory({
        id: Math.random().toString(36).substr(2, 9),
        name: newCatName,
        type: newCatType
    });
    setNewCatName('');
  };

  const startEditingCat = (cat: Category) => {
    setEditingCatId(cat.id);
    setEditCatName(cat.name);
    setEditCatType(cat.type);
  };

  const cancelEditingCat = () => {
    setEditingCatId(null);
    setEditCatName('');
    setEditCatType('EXPENSE');
  };

  const saveEditingCat = () => {
    if (editingCatId && editCatName) {
      onEditCategory({
        id: editingCatId,
        name: editCatName,
        type: editCatType
      });
      cancelEditingCat();
    }
  };

  // Archive Edit Handlers
  const handleEditArchive = (t: Transaction) => {
      setArchiveEditForm({...t});
      setIsArchiveEditing(true);
  };

  const handleSaveArchiveEdit = () => {
      if(archiveEditForm) {
          onUpdateTransaction(archiveEditForm);
          setIsArchiveEditing(false);
          setArchiveEditForm(null);
      }
  };

  // Security & Cloud Logic
  const handleUnlockCloud = () => {
      if (adminPinInput === ADMIN_PIN) {
          setIsCloudUnlocked(true);
          setAdminPinInput('');
      } else {
          alert('Incorrect PIN');
      }
  };

  const handleSaveCloudConfig = () => {
      onUpdateCloudConfig(tempBinId, tempApiKey);
      setIsCloudUnlocked(false);
      alert('Credentials saved securely.');
  };

  // User Management Logic
  const handleOpenUserForm = (user?: User) => {
    if (!isCloudUnlocked) {
        const pin = prompt("Enter Admin PIN to manage users:");
        if (pin !== ADMIN_PIN) {
            alert("Access Denied");
            return;
        }
        setIsCloudUnlocked(true); // Temporarily unlock session for management
    }

    if (user) {
        setSelectedUser(user);
        setUserForm(user);
    } else {
        setSelectedUser(null);
        setUserForm({ name: '', email: '', phone: '', role: 'VIEWER', status: 'ACTIVE', momoNumber: '' });
    }
    setIsUserEditing(true);
  };

  const handleSaveUser = () => {
      if (!userForm.name || !userForm.role) return;

      if (selectedUser) {
          onUserAction('UPDATE', { ...selectedUser, ...userForm } as User);
      } else {
          onUserAction('ADD', userForm as User);
      }
      setIsUserEditing(false);
      setSelectedUser(null);
  };

  const handleExportData = () => {
      const dataStr = JSON.stringify({ transactions, categories, users }, null, 2);
      const blob = new Blob([dataStr], { type: 'application/json' });
      const url = URL.createObjectURL(blob);
      const link = document.createElement('a');
      link.href = url;
      link.download = `cm-finance_backup_${new Date().toISOString().split('T')[0]}.json`;
      document.body.appendChild(link);
      link.click();
      document.body.removeChild(link);
      URL.revokeObjectURL(url);
  };

  const handleImportFile = (e: React.ChangeEvent<HTMLInputElement>) => {
      const file = e.target.files?.[0];
      if (!file) return;

      const reader = new FileReader();
      reader.onload = (event) => {
          try {
              const result = event.target?.result as string;
              const parsed = JSON.parse(result);
              onImportData(parsed);
          } catch (err) {
              console.error(err);
              alert('Invalid file format. Please upload a valid Thesaurus backup file.');
          }
      };
      reader.readAsText(file);
      e.target.value = '';
  };

  const navItems = [
      { id: 'CATEGORIES', label: 'Categories' },
      { id: 'USERS', label: 'Users' },
      { id: 'ARCHIVE', label: 'Archives' },
      { id: 'CLOUD', label: 'Cloud Sync' },
      { id: 'DOCS', label: 'System Manual' },
  ];

  const filteredArchive = useMemo(() => {
    return archivedTransactions.filter(t => 
        t.category.toLowerCase().includes(deferredArchiveSearch.toLowerCase()) || 
        t.notes?.toLowerCase().includes(deferredArchiveSearch.toLowerCase())
    ).sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());
  }, [archivedTransactions, deferredArchiveSearch]);

  return (
    <div className="bg-white rounded-[2rem] shadow-xl shadow-gray-200/50 border border-gray-100 min-h-0 md:min-h-[600px] flex flex-col md:flex-row overflow-hidden">
      {/* Sidebar Navigation */}
      <div className="w-full md:w-64 border-b md:border-b-0 md:border-r border-gray-100 bg-gray-50/50 sticky top-0 z-10 md:static">
        <div className="p-8 hidden md:block">
            <h2 className="text-xl font-black text-gray-900 tracking-tighter uppercase">Vault Settings</h2>
            <p className="text-[9px] font-black text-gray-400 mt-1 uppercase tracking-widest">Configuration Panel</p>
        </div>
        <div className="flex md:flex-col flex-wrap justify-center p-3 md:p-4 md:pt-0 gap-2 bg-gray-50/50 backdrop-blur-sm">
            {navItems.map(item => (
                <button 
                    key={item.id}
                    onClick={() => setActiveSection(item.id as any)}
                    className={`min-w-[45%] md:w-full text-center md:text-left px-5 py-4 rounded-2xl transition-all text-xs font-black uppercase tracking-widest whitespace-nowrap ${
                        activeSection === item.id 
                        ? 'bg-primary text-white shadow-lg shadow-primary/20' 
                        : 'text-gray-500 hover:bg-white hover:shadow-sm'
                    }`}
                >
                    {item.label}
                </button>
            ))}
        </div>
      </div>

      {/* Content Area */}
      <div className="flex-1 p-4 md:p-10 max-h-[calc(100vh-100px)] overflow-y-auto custom-scrollbar">

        {/* --- CATEGORIES SECTION --- */}
        {activeSection === 'CATEGORIES' && (
            <div className="space-y-8 animate-in fade-in duration-500">
                <div className="flex justify-between items-end border-b border-gray-100 pb-4">
                    <div>
                        <h3 className="text-xl md:text-2xl font-black text-gray-900 tracking-tighter uppercase">Classification Matrix</h3>
                        <p className="text-xs md:text-sm font-medium text-gray-400 mt-1">Manage financial categories and tagging.</p>
                    </div>
                </div>

                <div className="flex flex-col xl:flex-row gap-4 items-stretch xl:items-end bg-gray-50 p-6 rounded-[2rem] border border-gray-200 shadow-inner">
                    <div className="flex-1">
                        <label className="text-[10px] font-black text-gray-400 mb-2 block uppercase tracking-widest">New Category Name</label>
                        <input 
                            type="text" 
                            className="w-full p-4 border border-gray-100 rounded-2xl text-sm font-bold focus:ring-4 focus:ring-primary/10 outline-none shadow-sm" 
                            value={newCatName}
                            onChange={(e) => setNewCatName(e.target.value)}
                            placeholder="e.g. Outreach Support"
                        />
                    </div>
                    <div className="w-full xl:w-48">
                         <label className="text-[10px] font-black text-gray-400 mb-2 block uppercase tracking-widest">Accounting Type</label>
                         <select 
                            className="w-full p-4 border border-gray-100 rounded-2xl text-sm font-bold focus:ring-4 focus:ring-primary/10 outline-none shadow-sm bg-white cursor-pointer"
                            value={newCatType}
                            onChange={(e) => setNewCatType(e.target.value as any)}
                        >
                            <option value="EXPENSE">EXPENSE ONLY</option>
                            <option value="INCOME">INCOME ONLY</option>
                            <option value="BOTH">DUAL MODALITY</option>
                         </select>
                    </div>
                    <button 
                        onClick={handleAddCategory}
                        className="bg-primary text-white p-4 rounded-2xl hover:bg-teal-800 transition-all shadow-xl shadow-primary/20 flex justify-center items-center active:scale-95"
                    >
