                                        <button onClick={() => onDeleteCategory(cat.id)} className="text-gray-400 hover:text-rose-600 p-2 hover:bg-rose-50 rounded-xl transition-all">
                                            <Trash2 size={18} />
                                        </button>
                                    </div>
                                </>
