import React, { useState, useEffect, useCallback } from 'react';
import { LayoutDashboard, Receipt, Settings as SettingsIcon, PieChart, ChevronLeft, ChevronRight, Cloud, CloudOff, Loader2, Check } from 'lucide-react';
